    .{ .name = "name", .type = .string },
};

const fs_p3_local_types = [_]ctypes.TypeDef{
    .{ .option = .{ .inner = .string } }, // 0: option<string>
    .{ .variant = .{ .cases = &fs_p3_error_code_cases } }, // 1: error-code
    .{ .variant = .{ .cases = &fs_p3_descriptor_type_cases } }, // 2: descriptor-type
    .{ .flags = .{ .names = &fs_p3_descriptor_flags_names } }, // 3: descriptor-flags
    .{ .record = .{ .fields = &fs_p3_instant_fields } }, // 4: instant
    .{ .option = .{ .inner = .{ .type_idx = 4 } } }, // 5: option<instant>
    .{ .record = .{ .fields = &fs_p3_descriptor_stat_fields } }, // 6: descriptor-stat
    .{ .record = .{ .fields = &fs_p3_metadata_hash_fields } }, // 7: metadata-hash-value
    .{ .record = .{ .fields = &fs_p3_directory_entry_fields } }, // 8: directory-entry
    .{ .result = .{ .ok = null, .err = .{ .variant = 1 } } }, // 9: result<_, error-code>
    .{ .result = .{ .ok = .{ .own = 0 }, .err = .{ .variant = 1 } } }, // 10: result<descriptor (own), error-code>
    .{ .result = .{ .ok = .{ .variant = 2 }, .err = .{ .variant = 1 } } }, // 11: result<descriptor-type, ...>
    .{ .result = .{ .ok = .{ .flags = 3 }, .err = .{ .variant = 1 } } }, // 12: result<descriptor-flags, ...>
    .{ .result = .{ .ok = .string, .err = .{ .variant = 1 } } }, // 13: result<string, ...>
    .{ .result = .{ .ok = .{ .record = 6 }, .err = .{ .variant = 1 } } }, // 14: result<descriptor-stat, ...>
    .{ .result = .{ .ok = .{ .record = 7 }, .err = .{ .variant = 1 } } }, // 15: result<metadata-hash-value, ...>
};

const FS_P3_ERROR_CODE_IDX: u32 = 1;
const FS_P3_DESCRIPTOR_TYPE_IDX: u32 = 2;
const FS_P3_DESCRIPTOR_FLAGS_IDX: u32 = 3;
const FS_P3_DESCRIPTOR_STAT_IDX: u32 = 6;
const FS_P3_METADATA_HASH_IDX: u32 = 7;
const FS_P3_DIRECTORY_ENTRY_IDX: u32 = 8;
const FS_P3_RESULT_UNIT_ERR_IDX: u32 = 9;
const FS_P3_RESULT_DESC_ERR_IDX: u32 = 10;
const FS_P3_RESULT_DESC_TYPE_ERR_IDX: u32 = 11;
const FS_P3_RESULT_DESC_FLAGS_ERR_IDX: u32 = 12;
const FS_P3_RESULT_STRING_ERR_IDX: u32 = 13;
const FS_P3_RESULT_DESC_STAT_ERR_IDX: u32 = 14;
const FS_P3_RESULT_METADATA_HASH_ERR_IDX: u32 = 15;

fn fsP3TypeRegistry() abi.TypeRegistry {
    return abi.TypeRegistry.fromTypes(&fs_p3_local_types);
}

/// Shape of an `async func` return on the 0.3 `wasi:filesystem/types`
/// surface. Each shape maps to a `ValType` resolvable in
/// `fs_p3_local_types`; `fsP3LowerAsyncPayload` consumes a fully-lifted
/// 0.2-shape `InterfaceValue` and writes its canonical lowering into a
/// heap-owned `[]u8` ready to install on `Future.payload`.
const FsP3AsyncReturn = enum {
    /// `result<_, error-code>`
    unit_err,
    /// `result<descriptor, error-code>` — `descriptor` is a u32 own-handle.
    desc_err,
    /// `result<descriptor-type, error-code>`
    desc_type_err,
    /// `result<descriptor-flags, error-code>`
    desc_flags_err,
    /// `result<string, error-code>`
    string_err,
    /// `result<descriptor-stat, error-code>` — the 0.2 sync body emits
    /// the `option<datetime>` timestamps with `.u64` seconds; this
    /// kind triggers a fixup to `.s64` (matching 0.3's `instant`).
    desc_stat_err,
    /// `result<metadata-hash-value, error-code>`
    metadata_hash_err,
    /// Bare `bool` — used by `is-same-object`.
    just_bool,

    pub fn valType(self: FsP3AsyncReturn) ctypes.ValType {
        return switch (self) {
            .unit_err => .{ .result = FS_P3_RESULT_UNIT_ERR_IDX },
            .desc_err => .{ .result = FS_P3_RESULT_DESC_ERR_IDX },
            .desc_type_err => .{ .result = FS_P3_RESULT_DESC_TYPE_ERR_IDX },
            .desc_flags_err => .{ .result = FS_P3_RESULT_DESC_FLAGS_ERR_IDX },
            .string_err => .{ .result = FS_P3_RESULT_STRING_ERR_IDX },
            .desc_stat_err => .{ .result = FS_P3_RESULT_DESC_STAT_ERR_IDX },
            .metadata_hash_err => .{ .result = FS_P3_RESULT_METADATA_HASH_ERR_IDX },
            .just_bool => .bool,
        };
    }
};

/// Fix-up the `option<datetime { u64 seconds, u32 nanoseconds }>` tag the
/// 0.2 sync body produced into `option<instant { s64 seconds, u32 nanoseconds }>`
/// for 0.3 canonical lowering. Operates in-place on the `result_val.ok`
/// payload of a `descriptor-stat` record. The seconds bits are
/// `@bitCast`-preserved so positive Unix timestamps survive the tag
/// transition unchanged.
fn fsP3FixupStatRecord(val: InterfaceValue) void {
    if (val != .result_val) return;
    if (!val.result_val.is_ok) return;
    const ok_ptr = val.result_val.payload orelse return;
    if (ok_ptr.* != .record_val) return;
    const rec = ok_ptr.record_val;
    if (rec.len < 6) return;
    inline for ([_]usize{ 3, 4, 5 }) |i| {
        fsP3FixupOptionalInstant(@constCast(&rec[i]));
    }
}

fn fsP3FixupOptionalInstant(val_ptr: *InterfaceValue) void {
    if (val_ptr.* != .option_val) return;
    if (!val_ptr.option_val.is_some) return;
    const some_ptr = val_ptr.option_val.payload orelse return;
    if (some_ptr.* != .record_val) return;
    const rec = some_ptr.record_val;
    if (rec.len < 1) return;
    // The 0.2 body writes `.u64` for the seconds field; reinterpret the
    // bit pattern as the signed `.s64` 0.3 spec expects.
    switch (rec[0]) {
        .u64 => |bits| @constCast(&rec[0]).* = .{ .s64 = @bitCast(bits) },
        else => {},
    }
}

/// Map a discriminant produced by the host's 0.2-shape `FsErrorCode`
/// enum into the 0.3 `variant error-code` discriminant position. The
/// 0.3 spec dropped the `would-block` case (which sat at position 1 in
/// 0.2), shifting every subsequent case down by one. Sockets has the
/// same shape via `socketCodeToP3Disc`. (#564.)
///
/// Internal `would_block` (`= 1`) maps to 0.3 `busy` (`= 3`) — the
/// closest semantic equivalent for a "transient retry" error on a
/// filesystem operation.
fn fsCodeToP3Disc(p2_disc: u32) u32 {
    if (p2_disc == 0) return 0; // access stays
    if (p2_disc == 1) return 3; // would_block → busy (closest 0.3 equivalent)
    return p2_disc - 1; // already (2)..cross_device (36) shift down by one
}

/// Walk the `result<_, error-code>` shape and transcode the err-arm
/// discriminant from the host's 0.2 enum to the 0.3 variant via
/// `fsCodeToP3Disc`. The ok arm and non-variant err payloads (none
/// produced by the current host fns) are left untouched. (#564.)
fn fsP3FixupErrCode(val: InterfaceValue) void {
    if (val != .result_val) return;
    if (val.result_val.is_ok) return;
    const err_ptr = val.result_val.payload orelse return;
    if (err_ptr.* != .variant_val) return;
    const p2 = err_ptr.variant_val.discriminant;
    @constCast(err_ptr).variant_val.discriminant = fsCodeToP3Disc(p2);
}

/// Map a discriminant produced by the host's 0.2-shape `DescType`
/// enum into the 0.3 `variant descriptor-type` discriminant. The 0.2
/// enum had `unknown=0` at the head; the 0.3 spec drops it and
/// introduces an `other(option<string>)` case at the tail. Each
/// 0.2 case 1..7 shifts down by one; `unknown` maps to `other` (with
/// no payload — see `fsP3FixupDescType`). (#564.)
fn descTypeToP3Disc(p2_disc: u32) u32 {
    if (p2_disc == 0) return 7; // unknown → other(none)
    return p2_disc - 1; // block_device..socket shift down by one
}

/// Walk a `result<descriptor-type, error-code>` shape and transcode
/// the ok-arm `descriptor-type` variant discriminant from the host's
/// 0.2 enum to the 0.3 variant. Also descends into a
/// `descriptor-stat` record (field 0 is the descriptor-type) for the
/// `.desc_stat_err` shape. (#564.)
fn fsP3FixupDescType(val: InterfaceValue) void {
    if (val != .result_val) return;
    if (!val.result_val.is_ok) return;
    const ok_ptr = val.result_val.payload orelse return;
    if (ok_ptr.* != .variant_val) return;
    const p2 = ok_ptr.variant_val.discriminant;
    @constCast(ok_ptr).variant_val.discriminant = descTypeToP3Disc(p2);
}

fn fsP3FixupDescStatType(val: InterfaceValue) void {
    if (val != .result_val) return;
    if (!val.result_val.is_ok) return;
    const ok_ptr = val.result_val.payload orelse return;
    if (ok_ptr.* != .record_val) return;
    const rec = ok_ptr.record_val;
    if (rec.len < 1) return;
    if (rec[0] != .variant_val) return;
    const p2 = rec[0].variant_val.discriminant;
    @constCast(&rec[0]).variant_val.discriminant = descTypeToP3Disc(p2);
}

/// Lower a fully-lifted `InterfaceValue` into a heap-owned byte buffer
/// using the canonical ABI layout for `kind`'s `ValType`. The returned
/// slice is owned by `allocator` and is suitable for installation on
/// `async_mod.Future.payload`; the executor's `future_read` arm will
/// memcpy it into the guest's destination pointer at rendezvous time.
///
/// For `result<_, error-code>` (`.unit_err`), the 0.2 sync bodies
/// conventionally fabricate an empty-tuple `ok` payload — that payload
/// is irrelevant on the 0.3 wire (the ok arm is unit) and is stripped
/// before lowering so `storeValReg` doesn't try to lower a non-existent
/// ok type.
fn fsP3LowerAsyncPayload(
    allocator: Allocator,
    kind: FsP3AsyncReturn,
    val: InterfaceValue,
) ![]u8 {
    const reg = fsP3TypeRegistry();
    const vt = kind.valType();
    const size = abi.sizeOfType(reg, vt);
    if (size == 0) return error.LowerError;
    const buf = try allocator.alloc(u8, size);
    errdefer allocator.free(buf);
    @memset(buf, 0);

    // Strip a stray ok-payload from `result<_, error-code>` (the 0.2
    // sync body emits `.tuple_val = &.{}` which is non-null but the
    // 0.3 result type's ok arm is null — `storeValReg` would otherwise
    // unwrap `td.result.ok.?`).
    var effective = val;
    if (kind == .unit_err and val == .result_val and val.result_val.is_ok) {
        effective = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    // The 0.2 sync bodies write the err-arm discriminant via
    // `@intFromEnum(FsErrorCode)`, but the 0.3 `variant error-code`
    // dropped `would-block`. Transcode in-place for every
    // `result<_, error-code>`-shaped return so the wire-level disc
    // matches the guest's 0.3 enum positions. The 0.2 `DescType`
    // similarly has a leading `unknown=0` case absent from 0.3's
    // `descriptor-type` variant — transcode the ok-arm disc for
    // `.desc_type_err` and the `descriptor-stat.type` field for
    // `.desc_stat_err`. Tier-D / `.just_bool` doesn't carry an error
    // variant; safe to skip. (#564.)
    switch (kind) {
        .unit_err, .desc_err, .desc_type_err, .desc_flags_err, .string_err, .desc_stat_err, .metadata_hash_err => fsP3FixupErrCode(effective),
        .just_bool => {},
    }
    switch (kind) {
        .desc_type_err => fsP3FixupDescType(effective),
        .desc_stat_err => fsP3FixupDescStatType(effective),
        else => {},
    }

    try abi.storeValReg(buf, 0, vt, effective, reg);
    return buf;
}

/// Lower a host slice-of-byte-slices into a canonical
/// `list<list<u8>>` PtrLen in guest memory. Each inner slice is
/// `hostAllocAndWrite`'d; the outer buffer holds `n × (u32 ptr, u32 len)`
/// pairs. Returns `{ .ptr = 0, .len = 0 }` for empty input without
/// touching guest memory.
fn lowerByteListList(ci: *ComponentInstance, lists: []const []const u8) !InterfaceValue.PtrLen {
    if (lists.len == 0) return .{ .ptr = 0, .len = 0 };
    const total: u32 = @intCast(lists.len * 8);
    const outer = ci.hostAllocGuest(total, 4) orelse return error.OutOfMemory;
    const dst = ci.writableGuestBytes(outer, total) orelse return error.OutOfMemory;
    var off: u32 = 0;
    for (lists) |bytes| {
        // Empty inner lists must still carry a non-zero pointer:
        // wit-bindgen 0.45 lifts each inner via `Vec::from_raw_parts`
        // which asserts the pointer is non-null even when length is
        // zero. Allocate a single byte so the lift survives (#538).
        const inner_ptr: u32 = if (bytes.len == 0)
            (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
        else
            (ci.hostAllocAndWrite(bytes) orelse return error.OutOfMemory);
        std.mem.writeInt(u32, dst[off..][0..4], inner_ptr, .little);
        std.mem.writeInt(u32, dst[off + 4 ..][0..4], @intCast(bytes.len), .little);
        off += 8;
    }
    return .{ .ptr = outer, .len = @intCast(lists.len) };
}

/// Lower a slice of (name, value) byte pairs into canonical
/// `list<tuple<list<u8>, list<u8>>>` PtrLen in guest memory. Each
/// element is 16 bytes: `(name_ptr, name_len, value_ptr, value_len)`.
fn lowerFieldEntriesList(ci: *ComponentInstance, entries: []const HttpFieldEntry) !InterfaceValue.PtrLen {
    if (entries.len == 0) return .{ .ptr = 0, .len = 0 };
    const total: u32 = @intCast(entries.len * 16);
    const outer = ci.hostAllocGuest(total, 4) orelse return error.OutOfMemory;
    const dst = ci.writableGuestBytes(outer, total) orelse return error.OutOfMemory;
    var off: u32 = 0;
    for (entries) |e| {
        // See `lowerByteListList` (#538): wit-bindgen Vec lift
        // requires a non-null pointer even for empty lists.
        const name_ptr: u32 = if (e.name.len == 0)
            (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
        else
            (ci.hostAllocAndWrite(e.name) orelse return error.OutOfMemory);
        const value_ptr: u32 = if (e.value.len == 0)
            (ci.hostAllocGuest(1, 1) orelse return error.OutOfMemory)
        else
            (ci.hostAllocAndWrite(e.value) orelse return error.OutOfMemory);
        std.mem.writeInt(u32, dst[off..][0..4], name_ptr, .little);
        std.mem.writeInt(u32, dst[off + 4 ..][0..4], @intCast(e.name.len), .little);
        std.mem.writeInt(u32, dst[off + 8 ..][0..4], value_ptr, .little);
        std.mem.writeInt(u32, dst[off + 12 ..][0..4], @intCast(e.value.len), .little);
        off += 16;
    }
    return .{ .ptr = outer, .len = @intCast(entries.len) };
}

// ── wasi:sockets@0.3.0 async-payload type registry (#535) ──────────────────
//
// Async-func wrappers on the 0.3 sockets surface return `result<T, error-code>`
// shapes whose `T` arm carries either a list of `ip-address`es or a tuple of
// `(list<u8>, ip-socket-address)`. The executor's `future_read` rendezvous
// (#502) consumes `Future.payload` directly: the canonical-ABI-lowered byte
// stream for `result<T, error-code>` lives in `payload` so the read can
// `memcpy` it into the guest's destination pointer.
//
// Indices (consult `sockets_p3_local_types` below):
//    0: tuple<u8, u8, u8, u8>                                       — ipv4 octets
//    1: tuple<u16, u16, u16, u16, u16, u16, u16, u16>               — ipv6 groups
//    2: variant ip-address { ipv4(tuple<u8 x 4>), ipv6(tuple<u16 x 8>) }
//    3: list<ip-address>                                            — resolve-addresses ok arm
//    4: list<u8>                                                    — udp datagram bytes
//    5: record ipv4-socket-address { port: u16, address: tuple<u8 x 4> }
//    6: record ipv6-socket-address { port: u16, flow-info: u32,
//         address: tuple<u16 x 8>, scope-id: u32 }
//    7: variant ip-socket-address { ipv4, ipv6 }
//    8: tuple<list<u8>, ip-socket-address>                          — udp-receive ok arm
//    9: variant error-code (21 cases; all unit)
//   10: result<list<ip-address>, error-code>                         — resolve-addresses
//   11: result<tuple<list<u8>, ip-socket-address>, error-code>       — udp-receive
//   12: result<_, error-code>                                        — connect, udp-send, etc.

const sockets_p3_ipv4_octets_fields = [_]ctypes.ValType{ .u8, .u8, .u8, .u8 };
const sockets_p3_ipv6_groups_fields = [_]ctypes.ValType{ .u16, .u16, .u16, .u16, .u16, .u16, .u16, .u16 };
const sockets_p3_ip_address_cases = [_]ctypes.Case{
    .{ .name = "ipv4", .type = .{ .tuple = 0 } },
    .{ .name = "ipv6", .type = .{ .tuple = 1 } },
};
const sockets_p3_ipv4_sockaddr_fields = [_]ctypes.Field{
    .{ .name = "port", .type = .u16 },
    .{ .name = "address", .type = .{ .tuple = 0 } },
};
const sockets_p3_ipv6_sockaddr_fields = [_]ctypes.Field{
    .{ .name = "port", .type = .u16 },
    .{ .name = "flow-info", .type = .u32 },
    .{ .name = "address", .type = .{ .tuple = 1 } },
    .{ .name = "scope-id", .type = .u32 },
};
const sockets_p3_ip_sockaddr_cases = [_]ctypes.Case{
    .{ .name = "ipv4", .type = .{ .record = 5 } },
    .{ .name = "ipv6", .type = .{ .record = 6 } },
};
const sockets_p3_udp_receive_fields = [_]ctypes.ValType{
    .{ .list = 4 },
    .{ .variant = 7 },
};
// WIT 0.3 `wasi:sockets/types.error-code` is a 15-case variant ending in
// `other(option<string>)` (NOT the flat 21-case enum of 0.2). Case 14
// carries the option<string> payload so the canonical-ABI size envelope
// for the variant reserves space for ptr+len+option-disc — emitting case
// 14 with `payload=null` is `other(none)`; supplying a string is the
// diagnostic path used by `socketResultErrP3WithDiag`. The `other` arm
// references the `option<string>` typedef at index 13 below. (#563)
const sockets_p3_error_code_cases = [_]ctypes.Case{
    .{ .name = "access-denied", .type = null },
    .{ .name = "not-supported", .type = null },
    .{ .name = "invalid-argument", .type = null },
    .{ .name = "out-of-memory", .type = null },
    .{ .name = "timeout", .type = null },
    .{ .name = "invalid-state", .type = null },
    .{ .name = "address-not-bindable", .type = null },
    .{ .name = "address-in-use", .type = null },
    .{ .name = "remote-unreachable", .type = null },
    .{ .name = "connection-refused", .type = null },
    .{ .name = "connection-broken", .type = null },
    .{ .name = "connection-reset", .type = null },
    .{ .name = "connection-aborted", .type = null },
    .{ .name = "datagram-too-large", .type = null },
    // case 14: `other(option<string>)` — payload references the
    // option<string> typedef at index 13.
    .{ .name = "other", .type = .{ .option = 13 } },
};

const sockets_p3_local_types = [_]ctypes.TypeDef{
    .{ .tuple = .{ .fields = &sockets_p3_ipv4_octets_fields } }, // 0
    .{ .tuple = .{ .fields = &sockets_p3_ipv6_groups_fields } }, // 1
    .{ .variant = .{ .cases = &sockets_p3_ip_address_cases } }, // 2
    .{ .list = .{ .element = .{ .variant = 2 } } }, // 3
    .{ .list = .{ .element = .u8 } }, // 4
    .{ .record = .{ .fields = &sockets_p3_ipv4_sockaddr_fields } }, // 5
    .{ .record = .{ .fields = &sockets_p3_ipv6_sockaddr_fields } }, // 6
    .{ .variant = .{ .cases = &sockets_p3_ip_sockaddr_cases } }, // 7
    .{ .tuple = .{ .fields = &sockets_p3_udp_receive_fields } }, // 8
    .{ .variant = .{ .cases = &sockets_p3_error_code_cases } }, // 9
    .{ .result = .{ .ok = .{ .list = 3 }, .err = .{ .variant = 9 } } }, // 10
    .{ .result = .{ .ok = .{ .tuple = 8 }, .err = .{ .variant = 9 } } }, // 11
    .{ .result = .{ .ok = null, .err = .{ .variant = 9 } } }, // 12
    // option<string> — referenced by `other(option<string>)` arm of the
    // error-code variant. Must occupy the index named in
    // `sockets_p3_error_code_cases[14].type.option`. (#563)
    .{ .option = .{ .inner = .string } }, // 13
};

const SOCKETS_P3_IP_ADDRESS_VARIANT_IDX: u32 = 2;
const SOCKETS_P3_IP_ADDRESS_LIST_IDX: u32 = 3;
const SOCKETS_P3_IP_SOCKADDR_VARIANT_IDX: u32 = 7;
const SOCKETS_P3_UDP_RECEIVE_TUPLE_IDX: u32 = 8;
const SOCKETS_P3_RESULT_RESOLVE_IDX: u32 = 10;
const SOCKETS_P3_RESULT_UDP_RECV_IDX: u32 = 11;
const SOCKETS_P3_RESULT_UNIT_ERR_IDX: u32 = 12;
const SOCKETS_P3_OPTION_STRING_IDX: u32 = 13;
/// Discriminant of the `other(option<string>)` arm in the 0.3
/// error-code variant. Co-located with the case array so the helper
/// fall-through path can route unmapped errors here without an
/// off-by-one risk. (#563)
const SOCKETS_P3_ERROR_OTHER_DISC: u32 = 14;

fn socketsP3TypeRegistry() abi.TypeRegistry {
    return abi.TypeRegistry.fromTypes(&sockets_p3_local_types);
}

/// 0.3 async-func return shapes that `socketsLowerAsyncPayload` knows
/// how to lower. Mirrors `FsP3AsyncReturn`.
const SocketsP3AsyncReturn = enum {
    /// `result<_, error-code>` — connect, udp-send, etc.
    unit_err,
    /// `result<list<ip-address>, error-code>` — resolve-addresses ok arm.
    resolve_list_err,
    /// `result<tuple<list<u8>, ip-socket-address>, error-code>` — udp-receive ok arm.
    udp_receive_err,

    pub fn valType(self: SocketsP3AsyncReturn) ctypes.ValType {
        return switch (self) {
            .unit_err => .{ .result = SOCKETS_P3_RESULT_UNIT_ERR_IDX },
            .resolve_list_err => .{ .result = SOCKETS_P3_RESULT_RESOLVE_IDX },
            .udp_receive_err => .{ .result = SOCKETS_P3_RESULT_UDP_RECV_IDX },
        };
    }
};

/// Lower a fully-lifted `InterfaceValue` for the requested 0.3 sockets
/// async-func return shape into a canonical-ABI byte buffer suitable
/// for installation on `async_mod.Future.payload`. Owned by `allocator`;
/// the future-read rendezvous on the executor frees it after the guest
/// reads. Mirrors `fsP3LowerAsyncPayload` (#522 / PR #528).
fn socketsP3LowerAsyncPayload(
    allocator: Allocator,
    kind: SocketsP3AsyncReturn,
    val: InterfaceValue,
) ![]u8 {
    const reg = socketsP3TypeRegistry();
    const vt = kind.valType();
    const size = abi.sizeOfType(reg, vt);
    if (size == 0) return error.LowerError;
    const buf = try allocator.alloc(u8, size);
    errdefer allocator.free(buf);
    @memset(buf, 0);

    // Strip a stray ok-payload from `result<_, error-code>` (the same
    // 0.2-shape compatibility cleanup as `fsP3LowerAsyncPayload`).
    var effective = val;
    if (kind == .unit_err and val == .result_val and val.result_val.is_ok) {
        effective = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }
    try abi.storeValReg(buf, 0, vt, effective, reg);
    return buf;
}

const streams = @import("../wasi/preview2/streams.zig");
const wasi_p2_core = @import("../wasi/preview2/core.zig");

/// Captured stdout adapter. Owns its `OutputStream` and the `HostInstance`
/// objects exposed to the runtime via `populateProviders`.
///
/// Lifetime: caller `init`s, registers via `populateProviders`, then
/// retains the adapter until any `ComponentInstance` whose imports point
/// at the registered `HostInstance` is destroyed. `deinit` releases the
/// buffer and member maps.
/// `wasi:filesystem/types.descriptor-flags` (#181). Carries the access
/// + sync intent that the guest passed to `descriptor.open-at` and that
/// `descriptor.get-flags` reads back. Bit positions match the WIT order.
pub const FsDescriptorFlags = packed struct(u8) {
    read: bool = false,
    write: bool = false,
    file_integrity_sync: bool = false,
    data_integrity_sync: bool = false,
    requested_write_sync: bool = false,
    mutate_directory: bool = false,
    _pad: u2 = 0,

    pub fn fromBits(bits: u32) FsDescriptorFlags {
        return .{
            .read = (bits & 0b000001) != 0,
            .write = (bits & 0b000010) != 0,
            .file_integrity_sync = (bits & 0b000100) != 0,
            .data_integrity_sync = (bits & 0b001000) != 0,
            .requested_write_sync = (bits & 0b010000) != 0,
            .mutate_directory = (bits & 0b100000) != 0,
        };
    }

    pub fn toBits(self: FsDescriptorFlags) u32 {
        var out: u32 = 0;
        if (self.read) out |= 0b000001;
        if (self.write) out |= 0b000010;
        if (self.file_integrity_sync) out |= 0b000100;
        if (self.data_integrity_sync) out |= 0b001000;
        if (self.requested_write_sync) out |= 0b010000;
        if (self.mutate_directory) out |= 0b100000;
        return out;
    }

    /// Whether host writes against this descriptor must be flushed to
    /// stable storage (i.e. `file.sync()` after each flush boundary).
    /// Matches POSIX `O_SYNC`/`O_DSYNC`. `requested-write-sync`
    /// (`O_RSYNC`) is **read-side** in POSIX and not a write-sync trigger.
    pub fn needsWriteSync(self: FsDescriptorFlags) bool {
        return self.file_integrity_sync or self.data_integrity_sync;
    }
};

/// `wasi:filesystem/types.descriptor` resource — slot in the descriptor
/// table. Indices in `WasiCliAdapter.fs_descriptor_table` are guest
/// handles. Slots are nulled on `[resource-drop]descriptor`, except
/// `.preopen` slots which are persistent (a guest dropping a preopen
/// handle is treated as a no-op so subsequent calls to
/// `preopens.get-directories` and `descriptor.open-at` keep working).
///
/// Each variant carries the `descriptor-flags` the guest requested at
/// open time (#181). Preopens default to `read|write|mutate_directory`
/// so that `open-at` from a preopen retains its pre-#181 capabilities.
pub const FsDescriptor = union(enum) {
    /// Regular file or any other non-directory descriptor opened via
    /// `descriptor.open-at`. Owned — closed on resource-drop.
    file: FsFile,
    /// Directory descriptor opened via `descriptor.open-at` with the
    /// `directory` open-flag. Owned — closed on resource-drop.
    dir: FsDir,
    /// Preopen sandbox root — adapter-owned. Resource-drop is a no-op
    /// for preopens; the adapter closes them in `deinit`.
    preopen: FsDir,

    pub const FsFile = struct {
        file: std.Io.File,
        flags: FsDescriptorFlags = .{},
    };
    pub const FsDir = struct {
        dir: std.Io.Dir,
        flags: FsDescriptorFlags = .{},
    };

    pub fn flags(self: FsDescriptor) FsDescriptorFlags {
        return switch (self) {
            .file => |f| f.flags,
            .dir => |d| d.flags,
            .preopen => |d| d.flags,
        };
    }

    /// Underlying directory handle for any directory-shaped descriptor
    /// (`.dir` or `.preopen`). Returns null for `.file`.
    pub fn asDir(self: FsDescriptor) ?std.Io.Dir {
        return switch (self) {
            .dir => |d| d.dir,
            .preopen => |d| d.dir,
            .file => null,
        };
    }
};

pub const FsPreopen = struct {
    name: []const u8,
    dir_handle: u32,
};

/// `wasi:filesystem/types.directory-entry-stream` resource (#476). A
/// thin owner of a heap-allocated `std.Io.Dir.Iterator`. We heap-
/// allocate because the iterator embeds a ~2 KiB read-buffer field
/// whose self-referential pointer (`reader.buffer = &reader_buffer`)
/// is re-fixed by each `.next(io)` call — that re-fix is what makes
/// it valid for the struct to live in an `ArrayList` slot or to be
/// moved across deinit boundaries.
///
/// Indices in `WasiCliAdapter.dir_entry_stream_table` are guest
/// handles. The stream is independent of the descriptor that
/// produced it; dropping that descriptor must **not** invalidate the
/// stream.
pub const DirEntryStream = struct {
    iter: *std.Io.Dir.Iterator,
};

/// Close a descriptor's underlying handle. Used by both
/// `[resource-drop]descriptor` (for `.file` / `.dir`) and adapter
/// `deinit` (which also closes preopens).
fn closeFsDescriptor(d: FsDescriptor) void {
    const io = std.Io.Threaded.global_single_threaded.io();
    switch (d) {
        .file => |f| f.file.close(io),
        .dir => |d2| d2.dir.close(io),
        .preopen => |d2| d2.dir.close(io),
    }
}

/// `wasi:filesystem/types.error-code` discriminant indices, in the order
/// the WIT spec declares them. Used as `.variant_val.discriminant` for
/// the `result<_, error-code>` err arm.
const FsErrorCode = enum(u32) {
    access = 0,
    would_block = 1,
    already = 2,
    bad_descriptor = 3,
    busy = 4,
    deadlock = 5,
    quota = 6,
    exist = 7,
    file_too_large = 8,
    illegal_byte_sequence = 9,
    in_progress = 10,
    interrupted = 11,
    invalid = 12,
    io = 13,
    is_directory = 14,
    loop = 15,
    too_many_links = 16,
    message_size = 17,
    name_too_long = 18,
    no_device = 19,
    no_entry = 20,
    no_lock = 21,
    insufficient_memory = 22,
    insufficient_space = 23,
    not_directory = 24,
    not_empty = 25,
    not_recoverable = 26,
    unsupported = 27,
    no_tty = 28,
    no_such_device = 29,
    overflow = 30,
    not_permitted = 31,
    pipe = 32,
    read_only = 33,
    invalid_seek = 34,
    text_file_busy = 35,
    cross_device = 36,
};

/// `wasi:sockets/network.error-code` discriminants in WIT-declaration order
/// (37 variants). Used as `.variant_val.discriminant` for the err arm of
/// `result<_, error-code>` returns from sockets host fns.
const SocketErrorCode = enum(u32) {
    unknown = 0,
    access_denied = 1,
    not_supported = 2,
    invalid_argument = 3,
    out_of_memory = 4,
    timeout = 5,
    concurrency_conflict = 6,
    not_in_progress = 7,
    would_block = 8,
    invalid_state = 9,
    new_socket_limit = 10,
    address_not_bindable = 11,
    address_in_use = 12,
    remote_unreachable = 13,
    connection_refused = 14,
    connection_reset = 15,
    connection_aborted = 16,
    datagram_too_large = 17,
    name_unresolvable = 18,
    temporary_resolver_failure = 19,
    permanent_resolver_failure = 20,
};

/// IPv4 vs IPv6 — matches the discriminant order of `ip-address-family`.
const IpAddressFamily = enum(u32) {
    ipv4 = 0,
    ipv6 = 1,
};

const SocketKind = enum { tcp, udp };

const SocketState = enum { unbound, bound, listening, connected, closed };

/// Pending lifecycle-op result. WIT splits each blocking op into a
/// `start-X` / `finish-X` pair: `start` kicks off the work, `finish`
/// reads the result. Our `start-X` runs synchronously (since
/// `std.Io.net` is blocking) and stores the outcome here for the
/// matching `finish-X` to consume. `idle` means no in-flight op.
const PendingTcpOp = enum { idle, bind_done, listen_done, connect_done };

/// Adapter-side `tcp-socket` / `udp-socket` rep. TCP can hold a real
/// `std.Io.net.Server` once `start-listen` succeeds (#178 PR A).
/// UDP holds a `host_socket` after `start-bind` succeeds (#178 PR C).
pub const Socket = struct {
    kind: SocketKind,
    family: IpAddressFamily,
    state: SocketState = .unbound,
    /// Authorized local address recorded by `start-bind`. Refreshed
    /// from the kernel after `start-listen` (TCP) or immediately
    /// after the real bind syscall (UDP) so guests observe the
    /// ephemeral port when port=0 was requested.
    local_addr: ?std.Io.net.IpAddress = null,
    /// Active listening server. Owned by the rep; closed in
    /// `closeAll`. TCP only.
    server: ?std.Io.net.Server = null,
    /// Pending TCP lifecycle op. Always `.idle` for udp sockets.
    pending: PendingTcpOp = .idle,
    /// UDP datagram socket. Owned by the rep; closed in `closeAll`.
    host_socket: ?std.Io.net.Socket = null,
    /// Deep-copied allow-list from the network rep at bind time.
    /// Owned by the socket; freed in `closeAll`. Prevents UAF if
    /// the network resource is dropped before the socket.
    allow_list: []const IpCidr = &.{},
    /// Connected remote address set by `stream(some(remote))`.
    remote_addr: ?std.Io.net.IpAddress = null,
    /// Generation counter for `stream()` — each call bumps this;
    /// sub-resources record the value at creation. Stale streams
    /// whose generation != socket's return `invalid-state`.
    stream_generation: u32 = 0,
    /// TCP connected stream. Owned by the rep; closed in `closeAll`.
    tcp_stream: ?std.Io.net.Stream = null,

    /// Requested listen backlog size. Stored on the rep by
    /// `set-listen-backlog-size` and consumed by `start-listen`.
    listen_backlog: ?u31 = null,

    // ----- Pending socket-option state (#561) ----------------------
    // The WIT spec lets guests set tcp/udp socket options before
    // bind/listen/connect, when there is no kernel fd to forward them
    // to. Setters write the requested value here; once a kernel fd
    // appears (via start-listen for TCP, start-connect for TCP, or
    // start-bind for UDP) `applyPendingSockOpts` flushes the
    // accumulated state via `setsockopt`. Getters return the rep
    // value first and only fall back to kernel `getsockopt` when the
    // rep is null.
    keep_alive_enabled: ?bool = null,
    keep_alive_idle_time: ?u64 = null,
    keep_alive_interval: ?u64 = null,
    keep_alive_count: ?u32 = null,
    hop_limit: ?u8 = null,
    send_buffer_size: ?u64 = null,
    receive_buffer_size: ?u64 = null,

    /// Returns the kernel fd for this socket, or null if no underlying
    /// socket exists yet (e.g., unbound state).
    pub fn getKernelFd(self: *const Socket) ?std.posix.fd_t {
        if (self.tcp_stream) |ts| return ts.socket.handle;
        if (self.server) |srv| return srv.socket.handle;
        if (self.host_socket) |hs| return hs.handle;
        return null;
    }

    /// Flush rep-tracked socket options (#561) onto a freshly opened
    /// kernel fd. Called from `tcpStartListen` / `tcpStartConnect` /
    /// `udpStartBind` after the underlying socket is created. Failures
    /// from `setsockopt` are swallowed: the rep value remains the
    /// source of truth and the corresponding getter still returns it.
    pub fn applyPendingSockOpts(self: *const Socket) void {
        const fd = self.getKernelFd() orelse return;
        if (self.keep_alive_enabled) |e| {
            _ = socketSetU32Opt(fd, SOL_SOCKET_OPT, SO_KEEPALIVE_OPT, if (e) 1 else 0);
        }
        if (self.keep_alive_idle_time) |ns| {
            const secs: u32 = @intCast(@min(ns / 1_000_000_000, std.math.maxInt(u32)));
            if (secs != 0) {
                _ = socketSetU32Opt(fd, IPPROTO_TCP_OPT, TCP_KEEPIDLE_OPT, secs);
            }
        }
        if (self.keep_alive_interval) |ns| {
            const secs: u32 = @intCast(@min(ns / 1_000_000_000, std.math.maxInt(u32)));
            if (secs != 0) {
                _ = socketSetU32Opt(fd, IPPROTO_TCP_OPT, TCP_KEEPINTVL_OPT, secs);
            }
        }
        if (self.keep_alive_count) |c| {
            _ = socketSetU32Opt(fd, IPPROTO_TCP_OPT, TCP_KEEPCNT_OPT, c);
        }
        if (self.hop_limit) |h| {
            _ = switch (self.family) {
                .ipv4 => socketSetU32Opt(fd, IPPROTO_IP_OPT, IP_TTL_OPT, @as(u32, h)),
                .ipv6 => socketSetU32Opt(fd, IPPROTO_IPV6_OPT, IPV6_UNICAST_HOPS_OPT, @as(u32, h)),
            };
        }
        if (self.send_buffer_size) |sz| {
            _ = socketSetU32Opt(fd, SOL_SOCKET_OPT, SO_SNDBUF_OPT, @intCast(@min(sz, std.math.maxInt(u32))));
        }
        if (self.receive_buffer_size) |sz| {
            _ = socketSetU32Opt(fd, SOL_SOCKET_OPT, SO_RCVBUF_OPT, @intCast(@min(sz, std.math.maxInt(u32))));
        }
    }

    /// Release any held kernel resources. Idempotent. Called from
    /// `[resource-drop]{tcp,udp}-socket` and adapter `deinit`.
    pub fn closeAll(self: *Socket, io: std.Io, allocator: Allocator) void {
        if (self.server) |*srv| srv.deinit(io);
        self.server = null;
        if (self.tcp_stream) |*ts| ts.close(io);
        self.tcp_stream = null;
        if (self.host_socket) |*hs| hs.close(io);
        self.host_socket = null;
        if (self.allow_list.len != 0) allocator.free(self.allow_list);
        self.allow_list = &.{};
        self.remote_addr = null;
    }
};

/// Rep for `wasi:sockets/udp.incoming-datagram-stream`. Each instance
/// is tied to a parent `Socket` via `parent_handle` and validated via
/// `generation` — if the socket's `stream_generation` has advanced
/// past this stream's, all operations return `invalid-state`.
pub const UdpIncomingStream = struct {
    parent_handle: u32,
    generation: u32,
    remote: ?std.Io.net.IpAddress,
};

/// Rep for `wasi:sockets/udp.outgoing-datagram-stream`. Tracks
/// `send_credit` for the WIT-mandated `check-send` / `send`
/// protocol: `send` traps if `check-send` was not called first
/// or if `datagrams.len > send_credit`.
pub const UdpOutgoingStream = struct {
    parent_handle: u32,
    generation: u32,
    remote: ?std.Io.net.IpAddress,
    send_credit: ?u64 = null,
};

/// CIDR block for the per-`network` allow-list (#180). Stored canonical:
/// host bits below the prefix are zeroed at parse time.
pub const IpCidr = union(enum) {
    ip4: struct { bytes: [4]u8, prefix: u6 },
    ip6: struct { bytes: [16]u8, prefix: u8 },

    pub const ParseError = error{
        InvalidCidr,
        InvalidPrefix,
        InvalidAddress,
    };

    /// Parse `"<addr>/<prefix>"`. The address half is parsed with port=0 by
    /// `Ip4Address.parse` / `Ip6Address.parse`; v4 is tried first. Prefix
    /// must be plain decimal (no leading `+`/`-`/zero-padding) within
    /// 0..=32 (v4) or 0..=128 (v6). Host bits are masked to zero so two
    /// textual variants of the same network compare equal.
    pub fn parse(text: []const u8) ParseError!IpCidr {
        const slash = std.mem.indexOfScalar(u8, text, '/') orelse return error.InvalidCidr;
        const addr_text = text[0..slash];
        const prefix_text = text[slash + 1 ..];
        if (addr_text.len == 0 or prefix_text.len == 0) return error.InvalidCidr;
        // Reject leading zeros / signs in prefix to keep canonical text.
        if (prefix_text[0] == '+' or prefix_text[0] == '-') return error.InvalidPrefix;
        if (prefix_text.len > 1 and prefix_text[0] == '0') return error.InvalidPrefix;
        for (prefix_text) |c| if (c < '0' or c > '9') return error.InvalidPrefix;
        // Reject bracketed IPv6 (`[::]/128`) — CIDR text is bare.
        if (addr_text[0] == '[') return error.InvalidAddress;

        if (std.Io.net.Ip4Address.parse(addr_text, 0)) |v4| {
            const p = std.fmt.parseInt(u8, prefix_text, 10) catch return error.InvalidPrefix;
            if (p > 32) return error.InvalidPrefix;
            var bytes = v4.bytes;
            maskV4(&bytes, @intCast(p));
            return .{ .ip4 = .{ .bytes = bytes, .prefix = @intCast(p) } };
        } else |_| {}
        if (std.Io.net.Ip6Address.parse(addr_text, 0)) |v6| {
            const p = std.fmt.parseInt(u8, prefix_text, 10) catch return error.InvalidPrefix;
            if (p > 128) return error.InvalidPrefix;
            var bytes = v6.bytes;
            maskV6(&bytes, p);
            return .{ .ip6 = .{ .bytes = bytes, .prefix = p } };
        } else |_| {}
        return error.InvalidAddress;
    }

    /// Same-family bit-prefix match. Mixed families never match — IPv4-
    /// mapped IPv6 addresses are matched as IPv6 only (callers receive an
    /// `IpAddress` already discriminated by the wasi:sockets layer).
    pub fn containsAddr(self: IpCidr, addr: std.Io.net.IpAddress) bool {
        return switch (self) {
            .ip4 => |c| switch (addr) {
                .ip4 => |a| matchPrefix(&c.bytes, &a.bytes, c.prefix),
                .ip6 => false,
            },
            .ip6 => |c| switch (addr) {
                .ip6 => |a| matchPrefix(&c.bytes, &a.bytes, c.prefix),
                .ip4 => false,
            },
        };
    }
};

fn maskV4(bytes: *[4]u8, prefix: u6) void {
    if (prefix >= 32) return;
    var i: usize = 0;
    var remaining: u8 = prefix;
    while (i < 4) : (i += 1) {
        if (remaining >= 8) {
            remaining -= 8;
        } else if (remaining == 0) {
            bytes[i] = 0;
        } else {
            const keep: u8 = @as(u8, 0xff) << @intCast(8 - remaining);
            bytes[i] &= keep;
            remaining = 0;
        }
    }
}

fn maskV6(bytes: *[16]u8, prefix: u8) void {
    if (prefix >= 128) return;
    var i: usize = 0;
    var remaining: u8 = prefix;
    while (i < 16) : (i += 1) {
        if (remaining >= 8) {
            remaining -= 8;
        } else if (remaining == 0) {
            bytes[i] = 0;
        } else {
            const keep: u8 = @as(u8, 0xff) << @intCast(8 - remaining);
            bytes[i] &= keep;
            remaining = 0;
        }
    }
}

fn matchPrefix(cidr_bytes: []const u8, addr_bytes: []const u8, prefix: u8) bool {
    var remaining: u8 = prefix;
    var i: usize = 0;
    while (remaining >= 8) : (i += 1) {
        if (cidr_bytes[i] != addr_bytes[i]) return false;
        remaining -= 8;
    }
    if (remaining == 0) return true;
    const mask: u8 = @as(u8, 0xff) << @intCast(8 - remaining);
    return (cidr_bytes[i] & mask) == (addr_bytes[i] & mask);
}

/// Adapter-side `network` rep (#180). Carries a per-instance allow-list of
/// CIDR blocks snapshotted from `WasiCliAdapter.sockets_allow_list_template`
/// at `instance-network` time; the snapshot is owned by the Network and
/// freed in `[resource-drop]network` / adapter `deinit`. Empty list = the
/// default deny-all capability for the 0.2 surface.
///
/// Note: the 0.3 sockets path does not go through a `Network` resource
/// (the 0.3 WIT dropped `network` entirely). It consults
/// `WasiCliAdapter.sockets_allow_list_template` directly via
/// `templateAllows` — see that helper for the empty-template semantics
/// (allow-all for raw sockets, deny-all for DNS / outbound HTTP). (#583 A1)
pub const Network = struct {
    allow_list: []const IpCidr = &.{},

    pub fn allows(self: Network, addr: std.Io.net.IpAddress) bool {
        for (self.allow_list) |c| if (c.containsAddr(addr)) return true;
        return false;
    }

    fn deinit(self: *Network, allocator: Allocator) void {
        if (self.allow_list.len != 0) allocator.free(self.allow_list);
        self.allow_list = &.{};
    }
};

/// Adapter-side `resolve-address-stream` rep. `pos` advances on each
/// `resolve-next-address` until `pos == results.len`, after which the
/// stream returns `option<ip-address>::none`. The slice and `self`
/// itself are owned by the adapter and freed in `deinit` /
/// `[resource-drop]resolve-address-stream`.
pub const ResolveAddressStream = struct {
    results: []std.Io.net.IpAddress,
    pos: usize,
    allocator: Allocator,
};

/// Lifetime-stable context for a `host_driver` attached to a socket-
/// backed `AsyncStream` (#535). The executor invokes the driver
/// callbacks with this opaque pointer; the callbacks unwrap it,
/// consult the fd, and (for accept) push new sockets through the
/// adapter. Owned by `WasiCliAdapter.sockets_p3_stream_ctxs`, lives
/// until adapter teardown.
pub const SocketsP3StreamCtx = struct {
    adapter: *WasiCliAdapter,
    fd: std.posix.fd_t,
    family: IpAddressFamily,
};

/// Lifetime-stable context for a `host_driver` attached to an
/// `AsyncStream` created by `descriptor.write-via-stream` /
/// `descriptor.append-via-stream` (#571). The executor invokes
/// `writeViaStreamOnWrite` with this opaque pointer; the callback
/// looks up the underlying `FsDescriptor` (so a guest dropping the
/// descriptor while the stream is still live surfaces gracefully as
/// `.err`) and `pwrite(2)`s the guest's bytes at
/// `offset + bytes_written`, tracking the running offset.
///
/// Owned by `WasiCliAdapter.fs_write_stream_ctxs`; freed in adapter
/// `deinit` after the executor has released all `AsyncStream` slots.
pub const FsWriteStreamCtx = struct {
    adapter: *WasiCliAdapter,
    /// Guest-visible `descriptor` handle for the target file. We
    /// re-lookup on every callback instead of stashing a `std.Io.File`
    /// by value so a `[resource-drop]descriptor` mid-stream surfaces
    /// as an error instead of a UAF on the fd.
    desc_handle: u32,
    /// Base offset captured at `write-via-stream` call time. For
    /// `append-via-stream` we ignore this and re-stat each call.
    offset: u64,
    /// Running byte counter — sum of all bytes pwrite'd so far. The
    /// next `on_write` call writes at `offset + bytes_written`.
    bytes_written: u64,
    /// True if this driver was installed by `append-via-stream`. The
    /// `on_write` callback stats the file each call and writes at
    /// end-of-file instead of `offset + bytes_written`.
    append: bool,
};

/// A `udp-socket.receive` call that found no datagram waiting on its
/// first non-blocking `recvfrom(2)` and so returned a `.pending`
/// future. The async event driver (`driveAsyncEvents`) polls the
/// recorded fd on every `waitable-set.wait` iteration and, when a
/// datagram arrives, lifts the `result<tuple<list<u8>,
/// ip-socket-address>, error-code>` payload into the future and
/// fires the WaitableSet wakeup so the guest's awaited `.receive()`
/// resolves (#576).
///
/// Mirrors the deferred-completion shape used by the `wasi:clocks`
/// timer-future infrastructure (#551): the host adapter parks the
/// future, the driver drives it on each event-loop tick, and the
/// trampoline's `async_lower_retptr` stash gets written when the
/// future settles.
pub const PendingUdpReceive = struct {
    future_handle: u32,
    sock_handle: u32,
};

/// Outcome captured by an outbound HTTP worker thread (#583 A2). Shared
/// across the worker thread and the adapter's drain side via a heap-
/// allocated `PendingHttpFetchShared`. The two threads coordinate
/// through `done` (worker → adapter signal) and `cancelled` (adapter →
/// worker advisory); the heap struct is freed only after the thread
/// has been joined, so a slow outbound fetch can never UAF even if
/// the guest cancels or the adapter tears down mid-flight.
pub const HttpFetchOutcome = union(enum) {
    /// Successful HTTP response. `body` is owned host-allocated bytes
    /// consumed into an `IncomingResponse` on settle; `status` is the
    /// numeric HTTP response status; `headers` is the wire-order list
    /// of `(name, value)` pairs the server emitted, with transport-
    /// managed headers (Content-Length, Transfer-Encoding, Connection,
    /// Keep-Alive, Trailer, Upgrade, TE, Host) stripped per the
    /// wasi:http WIT spec (#583 A4). Each entry's `name` and `value`
    /// are independently owned `[]u8` slices.
    success: struct {
        status: u16,
        body: []u8,
        headers: []HttpFieldEntry,
    },
    /// Transport / TLS / parse failure mapped to a
    /// `wasi:http/types.error-code` discriminant.
    failure: HttpErrorCode,
};

/// Free an owned `[]HttpFieldEntry` produced by the low-level outbound
/// HTTP path (`httpClientLowLevelFetch` / worker). Frees each entry's
/// name + value plus the backing slice. Used both on the worker side
/// when the guest has already dropped the future-incoming-response and
/// on the settle side once entries transfer into a `HttpFields`. The
/// helper exists so the lifetime contract is centralised — anywhere
/// that owns a `HttpFetchOutcome.success.headers` slice can free it
/// without re-deriving the layout. (#583 A4)
fn freeOwnedHttpHeaders(allocator: Allocator, headers: []HttpFieldEntry) void {
    for (headers) |e| {
        allocator.free(e.name);
        allocator.free(e.value);
    }
    allocator.free(headers);
}

/// Returns `true` for HTTP headers the host manages on behalf of the
/// guest and must therefore strip from the lifted `incoming-response`
/// header set per the wasi:http WIT spec (#583 A4):
///
///   * `Content-Length` — body framing; recomputable from the body
///     stream. The host owns the wire framing; the guest sees a
///     `stream<u8>`, not byte counts.
///   * `Transfer-Encoding` — likewise body framing (chunked, etc.).
///   * `Connection`, `Keep-Alive` — hop-by-hop connection lifecycle.
///   * `Trailer`, `TE` — hop-by-hop trailer negotiation. wasi:http
///     surfaces trailers via the `future-trailers` resource instead.
///   * `Upgrade` — protocol upgrade hop-by-hop.
///   * `Host` — request-only target authority (only relevant on the
///     outgoing side, kept here defensively for symmetry).
///
/// Comparison is ASCII case-insensitive per RFC 9110 §5.1.
fn isTransportManagedHeader(name: []const u8) bool {
    const managed = [_][]const u8{
        "content-length",
        "transfer-encoding",
        "connection",
        "keep-alive",
        "trailer",
        "te",
        "upgrade",
        "host",
    };
    for (managed) |m| {
        if (std.ascii.eqlIgnoreCase(name, m)) return true;
    }
    return false;
}

/// Heap-allocated state shared between the host's outbound-HTTP worker
/// thread and the adapter's drain side. The worker writes `outcome`
/// then publishes via `done.store(true, .release)`; the adapter checks
/// `done.load(.acquire)` from `drainPendingHttpFetches` and only frees
/// the struct after `thread.join()` returns, guaranteeing no UAF even
/// when the worker is still mid-`std.http.Client.fetch`.
///
/// `cancelled` is an adapter → worker advisory: today's blocking
/// `std.http.Client.fetch` can't observe it mid-fetch, but the drain
/// side checks it on completion so a guest `task.cancel` issued
/// before the worker returns is still honoured by the future the
/// guest awaits (#488 cancel-propagation pattern). (#583 A2)
pub const PendingHttpFetchShared = struct {
    done: std.atomic.Value(bool) = .{ .raw = false },
    cancelled: std.atomic.Value(bool) = .{ .raw = false },
    /// Worker fetches into this slot once before flipping `done`.
    /// Adapter takes ownership of `success.body` on settle and frees
    /// it after the guest consumes the incoming-response.
    outcome: HttpFetchOutcome = .{ .failure = .internal_error },
};

/// One in-flight outbound HTTP fetch driven by a dedicated worker
/// thread. The future-incoming-response handle is settled by the
/// adapter's `drainPendingHttpFetches` driver once `shared.done` is
/// observed; the worker thread is `join()`ed at that point so the
/// shared heap struct can be safely freed. (#583 A2)
///
/// Mirrors the deferred-completion shape of `PendingUdpReceive`
/// (#576) but with a thread-driven completion source — Zig 0.16's
/// `std.http.Client.fetch` is blocking, and the spec-compliant
/// shape is a `.pending` future the guest can poll on.
pub const PendingHttpFetch = struct {
    /// Handle into `WasiCliAdapter.http_future_responses` of the
    /// future-incoming-response the guest is awaiting.
    future_handle: u32,
    /// Worker thread executing the blocking `std.http.Client.fetch`.
    /// Joined exactly once by the adapter — either at drain time
    /// when `shared.done` is observed, or at adapter teardown.
    thread: std.Thread,
    /// Heap-allocated coordination block — outlives both threads up
    /// to the post-join free in `drainPendingHttpFetches` / `deinit`.
    shared: *PendingHttpFetchShared,
    /// Set when the guest calls `[resource-drop]future-incoming-response`
    /// while the worker is still in flight. The slot is kept
    /// reserved (with a `.pending` `FutureIncomingResponse` parked
    /// in it) so `pushFutureResponse` cannot reuse the slot for an
    /// unrelated future; once the drainer settles the entry it
    /// nulls the slot and frees the parked `FutureIncomingResponse`
    /// itself. (#583 A2)
    guest_dropped: bool = false,
};

/// Snapshot of an `OutgoingRequest` plus body bytes that the worker
/// thread needs to perform a `std.http.Client.fetch` independently
/// of the adapter (so the adapter is free to mutate / drop the
/// request resource without racing). Owned by the worker; freed
/// in `httpFetchWorker` after the fetch returns. (#583 A2)
const HttpFetchRequest = struct {
    allocator: Allocator,
    url: []u8,
    method: std.http.Method,
    /// Header name/value slices, dupe'd into worker-owned memory.
    headers_buf: []std.http.Header,
    headers_names: [][]u8,
    headers_values: [][]u8,
    /// Optional request body bytes, owned host-allocated.
    payload: ?[]u8,
    /// The `PendingHttpFetchShared` slot the worker will publish
    /// its outcome through.
    shared: *PendingHttpFetchShared,

    fn deinit(self: *HttpFetchRequest) void {
        self.allocator.free(self.url);
        for (self.headers_names) |n| self.allocator.free(n);
        for (self.headers_values) |v| self.allocator.free(v);
        self.allocator.free(self.headers_names);
        self.allocator.free(self.headers_values);
        self.allocator.free(self.headers_buf);
        if (self.payload) |p| self.allocator.free(p);
    }
};

/// Map a `std.Io.net.HostName.LookupError` to the closest
/// `wasi:sockets/network.error-code` variant. Most parse / nameserver
/// failures funnel into `permanent-resolver-failure`; transient errors
/// (cancelation, would-block) become `temporary-resolver-failure`;
/// "no such host" maps to `name-unresolvable`.
fn mapDnsError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.UnknownHostName, error.NoAddressReturned => .name_unresolvable,
        error.Canceled, error.WouldBlock => .temporary_resolver_failure,
        error.ResolvConfParseFailed,
        error.InvalidDnsARecord,
        error.InvalidDnsAAAARecord,
        error.InvalidDnsCnameRecord,
        error.NameServerFailure,
        error.DetectingNetworkConfigurationFailed,
        => .permanent_resolver_failure,
        else => .permanent_resolver_failure,
    };
}

/// Lower a Zig `std.Io.net.IpAddress` into the wasi:sockets
/// `ip-address` variant: `variant { ipv4(tuple<u8 x 4>), ipv6(tuple<u16 x 8>) }`.
/// Caller owns the returned `InterfaceValue` (free via `deinit`).
fn lowerIpAddress(allocator: Allocator, addr: std.Io.net.IpAddress) !InterfaceValue {
    switch (addr) {
        .ip4 => |v4| {
            const bytes = v4.bytes;
            const octets = try allocator.alloc(InterfaceValue, 4);
            errdefer allocator.free(octets);
            inline for (0..4) |i| octets[i] = .{ .u8 = bytes[i] };
            const tup = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(tup);
            tup.* = .{ .tuple_val = octets };
            return .{ .variant_val = .{
                .discriminant = @intFromEnum(IpAddressFamily.ipv4),
                .payload = tup,
            } };
        },
        .ip6 => |v6| {
            const bytes = v6.bytes;
            const groups = try allocator.alloc(InterfaceValue, 8);
            errdefer allocator.free(groups);
            inline for (0..8) |i| {
                const hi: u16 = bytes[i * 2];
                const lo: u16 = bytes[i * 2 + 1];
                groups[i] = .{ .u16 = (hi << 8) | lo };
            }
            const tup = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(tup);
            tup.* = .{ .tuple_val = groups };
            return .{ .variant_val = .{
                .discriminant = @intFromEnum(IpAddressFamily.ipv6),
                .payload = tup,
            } };
        },
    }
}

/// Lift a wasi:sockets `ip-socket-address` variant value into a Zig
/// `std.Io.net.IpAddress`. Validates the variant arm matches `family`
/// (returns `error.FamilyMismatch`); rejects malformed records that
/// don't match the WIT shape (returns `error.InvalidArgs`).
///
/// WIT (0.2.6):
///   record ipv4-socket-address { port: u16, address: tuple<u8,u8,u8,u8> }
///   record ipv6-socket-address { port: u16, flow-info: u32,
///                                 address: tuple<u16,u16,u16,u16,u16,u16,u16,u16>,
///                                 scope-id: u32 }
fn liftIpSocketAddress(
    val: InterfaceValue,
    family: IpAddressFamily,
) error{ InvalidArgs, FamilyMismatch }!std.Io.net.IpAddress {
    const variant = switch (val) {
        .variant_val => |v| v,
        else => return error.InvalidArgs,
    };
    const arm: IpAddressFamily = if (variant.discriminant == 0) .ipv4 else .ipv6;
    if (arm != family) return error.FamilyMismatch;
    const payload = variant.payload orelse return error.InvalidArgs;
    const fields = switch (payload.*) {
        .record_val => |r| r,
        else => return error.InvalidArgs,
    };
    switch (arm) {
        .ipv4 => {
            if (fields.len < 2) return error.InvalidArgs;
            const port: u16 = switch (fields[0]) {
                .u16 => |p| p,
                else => return error.InvalidArgs,
            };
            const addr_tuple = switch (fields[1]) {
                .tuple_val => |t| t,
                else => return error.InvalidArgs,
            };
            if (addr_tuple.len != 4) return error.InvalidArgs;
            var bytes: [4]u8 = undefined;
            inline for (0..4) |i| {
                bytes[i] = switch (addr_tuple[i]) {
                    .u8 => |b| b,
                    else => return error.InvalidArgs,
                };
            }
            return .{ .ip4 = .{ .bytes = bytes, .port = port } };
        },
        .ipv6 => {
            if (fields.len < 4) return error.InvalidArgs;
            const port: u16 = switch (fields[0]) {
                .u16 => |p| p,
                else => return error.InvalidArgs,
            };
            const flow: u32 = switch (fields[1]) {
                .u32 => |f| f,
                else => return error.InvalidArgs,
            };
            const addr_tuple = switch (fields[2]) {
                .tuple_val => |t| t,
                else => return error.InvalidArgs,
            };
            if (addr_tuple.len != 8) return error.InvalidArgs;
            // WIT scope-id is captured but the std type holds it as an
            // Interface (none/index/name). PR A drops the scope id; it
            // will round-trip as 0 in `lowerIpSocketAddress`. The
            // listen/bind paths that PR A exposes don't need scoped
            // addresses.
            _ = fields[3];
            var bytes: [16]u8 = undefined;
            inline for (0..8) |i| {
                const group: u16 = switch (addr_tuple[i]) {
                    .u16 => |g| g,
                    else => return error.InvalidArgs,
                };
                bytes[i * 2] = @intCast((group >> 8) & 0xff);
                bytes[i * 2 + 1] = @intCast(group & 0xff);
            }
            return .{ .ip6 = .{ .port = port, .bytes = bytes, .flow = flow } };
        },
    }
}

/// Lower a `std.Io.net.IpAddress` into a wasi:sockets
/// `ip-socket-address` variant. Caller owns the returned
/// `InterfaceValue` (free via `.deinit(allocator)`).
fn lowerIpSocketAddress(allocator: Allocator, addr: std.Io.net.IpAddress) !InterfaceValue {
    switch (addr) {
        .ip4 => |v4| {
            const octets = try allocator.alloc(InterfaceValue, 4);
            errdefer allocator.free(octets);
            inline for (0..4) |i| octets[i] = .{ .u8 = v4.bytes[i] };
            const fields = try allocator.alloc(InterfaceValue, 2);
            errdefer allocator.free(fields);
            fields[0] = .{ .u16 = v4.port };
            fields[1] = .{ .tuple_val = octets };
            const rec = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(rec);
            rec.* = .{ .record_val = fields };
            return .{ .variant_val = .{
                .discriminant = @intFromEnum(IpAddressFamily.ipv4),
                .payload = rec,
            } };
        },
        .ip6 => |v6| {
            const groups = try allocator.alloc(InterfaceValue, 8);
            errdefer allocator.free(groups);
            inline for (0..8) |i| {
                const hi: u16 = v6.bytes[i * 2];
                const lo: u16 = v6.bytes[i * 2 + 1];
                groups[i] = .{ .u16 = (hi << 8) | lo };
            }
            const fields = try allocator.alloc(InterfaceValue, 4);
            errdefer allocator.free(fields);
            fields[0] = .{ .u16 = v6.port };
            fields[1] = .{ .u32 = v6.flow };
            fields[2] = .{ .tuple_val = groups };
            // PR A elides scope-id (Interface enum doesn't carry an
            // integer index in all variants); always lower as 0.
            fields[3] = .{ .u32 = 0 };
            const rec = try allocator.create(InterfaceValue);
            errdefer allocator.destroy(rec);
            rec.* = .{ .record_val = fields };
            return .{ .variant_val = .{
                .discriminant = @intFromEnum(IpAddressFamily.ipv6),
                .payload = rec,
            } };
        },
    }
}

/// Map an `IpAddress.BindError` to a `wasi:sockets/network.error-code`.
fn mapSocketBindError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.AddressInUse => .address_in_use,
        error.AddressUnavailable => .address_not_bindable,
        error.AddressFamilyUnsupported => .invalid_argument,
        error.SystemResources, error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded => .new_socket_limit,
        error.NetworkDown => .remote_unreachable,
        error.AccessDenied => .access_denied,
        else => .unknown,
    };
}

/// Open a kernel socket, bind to `address`, and getsockname for the
/// kernel-resolved local address. Wraps the result in the same
/// `std.Io.net.Socket` shape that `IpAddress.bind` returns so existing
/// `close`/`send`/`receive` paths work transparently.
///
/// Two parallel implementations, kept in sync by the unit tests
/// further down:
///   - POSIX (`linux`, `macos`, …): raw `socket(2)` / `setsockopt(2)` /
///     `bind(2)` / `getsockname(2)` syscalls via `std.posix.system`.
///   - Windows: raw `socket` / `setsockopt` / `bind` / `getsockname`
///     calls via the `ws2_32.dll` Winsock 2 API
///     (`bindAndGetsocknameWindows`). Mirrors the POSIX flow so
///     `sockets-tcp-bind::test_reuseaddr` passes when a Windows CI
///     worker eventually runs the p3 suite. (#583 A6)
///
/// The reason for not just calling `std.Io.net.IpAddress.bind` is
/// twofold:
///   1. A per-socket setsockopt phase between socket(2) and bind(2) is
///      required to mirror wasmtime's host-managed bind: we set
///      `SO_REUSEADDR=1` so a host that closed its first socket can
///      immediately rebind to the same kernel-assigned ephemeral port
///      while its accepted-child sockets are still in TIME_WAIT.
///      Required by `sockets-tcp-bind::test_reuseaddr`. SO_REUSEPORT
///      is intentionally NOT set — wasmtime doesn't either, and
///      setting it would let a concurrent active bind succeed, which
///      would in turn break the
///      `sockets-tcp-connect::test_explicit_bind_addrinuse` /
///      `sockets-udp-connect::test_explicit_bind_addrinuse` cases
///      (see wasmtime
///      `crates/wasi/src/sockets/util.rs::tcp_bind`). On Windows,
///      `SO_REUSEADDR` has SO_REUSEPORT-like semantics (it lets a
///      second socket *steal* an actively-bound port), but the host's
///      `bindWouldConflict` already gates active-bind reuse at the
///      adapter layer so the two `test_explicit_bind_addrinuse`
///      fixtures still surface `AddressInUse` correctly.
///   2. Centralising the `getsockname` step ensures the returned
///      `Socket.address` always carries the kernel-resolved ephemeral
///      port — defensive against stdlib drift where some
///      `netBindIp` variants might skip the getsockname refresh.
///
/// Returns a `BindWithReuseError` superset of the stdlib `BindError` —
/// `mapBindWithReuseError` collapses it back to a `SocketErrorCode`
/// without losing the host-specific access-denied / family-mismatch
/// classifications.
fn bindAndGetsockname(
    address: std.Io.net.IpAddress,
    mode: std.Io.net.Socket.Mode,
    protocol: ?std.Io.net.Protocol,
) BindWithReuseError!std.Io.net.Socket {
    const native_os = @import("builtin").os.tag;
    if (native_os == .windows) {
        return bindAndGetsocknameWindows(address, mode, protocol);
    }
    // POSIX path — raw syscalls so we can interleave setsockopt
    // between socket(2) and bind(2).
    const fam: std.posix.sa_family_t = switch (address) {
        .ip4 => std.posix.AF.INET,
        .ip6 => std.posix.AF.INET6,
    };
    const sock_type: u32 = switch (mode) {
        .stream => std.posix.SOCK.STREAM,
        .dgram => std.posix.SOCK.DGRAM,
        else => return error.SocketModeUnsupported,
    };
    const proto: u32 = if (protocol) |p| switch (p) {
        .tcp => std.posix.IPPROTO.TCP,
        .udp => std.posix.IPPROTO.UDP,
        else => 0,
    } else 0;
    // On Darwin (and Haiku) `SOCK.CLOEXEC` is a Zig-supplied shim — not a real
    // BSD kernel flag — so it must NOT be OR'd into the raw `socket(2)` type
    // argument or the kernel rejects it with EINVAL. Instead, do a bare
    // `socket(2)` and apply FD_CLOEXEC via `fcntl(F_SETFD, …)` afterwards.
    // This mirrors `std.Io.Threaded.openSocketPosix` (Threaded.zig:12243).
    const socket_flags_unsupported = switch (native_os) {
        .macos, .ios, .tvos, .watchos, .visionos, .driverkit, .maccatalyst, .haiku => true,
        else => false,
    };
    const flags: u32 = sock_type | if (socket_flags_unsupported) 0 else std.posix.SOCK.CLOEXEC;
    const sock_rc = std.posix.system.socket(fam, flags, proto);
    switch (std.posix.errno(sock_rc)) {
        .SUCCESS => {},
        .ACCES => return error.AccessDenied,
        .AFNOSUPPORT => return error.AddressFamilyUnsupported,
        .MFILE => return error.ProcessFdQuotaExceeded,
        .NFILE => return error.SystemFdQuotaExceeded,
        .NOBUFS, .NOMEM => return error.SystemResources,
        .PROTONOSUPPORT => return error.ProtocolUnsupportedBySystem,
        .INVAL => return error.ProtocolUnsupportedBySystem,
        else => return error.SystemResources,
    }
    const fd: std.posix.fd_t = @intCast(sock_rc);
    errdefer _ = std.posix.system.close(fd);

    if (socket_flags_unsupported) {
        while (true) switch (std.posix.errno(std.posix.system.fcntl(
            fd,
            std.posix.F.SETFD,
            @as(usize, std.posix.FD_CLOEXEC),
        ))) {
            .SUCCESS => break,
            .INTR => continue,
            else => return error.SystemResources,
        };
    }

    // SO_REUSEADDR is required by `sockets-tcp-bind::test_reuseaddr`
    // (around line 231 of the upstream fixture): the fixture binds to
    // an ephemeral port, drops the server (which had an established
    // accepted child), and immediately rebinds a fresh socket on the
    // same port. The accepted child sits in TIME_WAIT for ~60 s on
    // Linux, so without SO_REUSEADDR the rebind returns EADDRINUSE.
    // Linux's SO_REUSEADDR still refuses to bind on top of an
    // *actively-bound* port — neither socket in
    // `sockets-tcp-connect::test_explicit_bind_addrinuse` /
    // `sockets-udp-connect::test_explicit_bind_addrinuse` has been
    // dropped at that point, so those tests continue to surface
    // `AddressInUse` correctly even with REUSEADDR set on both fds
    // (because the active-bind path is unaffected by SO_REUSEADDR;
    // it's the TIME_WAIT / closed-fd path that REUSEADDR governs).
    // The `ComponentInstance.on_resource_drop` hook installed by
    // `runLoadedComponent` (also #575) ensures the host fd of the
    // first bind is released synchronously on guest drop so the
    // active-bind precondition for `test_explicit_bind_addrinuse`
    // remains intact: only the brief kernel TIME_WAIT window — which
    // REUSEADDR exists to bypass — is in play for `test_reuseaddr`.
    // Matches wasmtime's `crates/wasi/src/sockets/util.rs::tcp_bind`,
    // which sets SO_REUSEADDR unconditionally on POSIX. SO_REUSEPORT
    // is NOT set (wasmtime doesn't either, and it would let a
    // concurrent active bind succeed). (#575)
    _ = socketSetU32Opt(fd, SOL_SOCKET_OPT, SO_REUSEADDR_OPT, 1);

    // Build the sockaddr storage and call bind(2).
    var storage: std.posix.sockaddr.storage = std.mem.zeroes(std.posix.sockaddr.storage);
    var addr_len: std.posix.socklen_t = 0;
    switch (address) {
        .ip4 => |v4| {
            const sa_in: *std.posix.sockaddr.in = @ptrCast(@alignCast(&storage));
            sa_in.* = .{
                .family = std.posix.AF.INET,
                .port = std.mem.nativeToBig(u16, v4.port),
                .addr = @bitCast(v4.bytes),
                .zero = [_]u8{0} ** 8,
            };
            addr_len = @sizeOf(std.posix.sockaddr.in);
        },
        .ip6 => |v6| {
            const sa_in6: *std.posix.sockaddr.in6 = @ptrCast(@alignCast(&storage));
            sa_in6.* = .{
                .family = std.posix.AF.INET6,
                .port = std.mem.nativeToBig(u16, v6.port),
                .flowinfo = v6.flow,
                .addr = v6.bytes,
                .scope_id = 0,
            };
            addr_len = @sizeOf(std.posix.sockaddr.in6);
        },
    }
    const bind_rc = std.posix.system.bind(fd, @ptrCast(&storage), addr_len);
    switch (std.posix.errno(bind_rc)) {
        .SUCCESS => {},
        .ACCES => return error.AccessDenied,
        .ADDRINUSE => return error.AddressInUse,
        .ADDRNOTAVAIL => return error.AddressUnavailable,
        .AFNOSUPPORT => return error.AddressFamilyUnsupported,
        .NOBUFS, .NOMEM => return error.SystemResources,
        else => return error.SystemResources,
    }

    // getsockname → resolve ephemeral port.
    var got_storage: std.posix.sockaddr.storage = std.mem.zeroes(std.posix.sockaddr.storage);
    var got_len: std.posix.socklen_t = @sizeOf(std.posix.sockaddr.storage);
    const gs_rc = std.posix.system.getsockname(fd, @ptrCast(&got_storage), &got_len);
    if (std.posix.errno(gs_rc) != .SUCCESS) return error.SystemResources;

    const local: std.Io.net.IpAddress = switch (address) {
        .ip4 => blk: {
            const sa: *const std.posix.sockaddr.in = @ptrCast(@alignCast(&got_storage));
            break :blk .{ .ip4 = .{
                .bytes = @bitCast(sa.addr),
                .port = std.mem.bigToNative(u16, sa.port),
            } };
        },
        .ip6 => blk: {
            const sa: *const std.posix.sockaddr.in6 = @ptrCast(@alignCast(&got_storage));
            break :blk .{ .ip6 = .{
                .bytes = sa.addr,
                .port = std.mem.bigToNative(u16, sa.port),
                .flow = sa.flowinfo,
            } };
        },
    };
    return .{ .handle = fd, .address = local };
}

// ── Windows direct-Winsock externs (#583 A6) ────────────────────────
//
// `std.os.windows.ws2_32` in Zig 0.16.0 is a *types-and-constants*
// namespace — it intentionally exposes none of the actual `ws2_32.dll`
// procedure exports (`socket`, `bind`, `setsockopt`, `getsockname`,
// `closesocket`, `WSAStartup`, `WSAGetLastError`) because the stdlib
// `std.Io.Threaded` Windows socket backend bypasses Winsock entirely
// and talks to the AFD endpoint (\Device\Afd\Endpoint) via
// `NtCreateFile`/`NtDeviceIoControlFile`. That AFD path doesn't
// permit interleaving a `SO_REUSEADDR` `setsockopt` between socket
// creation and bind in the way `bindAndGetsockname` needs.
//
// We therefore declare the small set of Winsock 2 entry points we
// need here as private externs against `ws2_32.dll`. The set mirrors
// what wasmtime's `crates/wasi/src/sockets/util.rs::tcp_bind` reaches
// for on Windows (`socket2::Socket::new` + `set_reuse_address` +
// `bind` + `local_addr`).
//
// Calling these without a prior `WSAStartup` returns `WSANOTINITIALISED`
// (10093). `ensureWsaStartup` is a refcount-leaking idempotent
// initialiser — repeat calls are documented as safe by MSDN. We never
// call `WSACleanup` because the kernel reclaims the per-process
// Winsock state at process exit anyway.
const ws2_32_extern = struct {
    pub const SOCKET = usize;
    pub const INVALID_SOCKET: SOCKET = ~@as(usize, 0);
    pub const SOCKET_ERROR: c_int = -1;

    extern "ws2_32" fn WSAStartup(
        wVersionRequested: u16,
        lpWSAData: *anyopaque,
    ) callconv(.winapi) c_int;
    extern "ws2_32" fn WSAGetLastError() callconv(.winapi) c_int;
    extern "ws2_32" fn socket(
        af: c_int,
        type_: c_int,
        protocol: c_int,
    ) callconv(.winapi) SOCKET;
    extern "ws2_32" fn closesocket(s: SOCKET) callconv(.winapi) c_int;
    extern "ws2_32" fn bind(
        s: SOCKET,
        name: *const anyopaque,
        namelen: c_int,
    ) callconv(.winapi) c_int;
    extern "ws2_32" fn setsockopt(
        s: SOCKET,
        level: c_int,
        optname: c_int,
        optval: [*]const u8,
        optlen: c_int,
    ) callconv(.winapi) c_int;
    extern "ws2_32" fn getsockname(
        s: SOCKET,
        name: *anyopaque,
        namelen: *c_int,
    ) callconv(.winapi) c_int;
};

/// Selected `WSAGetLastError` codes that `bindAndGetsocknameWindows`
/// classifies. Numbered per MSDN; not exhaustive — anything else
/// collapses to `error.SystemResources` and is then mapped to
/// `unknown` by `mapSocketBindError`.
const WSAE = struct {
    pub const INTR: c_int = 10004;
    pub const ACCES: c_int = 10013;
    pub const FAULT: c_int = 10014;
    pub const INVAL: c_int = 10022;
    pub const MFILE: c_int = 10024;
    pub const NOBUFS: c_int = 10055;
    pub const ADDRINUSE: c_int = 10048;
    pub const ADDRNOTAVAIL: c_int = 10049;
    pub const AFNOSUPPORT: c_int = 10047;
    pub const SOCKTNOSUPPORT: c_int = 10044;
    pub const PROTONOSUPPORT: c_int = 10043;
};

/// Idempotent `WSAStartup(2.2)`. Safe to call concurrently — MSDN
/// guarantees repeated `WSAStartup` calls increment an internal
/// refcount and return immediately on subsequent calls. We never
/// pair them with `WSACleanup`; per-process Winsock state is
/// reclaimed at process exit.
var wsa_started: std.atomic.Value(u32) = .init(0);
fn ensureWsaStartup() void {
    if (wsa_started.load(.acquire) != 0) return;
    // `WSADATA` is 408 bytes on x86_64 (LPWSADATA in the SDK). The
    // 512-byte stack buffer is a deliberate over-allocation — we
    // never read the fields.
    var data: [512]u8 = undefined;
    _ = ws2_32_extern.WSAStartup(0x0202, @ptrCast(&data));
    wsa_started.store(1, .release);
}

/// Windows arm of `bindAndGetsockname`. Mirrors the POSIX flow via
/// direct `ws2_32.dll` calls so a `SO_REUSEADDR` `setsockopt` can be
/// interleaved between socket creation and `bind`. The returned
/// `std.Io.net.Socket.Handle` is the raw Winsock `SOCKET` cast to
/// `windows.HANDLE` (`?*anyopaque`) — `Socket.close` on the
/// `Threaded` backend forwards it to `CloseHandle`, which Windows
/// documents as a valid close for SOCKET handles (it delegates to
/// the kernel-mode AFD driver under the hood). (#583 A6)
fn bindAndGetsocknameWindows(
    address: std.Io.net.IpAddress,
    mode: std.Io.net.Socket.Mode,
    protocol: ?std.Io.net.Protocol,
) BindWithReuseError!std.Io.net.Socket {
    const windows = std.os.windows;
    const ws2_32 = windows.ws2_32;

    ensureWsaStartup();

    const family: c_int = switch (address) {
        .ip4 => ws2_32.AF.INET,
        .ip6 => ws2_32.AF.INET6,
    };
    const sock_type: c_int = switch (mode) {
        .stream => ws2_32.SOCK.STREAM,
        .dgram => ws2_32.SOCK.DGRAM,
        else => return error.SocketModeUnsupported,
    };
    const proto: c_int = if (protocol) |p| switch (p) {
        .tcp => ws2_32.IPPROTO.TCP,
        .udp => ws2_32.IPPROTO.UDP,
        else => 0,
    } else 0;

    const sock = ws2_32_extern.socket(family, sock_type, proto);
    if (sock == ws2_32_extern.INVALID_SOCKET) {
        return switch (ws2_32_extern.WSAGetLastError()) {
            WSAE.ACCES => error.AccessDenied,
            WSAE.AFNOSUPPORT => error.AddressFamilyUnsupported,
            WSAE.MFILE => error.ProcessFdQuotaExceeded,
            WSAE.NOBUFS => error.SystemResources,
            WSAE.PROTONOSUPPORT,
            WSAE.SOCKTNOSUPPORT,
            WSAE.INVAL,
            => error.ProtocolUnsupportedBySystem,
            else => error.SystemResources,
        };
    }
    errdefer _ = ws2_32_extern.closesocket(sock);

    // SO_REUSEADDR — required by `sockets-tcp-bind::test_reuseaddr`
    // (see `bindAndGetsockname` doc comment). Winsock semantics
    // differ from POSIX (it permits a *second* active bind to steal
    // the port), but the host's `bindWouldConflict` gate filters
    // those cases at the adapter layer, so the TIME_WAIT-rebind case
    // remains the one this option enables. Mirrors wasmtime's POSIX
    // `set_reuse_address(true)` call.
    const one: u32 = 1;
    const one_bytes = std.mem.toBytes(one);
    _ = ws2_32_extern.setsockopt(
        sock,
        ws2_32.SOL.SOCKET,
        ws2_32.SO.REUSEADDR,
        &one_bytes,
        @sizeOf(u32),
    );

    // Build the Winsock sockaddr_in / sockaddr_in6 and call bind.
    var storage: ws2_32.sockaddr.storage = std.mem.zeroes(ws2_32.sockaddr.storage);
    var addr_len: c_int = 0;
    switch (address) {
        .ip4 => |v4| {
            const sa_in: *ws2_32.sockaddr.in = @ptrCast(@alignCast(&storage));
            sa_in.* = .{
                .family = ws2_32.AF.INET,
                .port = std.mem.nativeToBig(u16, v4.port),
                .addr = @bitCast(v4.bytes),
            };
            addr_len = @sizeOf(ws2_32.sockaddr.in);
        },
        .ip6 => |v6| {
            const sa_in6: *ws2_32.sockaddr.in6 = @ptrCast(@alignCast(&storage));
            sa_in6.* = .{
                .family = ws2_32.AF.INET6,
                .port = std.mem.nativeToBig(u16, v6.port),
                .flowinfo = v6.flow,
                .addr = v6.bytes,
                .scope_id = 0,
            };
            addr_len = @sizeOf(ws2_32.sockaddr.in6);
        },
    }
    if (ws2_32_extern.bind(sock, @ptrCast(&storage), addr_len) == ws2_32_extern.SOCKET_ERROR) {
        return switch (ws2_32_extern.WSAGetLastError()) {
            WSAE.ACCES => error.AccessDenied,
            WSAE.ADDRINUSE => error.AddressInUse,
            WSAE.ADDRNOTAVAIL => error.AddressUnavailable,
            WSAE.AFNOSUPPORT => error.AddressFamilyUnsupported,
            WSAE.NOBUFS => error.SystemResources,
            WSAE.INVAL => error.AddressInUse,
            else => error.SystemResources,
        };
    }

    // getsockname — resolve the kernel-assigned ephemeral port for
    // the port-0 case (and confirm the bind for the explicit-port
    // case).
    var got_storage: ws2_32.sockaddr.storage = std.mem.zeroes(ws2_32.sockaddr.storage);
    var got_len: c_int = @sizeOf(ws2_32.sockaddr.storage);
    if (ws2_32_extern.getsockname(sock, @ptrCast(&got_storage), &got_len) == ws2_32_extern.SOCKET_ERROR) {
        return error.SystemResources;
    }

    const local: std.Io.net.IpAddress = switch (address) {
        .ip4 => blk: {
            const sa: *const ws2_32.sockaddr.in = @ptrCast(@alignCast(&got_storage));
            break :blk .{ .ip4 = .{
                .bytes = @bitCast(sa.addr),
                .port = std.mem.bigToNative(u16, sa.port),
            } };
        },
        .ip6 => blk: {
            const sa: *const ws2_32.sockaddr.in6 = @ptrCast(@alignCast(&got_storage));
            break :blk .{ .ip6 = .{
                .bytes = sa.addr,
                .port = std.mem.bigToNative(u16, sa.port),
                .flow = sa.flowinfo,
            } };
        },
    };

    // Cast the Winsock SOCKET (an opaque integer) to the
    // `std.posix.fd_t` shape Zig uses for socket handles on Windows
    // (`windows.HANDLE` = `?*anyopaque`). `Socket.close` →
    // `Threaded.netClose` → `windows.CloseHandle` correctly disposes
    // of the underlying AFD endpoint.
    const fd: std.Io.net.Socket.Handle = @ptrFromInt(sock);
    return .{ .handle = fd, .address = local };
}

/// Superset of `std.Io.net.IpAddress.BindError` carried through
/// `bindAndGetsockname` — adds `AccessDenied` (returned by socket(2)
/// EACCES on some POSIX systems) which the stdlib bind path lifts to
/// `error.Unexpected`. `mapSocketBindError` knows how to route
/// either.
const BindWithReuseError = std.Io.net.IpAddress.BindError || error{AccessDenied};

/// Build a raw POSIX `sockaddr_storage` from a Zig
/// `std.Io.net.IpAddress`. Returns the storage by value plus the
/// effective length (`sa_family_t` + family-specific tail) so the
/// caller can pass either to `bind(2)`, `connect(2)`, or
/// `getsockname(2)`. (#569)
fn ipAddressToPosixStorage(
    address: std.Io.net.IpAddress,
) struct { storage: std.posix.sockaddr.storage, len: std.posix.socklen_t } {
    var storage: std.posix.sockaddr.storage = std.mem.zeroes(std.posix.sockaddr.storage);
    var addr_len: std.posix.socklen_t = 0;
    switch (address) {
        .ip4 => |v4| {
            const sa_in: *std.posix.sockaddr.in = @ptrCast(@alignCast(&storage));
            sa_in.* = .{
                .family = std.posix.AF.INET,
                .port = std.mem.nativeToBig(u16, v4.port),
                .addr = @bitCast(v4.bytes),
                .zero = [_]u8{0} ** 8,
            };
            addr_len = @sizeOf(std.posix.sockaddr.in);
        },
        .ip6 => |v6| {
            const sa_in6: *std.posix.sockaddr.in6 = @ptrCast(@alignCast(&storage));
            sa_in6.* = .{
                .family = std.posix.AF.INET6,
                .port = std.mem.nativeToBig(u16, v6.port),
                .flowinfo = v6.flow,
                .addr = v6.bytes,
                .scope_id = 0,
            };
            addr_len = @sizeOf(std.posix.sockaddr.in6);
        },
    }
    return .{ .storage = storage, .len = addr_len };
}

/// Call `connect(2)` on a kernel UDP fd so the kernel records the
/// remote address and (for wildcard-bound sockets) refines the
/// outbound interface IP. Returns the same error set as
/// `std.Io.net.IpAddress.ConnectError` so callers can pipe straight
/// into `mapConnectError`. POSIX-only; Windows callers should skip
/// this path. (#569)
fn connectUdpKernel(
    fd: std.posix.fd_t,
    remote: std.Io.net.IpAddress,
) std.Io.net.IpAddress.ConnectError!void {
    const built = ipAddressToPosixStorage(remote);
    const rc = std.posix.system.connect(fd, @ptrCast(&built.storage), built.len);
    switch (std.posix.errno(rc)) {
        .SUCCESS => return,
        .ACCES, .PERM => return error.AccessDenied,
        .ADDRINUSE => return error.AddressUnavailable,
        .ADDRNOTAVAIL => return error.AddressUnavailable,
        .AFNOSUPPORT => return error.AddressFamilyUnsupported,
        .CONNREFUSED => return error.ConnectionRefused,
        .NETUNREACH, .NETDOWN => return error.NetworkUnreachable,
        .HOSTUNREACH => return error.HostUnreachable,
        .TIMEDOUT => return error.Timeout,
        .NOBUFS, .NOMEM => return error.SystemResources,
        else => return error.Unexpected,
    }
}

/// Call `getsockname(2)` on a kernel socket fd and return the
/// resolved `std.Io.net.IpAddress`. Returns `null` if the syscall
/// fails or the returned family doesn't match `expected_family` (a
/// belt-and-braces guard against a kernel returning AF_UNSPEC after
/// connect-then-disconnect). POSIX-only. (#569)
fn getsocknameKernel(
    fd: std.posix.fd_t,
    expected_family: IpAddressFamily,
) ?std.Io.net.IpAddress {
    var got_storage: std.posix.sockaddr.storage = std.mem.zeroes(std.posix.sockaddr.storage);
    var got_len: std.posix.socklen_t = @sizeOf(std.posix.sockaddr.storage);
    const rc = std.posix.system.getsockname(fd, @ptrCast(&got_storage), &got_len);
    if (std.posix.errno(rc) != .SUCCESS) return null;
    return switch (expected_family) {
        .ipv4 => blk: {
            const sa: *const std.posix.sockaddr.in = @ptrCast(@alignCast(&got_storage));
            if (sa.family != std.posix.AF.INET) break :blk null;
            break :blk .{ .ip4 = .{
                .bytes = @bitCast(sa.addr),
                .port = std.mem.bigToNative(u16, sa.port),
            } };
        },
        .ipv6 => blk: {
            const sa: *const std.posix.sockaddr.in6 = @ptrCast(@alignCast(&got_storage));
            if (sa.family != std.posix.AF.INET6) break :blk null;
            break :blk .{ .ip6 = .{
                .bytes = sa.addr,
                .port = std.mem.bigToNative(u16, sa.port),
                .flow = sa.flowinfo,
            } };
        },
    };
}

/// Map an `IpAddress.ListenError` to a `wasi:sockets/network.error-code`.
fn mapSocketListenError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.AddressInUse => .address_in_use,
        error.AddressUnavailable => .address_not_bindable,
        error.AddressFamilyUnsupported => .invalid_argument,
        error.SystemResources, error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded => .new_socket_limit,
        error.NetworkDown => .remote_unreachable,
        error.AccessDenied => .access_denied,
        else => .unknown,
    };
}

/// Map an `IpAddress.ConnectError` to a `wasi:sockets/network.error-code`.
fn mapConnectError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.ConnectionRefused => .connection_refused,
        error.ConnectionResetByPeer => .connection_reset,
        error.NetworkUnreachable, error.NetworkDown => .remote_unreachable,
        error.HostUnreachable => .remote_unreachable,
        error.Timeout => .timeout,
        error.AddressInUse => .address_in_use,
        error.AddressUnavailable => .address_not_bindable,
        error.AddressFamilyUnsupported => .invalid_argument,
        error.SystemResources, error.ProcessFdQuotaExceeded, error.SystemFdQuotaExceeded => .new_socket_limit,
        error.AccessDenied => .access_denied,
        else => .unknown,
    };
}

/// Map a `Socket.SendError` to a `wasi:sockets/network.error-code`.
fn mapSocketSendError(err: anyerror) SocketErrorCode {
    return switch (err) {
        error.MessageOversize => .datagram_too_large,
        error.NetworkUnreachable, error.NetworkDown => .remote_unreachable,
        error.HostUnreachable => .remote_unreachable,
        error.ConnectionRefused => .connection_refused,
        error.ConnectionResetByPeer => .connection_reset,
        error.AccessDenied => .access_denied,
        error.AddressFamilyUnsupported => .invalid_argument,
        error.SystemResources => .out_of_memory,
        else => .unknown,
    };
}

/// Read a u32-valued socket option via `getsockopt(2)`. Returns the
/// kernel value on success, or `null` on error / unsupported platform.
fn socketGetU32Opt(fd: std.posix.fd_t, level: i32, optname: u32) ?u32 {
    const native_os = @import("builtin").os.tag;
    var val: u32 = 0;
    var optlen: std.posix.socklen_t = @sizeOf(u32);
    if (native_os == .linux) {
        const rc = std.os.linux.getsockopt(
            @intCast(fd),
            level,
            optname,
            @ptrCast(std.mem.asBytes(&val)),
            &optlen,
        );
        if (std.posix.errno(rc) != .SUCCESS) return null;
    } else if (native_os == .windows) {
        const windows = std.os.windows;
        if (level == SOL_SOCKET_OPT and (optname == SO_RCVBUF_OPT or optname == SO_SNDBUF_OPT)) {
            // Buffer sizes use AFD GET_INFORMATION with window-size info types
            var info = windows.AFD.INFORMATION{
                .InformationType = if (optname == SO_RCVBUF_OPT) .RECEIVE_WINDOW_SIZE else .SEND_WINDOW_SIZE,
                .Information = .{ .Ulong = 0 },
            };
            var iosb: windows.IO_STATUS_BLOCK = undefined;
            const status = windows.ntdll.NtDeviceIoControlFile(
                fd,
                null,
                null,
                null,
                &iosb,
                windows.IOCTL.AFD.GET_INFORMATION,
                @ptrCast(&info),
                @sizeOf(windows.AFD.INFORMATION),
                @ptrCast(&info),
                @sizeOf(windows.AFD.INFORMATION),
            );
            if (status == .PENDING) {
                _ = windows.ntdll.NtWaitForSingleObject(fd, .FALSE, null);
                if (iosb.u.Status != .SUCCESS) return null;
            } else if (status != .SUCCESS) {
                return null;
            }
            return info.Information.Ulong;
        }
        var info = windows.AFD.SOCKOPT_INFO{
            .mode = .get,
            .level = level,
            .optname = optname,
            .optval = @ptrCast(std.mem.asBytes(&val)),
            .optlen = @sizeOf(u32),
        };
        var iosb: windows.IO_STATUS_BLOCK = undefined;
        const status = windows.ntdll.NtDeviceIoControlFile(
            fd,
            null,
            null,
            null,
            &iosb,
            windows.IOCTL.AFD.SOCKOPT,
            @ptrCast(&info),
            @sizeOf(windows.AFD.SOCKOPT_INFO),
            @ptrCast(std.mem.asBytes(&val)),
            @sizeOf(u32),
        );
        if (status == .PENDING) {
            _ = windows.ntdll.NtWaitForSingleObject(fd, .FALSE, null);
            if (iosb.u.Status != .SUCCESS) return null;
        } else if (status != .SUCCESS) {
            return null;
        }
    } else {
        // macOS / other POSIX — use libc
        const rc = std.c.getsockopt(
            fd,
            level,
            optname,
            @ptrCast(&val),
            &optlen,
        );
        if (rc != 0) return null;
    }
    return val;
}

/// TCP keep-alive idle time socket option. macOS uses `TCP_KEEPALIVE`
/// (0x10) instead of Linux's `TCP_KEEPIDLE`.
const TCP_KEEPIDLE_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x10, // TCP_KEEPALIVE
    .linux => 4,
    .windows => 3, // TCP_KEEPALIVE (same function as Linux TCP_KEEPIDLE)
    else => 4,
};

/// IP-level socket option constants, defined portably since
/// `std.posix.IP`/`std.posix.IPV6` may be void on some platforms.
const IP_TTL_OPT: u32 = switch (@import("builtin").os.tag) {
    .linux => 2,
    .macos, .ios, .tvos, .watchos => 4,
    .windows => 4,
    else => 2,
};
const IPV6_UNICAST_HOPS_OPT: u32 = switch (@import("builtin").os.tag) {
    .linux => 16,
    .macos, .ios, .tvos, .watchos => 4,
    .windows => 4,
    else => 16,
};
const IPPROTO_IP_OPT: i32 = 0;
const IPPROTO_IPV6_OPT: i32 = 41;
const IPPROTO_TCP_OPT: i32 = 6;
const SOL_SOCKET_OPT: i32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0xffff,
    .windows => 0xffff,
    else => 1, // Linux
};
const SO_RCVBUF_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x1002,
    .windows => 0x1002,
    else => 8, // Linux
};
const SO_SNDBUF_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x1001,
    .windows => 0x1001,
    else => 7, // Linux
};
const SO_KEEPALIVE_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x0008,
    .windows => 0x0008,
    else => 9, // Linux
};
/// SO_REUSEADDR — set unconditionally on POSIX between `socket(2)` and
/// `bind(2)` by `bindAndGetsockname` so that an immediate rebind to a
/// TIME_WAIT port succeeds (required by
/// `sockets-tcp-bind::test_reuseaddr`). Matches wasmtime's
/// `crates/wasi/src/sockets/util.rs::tcp_bind`. (#575)
const SO_REUSEADDR_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x0004,
    .windows => 0x0004,
    else => 2, // Linux
};
const TCP_KEEPINTVL_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x101,
    .windows => 17,
    else => 5, // Linux
};
const TCP_KEEPCNT_OPT: u32 = switch (@import("builtin").os.tag) {
    .macos, .ios, .tvos, .watchos => 0x102,
    .windows => 16,
    else => 6, // Linux
};

/// Set a u32-valued socket option via `setsockopt(2)`. Returns `null`
/// on success, or an error code on failure.
fn socketSetU32Opt(fd: std.posix.fd_t, level: i32, optname: u32, value: u32) ?SocketErrorCode {
    const native_os = @import("builtin").os.tag;
    const bytes = std.mem.toBytes(value);
    if (native_os == .windows) {
        const windows = std.os.windows;
        var iosb: windows.IO_STATUS_BLOCK = undefined;
        if (level == SOL_SOCKET_OPT and (optname == SO_RCVBUF_OPT or optname == SO_SNDBUF_OPT)) {
            // Buffer sizes use AFD SET_INFORMATION with window-size info types
            const status = windows.ntdll.NtDeviceIoControlFile(
                fd,
                null,
                null,
                null,
                &iosb,
                windows.IOCTL.AFD.SET_INFORMATION,
                @ptrCast(&windows.AFD.INFORMATION{
                    .InformationType = if (optname == SO_RCVBUF_OPT) .RECEIVE_WINDOW_SIZE else .SEND_WINDOW_SIZE,
                    .Information = .{ .Ulong = value },
                }),
                @sizeOf(windows.AFD.INFORMATION),
                null,
                0,
            );
            if (status == .PENDING) {
                _ = windows.ntdll.NtWaitForSingleObject(fd, .FALSE, null);
                if (iosb.u.Status != .SUCCESS) return .unknown;
            } else if (status != .SUCCESS) {
                return .unknown;
            }
            return null;
        }
        const status = windows.ntdll.NtDeviceIoControlFile(
            fd,
            null,
            null,
            null,
            &iosb,
            windows.IOCTL.AFD.SOCKOPT,
            @ptrCast(&windows.AFD.SOCKOPT_INFO{
                .mode = .set,
                .level = level,
                .optname = optname,
                .optval = @ptrCast(&bytes),
                .optlen = @sizeOf(u32),
            }),
            @sizeOf(windows.AFD.SOCKOPT_INFO),
            null,
            0,
        );
        if (status == .PENDING) {
            _ = windows.ntdll.NtWaitForSingleObject(fd, .FALSE, null);
            if (iosb.u.Status != .SUCCESS) return .unknown;
        } else if (status != .SUCCESS) {
            return .unknown;
        }
        return null;
    } else if (native_os == .linux) {
        const rc = std.os.linux.setsockopt(
            @intCast(fd),
            level,
            optname,
            @ptrCast(&bytes),
            @sizeOf(u32),
        );
        if (std.posix.errno(rc) != .SUCCESS) return .unknown;
        return null;
    } else {
        // macOS / other POSIX — use std.posix.setsockopt
        std.posix.setsockopt(fd, level, optname, &bytes) catch return .unknown;
        return null;
    }
}

/// Deep-copy a CIDR allow-list slice so the socket owns its own copy
/// (prevents UAF when the network resource is dropped first).
fn cloneAllowList(allocator: Allocator, src: []const IpCidr) ![]IpCidr {
    if (src.len == 0) return &.{};
    const dst = try allocator.alloc(IpCidr, src.len);
    @memcpy(dst, src);
    return dst;
}

/// Validate that `addr` is suitable as a send destination for the
/// given socket `family`. Returns `null` if valid, or the WIT
/// `error-code` discriminant to return on failure.
///
/// Checks (in WIT-mandated order):
///  1. family mismatch → `invalid-argument`
///  2. wildcard IP (0.0.0.0 / ::) → `invalid-argument`
///  3. port == 0 → `invalid-argument`
fn validateRemoteForSend(addr: std.Io.net.IpAddress, family: IpAddressFamily) ?SocketErrorCode {
    switch (addr) {
        .ip4 => |v4| {
            if (family != .ipv4) return .invalid_argument;
            if (std.mem.eql(u8, &v4.bytes, &.{ 0, 0, 0, 0 })) return .invalid_argument;
            if (v4.port == 0) return .invalid_argument;
        },
        .ip6 => |v6| {
            if (family != .ipv6) return .invalid_argument;
            if (std.mem.eql(u8, &v6.bytes, &(.{0} ** 16))) return .invalid_argument;
            if (v6.port == 0) return .invalid_argument;
        },
    }
    return null;
}

/// Map a Zig std.fs / std.posix error to the closest `error-code` variant.
/// Errors not represented map to `.io` so the guest still sees a
/// well-typed result rather than a host trap.
fn mapFsError(err: anyerror) FsErrorCode {
    return switch (err) {
        error.AccessDenied, error.PermissionDenied => .access,
        error.FileNotFound => .no_entry,
        error.NotDir => .not_directory,
        error.PathAlreadyExists => .exist,
        error.IsDir => .is_directory,
        error.NameTooLong => .name_too_long,
        error.SymLinkLoop => .loop,
        error.FileTooBig => .file_too_large,
        error.NoSpaceLeft => .insufficient_space,
        error.OutOfMemory => .insufficient_memory,
        error.DeviceBusy, error.FileBusy => .busy,
        error.WouldBlock => .would_block,
        error.BrokenPipe => .pipe,
        error.ReadOnlyFileSystem => .read_only,
        error.InvalidUtf8 => .illegal_byte_sequence,
        // #476: directory-mutation surface needs cross-device, not-empty,
        // unsupported-op, link-quota, disk-quota, and not-symlink mappings.
        error.CrossDevice => .cross_device,
        error.DirNotEmpty => .not_empty,
        error.OperationUnsupported => .unsupported,
        error.LinkQuotaExceeded => .too_many_links,
        error.DiskQuota => .quota,
        error.NotLink => .invalid,
        else => .io,
    };
}

/// `wasi:http/types.error-code` discriminant indices in WIT-declaration
/// order. Used as `.variant_val.discriminant` for `result<_, error-code>`
/// returns. Several variants carry payloads in the WIT (option<u64>,
/// option<string>, etc.); the adapter only ever returns no-payload
/// codes from default-deny stubs, so payload handling is deferred.
const HttpErrorCode = enum(u32) {
    DNS_timeout = 0,
    DNS_error = 1,
    destination_not_found = 2,
    destination_unavailable = 3,
    destination_IP_prohibited = 4,
    destination_IP_unroutable = 5,
    connection_refused = 6,
    connection_terminated = 7,
    connection_timeout = 8,
    connection_read_timeout = 9,
    connection_write_timeout = 10,
    connection_limit_reached = 11,
    TLS_protocol_error = 12,
    TLS_certificate_error = 13,
    TLS_alert_received = 14,
    HTTP_request_denied = 15,
    HTTP_request_length_required = 16,
    HTTP_request_body_size = 17,
    HTTP_request_method_invalid = 18,
    HTTP_request_URI_invalid = 19,
    HTTP_request_URI_too_long = 20,
    HTTP_request_header_section_size = 21,
    HTTP_request_header_size = 22,
    HTTP_request_trailer_section_size = 23,
    HTTP_request_trailer_size = 24,
    HTTP_response_incomplete = 25,
    HTTP_response_header_section_size = 26,
    HTTP_response_header_size = 27,
    HTTP_response_body_size = 28,
    HTTP_response_trailer_section_size = 29,
    HTTP_response_trailer_size = 30,
    HTTP_response_transfer_coding = 31,
    HTTP_response_content_coding = 32,
    HTTP_response_timeout = 33,
    HTTP_upgrade_failed = 34,
    HTTP_protocol_error = 35,
    loop_detected = 36,
    configuration_error = 37,
    internal_error = 38,
};

/// Map a `std.http.Client.FetchError` (or any error that reaches the
/// outbound-handler / `client.send` catch arm) onto the most specific
/// `wasi:http/types.error-code` variant we can name (#583 A3).
///
/// The full FetchError set is, transitively:
///   * `Uri.ParseError` — `InvalidFormat`, `UnexpectedCharacter`, `InvalidPort`.
///   * `Allocator.Error` — `OutOfMemory`.
///   * `HostName.LookupError` — DNS resolution failures.
///   * `IpAddress.ConnectError` / `IpAddress.BindError` — kernel-level
///     connect failures.
///   * `error{TlsInitializationFailed, CertificateBundleLoadFailure,
///     UnsupportedUriScheme, UriMissingHost}` from `Client.RequestError`.
///   * `Request.ReceiveHeadError` — HTTP/1.1 framing failures during the
///     response head parse.
///   * The leaf `error{StreamTooLong, WriteFailed, UnsupportedCompressionMethod}`
///     declared on `FetchError` itself.
///
/// Each *classified* error has its own arm below; truly-unknown errors
/// (`OutOfMemory`, `SystemResources`, `Canceled`, `Unexpected`, plus
/// anything new Zig adds to the FetchError set after this revision) fall
/// through the `else` arm to `internal_error`. The README sentence
/// promising this as follow-up work has been retired.
fn mapHttpFetchError(err: anyerror) HttpErrorCode {
    return switch (err) {
        // ── Connection-level transport (IpAddress.ConnectError) ──────────
        error.ConnectionRefused => .connection_refused,
        error.ConnectionResetByPeer,
        error.ReadFailed,
        error.WriteFailed,
        error.HttpRequestTruncated,
        error.HttpConnectionClosing,
        error.HttpChunkTruncated,
        => .connection_terminated,
        error.HostUnreachable,
        error.NetworkUnreachable,
        error.NetworkDown,
        => .destination_unavailable,
        error.Timeout => .connection_timeout,
        error.AccessDenied => .destination_IP_prohibited,

        // ── TLS (ConnectTcpError remaps `Connection.Tls.create` failures
        //    to `TlsInitializationFailed`; the bundle-load case is its own
        //    arm of `RequestError`). ───────────────────────────────────────
        error.TlsInitializationFailed => .TLS_protocol_error,
        error.CertificateBundleLoadFailure => .TLS_certificate_error,

        // ── DNS / name resolution (`HostName.LookupError`) ─────────────────
        error.UnknownHostName,
        error.NameServerFailure,
        error.InvalidDnsARecord,
        error.InvalidDnsAAAARecord,
        error.InvalidDnsCnameRecord,
        error.ResolvConfParseFailed,
        error.DetectingNetworkConfigurationFailed,
        => .DNS_error,
        error.NoAddressReturned,
        error.AddressUnavailable,
        => .destination_not_found,

        // ── URI / request shape (`Uri.ParseError` + `RequestError`) ───────
        error.UnsupportedUriScheme,
        error.UriMissingHost,
        error.UnexpectedCharacter,
        error.InvalidFormat,
        error.InvalidPort,
        => .HTTP_request_URI_invalid,

        // ── HTTP/1.1 response framing (`Request.ReceiveHeadError`) ────────
        error.HttpHeadersInvalid,
        error.HttpChunkInvalid,
        error.HttpRedirectLocationMissing,
        error.HttpRedirectLocationInvalid,
        error.RedirectRequiresResend,
        => .HTTP_protocol_error,
        error.HttpHeadersOversize,
        error.HttpRedirectLocationOversize,
        => .HTTP_response_header_section_size,
        error.StreamTooLong => .HTTP_response_body_size,
        error.HttpContentEncodingUnsupported,
        error.UnsupportedCompressionMethod,
        => .HTTP_response_content_coding,
        error.TooManyHttpRedirects => .loop_detected,

        // Truly-unknown failures — intentional fallthrough. Every
        // classified path has its own arm above. Members reaching this
        // include `error.OutOfMemory`, `error.SystemResources`,
        // `error.ProcessFdQuotaExceeded`, `error.SystemFdQuotaExceeded`,
        // `error.Canceled`, `error.Unexpected`, and anything Zig adds to
        // `FetchError` after this audit.
        else => .internal_error,
    };
}

/// Successful low-level outbound HTTP fetch result. All three fields are
/// owned host-allocated slices: the caller takes ownership and is
/// responsible for freeing them (`freeOwnedHttpHeaders` for `headers`,
/// `allocator.free` for `body`). (#583 A4)
const HttpLowLevelFetchResult = struct {
    status: u16,
    headers: []HttpFieldEntry,
    body: []u8,
};

/// Drive a single outbound HTTP request through the lower-level
/// `std.http.Client.request` / `Request.receiveHead` /
/// `Response.readerDecompressing` API and capture the full
/// `(status, headers, body)` triple — the equivalent of
/// `std.http.Client.fetch` but without the `FetchResult.status`-only
/// projection that discards the response header list.
///
/// Both the worker thread (`httpFetchWorker`) and the synchronous P3
/// `client.send` path call this helper so the two outbound surfaces
/// produce byte-identical lifted `incoming-response` resources. Errors
/// flow back through `mapHttpFetchError` for `error-code` mapping
/// (#583 A3 — the error set is the same union the old `fetch` path
/// returned, transitively).
///
/// On success the caller owns the returned `headers` (free with
/// `freeOwnedHttpHeaders`) and `body` (`allocator.free`). Headers
/// listed in `isTransportManagedHeader` (Content-Length,
/// Transfer-Encoding, Connection, Keep-Alive, Trailer, TE, Upgrade,
/// Host) are stripped so the lifted `incoming-response` exposes only
/// the application-level headers per the wasi:http WIT spec (#583 A4).
fn httpClientLowLevelFetch(
    allocator: Allocator,
    io: std.Io,
    url: []const u8,
    method: std.http.Method,
    extra_headers: []const std.http.Header,
    payload: ?[]const u8,
) anyerror!HttpLowLevelFetchResult {
    var client: std.http.Client = .{
        .allocator = allocator,
        .io = io,
    };
    defer client.deinit();

    const uri = try std.Uri.parse(url);

    var req = try client.request(method, uri, .{
        .extra_headers = extra_headers,
        .keep_alive = false,
        // Mirror `std.http.Client.fetch`: when there is no payload the
        // request is repeatable so we follow up to 3 redirects; with a
        // payload we surface the redirect to the caller as
        // `error.RedirectRequiresResend` so they can act on it.
        .redirect_behavior = if (payload == null)
            @as(std.http.Client.Request.RedirectBehavior, @enumFromInt(3))
        else
            .unhandled,
    });
    defer req.deinit();

    if (payload) |p| {
        req.transfer_encoding = .{ .content_length = p.len };
        var body_writer = try req.sendBodyUnflushed(&.{});
        try body_writer.writer.writeAll(p);
        try body_writer.end();
        try req.connection.?.flush();
    } else {
        try req.sendBodiless();
    }

    // RFC 9110 recommends ≥ 8000 bytes for the redirect / merged-URI
    // buffer; the spec ceiling on a header section is `max_http_header_bytes`.
    var redirect_buffer: [8 * 1024]u8 = undefined;
    var response = try req.receiveHead(&redirect_buffer);

    // Snapshot headers BEFORE invoking `response.reader(...)` — that
    // call invalidates `response.head.bytes`, which the iterator
    // points into.
    var hdr_list: std.ArrayListUnmanaged(HttpFieldEntry) = .empty;
    errdefer {
        for (hdr_list.items) |e| {
            allocator.free(e.name);
            allocator.free(e.value);
        }
        hdr_list.deinit(allocator);
    }
    {
        var hit = response.head.iterateHeaders();
        while (hit.next()) |h| {
            // Trailers are not surfaced through `incoming-response.headers`
            // per the WIT spec — they have their own `future-trailers`
            // resource. Stop at the trailer boundary.
            if (hit.is_trailer) break;
            if (isTransportManagedHeader(h.name)) continue;
            const name_copy = try allocator.dupe(u8, h.name);
            errdefer allocator.free(name_copy);
            const value_copy = try allocator.dupe(u8, h.value);
            errdefer allocator.free(value_copy);
            try hdr_list.append(allocator, .{ .name = name_copy, .value = value_copy });
        }
    }

    const status_code: u16 = @intFromEnum(response.head.status);

    // Drain the body. HEAD / 1xx / 204 / 304 responses have no body
    // per RFC 9110; `Request.receiveHead` leaves the reader in `.ready`
    // for those and `response.reader(...)` short-circuits to `.ending`.
    var aw: std.Io.Writer.Allocating = .init(allocator);
    errdefer aw.deinit();

    const decompress_buffer: []u8 = switch (response.head.content_encoding) {
        .identity => &.{},
        .zstd => try allocator.alloc(u8, std.compress.zstd.default_window_len),
        .deflate, .gzip => try allocator.alloc(u8, std.compress.flate.max_window_len),
        .compress => return error.UnsupportedCompressionMethod,
    };
    defer if (decompress_buffer.len != 0) allocator.free(decompress_buffer);

    var transfer_buffer: [64]u8 = undefined;
    var decompress: std.http.Decompress = undefined;
    const body_reader = response.readerDecompressing(&transfer_buffer, &decompress, decompress_buffer);

    _ = body_reader.streamRemaining(&aw.writer) catch |err| switch (err) {
        error.ReadFailed => return response.bodyErr().?,
        else => |e| return e,
    };

    var body_al = aw.toArrayList();
    const body = try body_al.toOwnedSlice(allocator);
    errdefer allocator.free(body);

    return .{
        .status = status_code,
        .headers = try hdr_list.toOwnedSlice(allocator),
        .body = body,
    };
}

const max_http_header_bytes: usize = 64 * 1024;
const max_http_body_bytes: usize = 16 * 1024 * 1024;
const max_http_target_bytes: usize = 8192;

/// HTTP/1.1 incoming-handler limits (#583 A5). The header-section limit
/// matches Wasmtime's default `max-header-size = 16384` and is enforced
/// per-request on the live TCP accept path. The body limit aliases
/// `max_http_body_bytes` so a single 0.3 surface knob covers both.
const max_http_p3_header_section_bytes: usize = 16 * 1024;
const max_http_p3_body_bytes: usize = max_http_body_bytes;

/// Keep-alive idle timeout (#583 A5). When a connection is held open
/// between requests, the next request must arrive within this window
/// or the server closes the socket. Set just above the WASI testsuite's
/// own 5s request timeout so a healthy round-trip is never starved by
/// our own idle cap.
const http_p3_keep_alive_idle_seconds: i64 = 5;

/// `wasi:http/types.fields`: a multi-map of header name -> value bytes.
/// Each entry's name and value are owned host-allocated slices, freed
/// when the slot is dropped or the adapter deinits.
pub const HttpFieldEntry = struct {
    name: []u8,
    value: []u8,
};

pub const HttpFields = struct {
    entries: std.ArrayListUnmanaged(HttpFieldEntry) = .empty,
    /// `[static]fields.from-list` returns mutable fields per WIT; the
    /// flag exists so a future implementation of header-immutability
    /// (e.g. fields owned by an incoming-request) has somewhere to
    /// record it. Default-deny stubs ignore it.
    immutable: bool = false,

    pub fn deinit(self: *HttpFields, allocator: Allocator) void {
        for (self.entries.items) |e| {
            allocator.free(e.name);
            allocator.free(e.value);
        }
        self.entries.deinit(allocator);
    }
};

/// Lift a `list<tuple<string, string>>` from guest memory into a fresh
/// allocator-owned slice of `HttpFieldEntry`. Used by
/// `[static]fields.from-list` (#174). Each list element is laid out as
/// four little-endian u32s — name.ptr, name.len, value.ptr, value.len —
/// for a 16-byte stride and 4-byte alignment, matching the canonical
/// ABI lowering used by `getEnvironment`.
///
/// On any out-of-bounds read the partially-allocated entries are freed
/// and `error.OutOfBoundsMemory` is returned, leaving no leaks.
fn liftFieldEntries(
    allocator: Allocator,
    mem: []const u8,
    list_ptr: u32,
    count: u32,
) ![]HttpFieldEntry {
    const stride: u32 = 16;
    const total = std.math.mul(u32, count, stride) catch return error.OutOfBoundsMemory;
    const list_end = std.math.add(u32, list_ptr, total) catch return error.OutOfBoundsMemory;
    if (list_end > mem.len) return error.OutOfBoundsMemory;

    const entries = try allocator.alloc(HttpFieldEntry, count);
    var filled: usize = 0;
    errdefer {
        for (entries[0..filled]) |e| {
            allocator.free(e.name);
            allocator.free(e.value);
        }
        allocator.free(entries);
    }

    while (filled < count) : (filled += 1) {
        const off = list_ptr + @as(u32, @intCast(filled)) * stride;
        const name_ptr = std.mem.readInt(u32, mem[off..][0..4], .little);
        const name_len = std.mem.readInt(u32, mem[off + 4 ..][0..4], .little);
        const val_ptr = std.mem.readInt(u32, mem[off + 8 ..][0..4], .little);
        const val_len = std.mem.readInt(u32, mem[off + 12 ..][0..4], .little);

        const name_end = std.math.add(u32, name_ptr, name_len) catch return error.OutOfBoundsMemory;
        if (name_end > mem.len) return error.OutOfBoundsMemory;
        const val_end = std.math.add(u32, val_ptr, val_len) catch return error.OutOfBoundsMemory;
        if (val_end > mem.len) return error.OutOfBoundsMemory;

        const raw_name = mem[name_ptr..name_end];
        const raw_value = mem[val_ptr..val_end];
        // `fields.from-list` rejects invalid names/values with
        // `header-error.invalid-syntax` (#538). The caller dispatches
        // on the returned `error.InvalidFieldSyntax` to lower a result
        // error variant.
        if (!isValidFieldName(raw_name)) return error.InvalidFieldSyntax;
        if (!isValidFieldValue(raw_value)) return error.InvalidFieldSyntax;

        const name_copy = try lowercaseFieldName(allocator, raw_name);
        errdefer allocator.free(name_copy);
        const val_copy = try allocator.dupe(u8, raw_value);
        entries[filled] = .{ .name = name_copy, .value = val_copy };
    }

    return entries;
}

/// RFC 9110 §5.6.2 `tchar` validation: a non-empty token where every
/// byte is one of `!`, `#`, `$`, `%`, `&`, `'`, `*`, `+`, `-`, `.`,
/// `^`, `_`, `` ` ``, `|`, `~`, ASCII digit, or ASCII letter. The
/// wasi:http@0.3.0 fixtures sweep every codepoint 0..1024 expecting
/// non-token names to return `header-error.invalid-syntax` (#538).
///
/// Comptime-generated 256-byte lookup table (#552). The hot path
/// becomes a single indexed load + compare per byte, which is ~6×
/// faster than the prior `switch` chain — http-fields validates
/// ≥1024 codepoints through this function on every run and the CI
/// 5-second budget needs the speed-up.
pub const tchar_lut: [256]bool = blk: {
    var t: [256]bool = @splat(false);
    for ("!#$%&'*+-.^_`|~") |c| t[c] = true;
    var c: u8 = '0';
    while (c <= '9') : (c += 1) t[c] = true;
    c = 'A';
    while (c <= 'Z') : (c += 1) t[c] = true;
    c = 'a';
    while (c <= 'z') : (c += 1) t[c] = true;
    break :blk t;
};

pub fn isValidFieldName(name: []const u8) bool {
    if (name.len == 0) return false;
    for (name) |c| {
        if (!tchar_lut[c]) return false;
    }
    return true;
}

/// RFC 9110 §5.6.2 `field-value` validation in the wit-bindgen flavour
/// used by the wasi-p3-testsuite: each byte must be SP (0x20), HTAB
/// (0x09), VCHAR (0x21..0x7E), or obs-text (0x80..0xFF). The empty
/// value is valid. The RFC's leading/trailing-whitespace constraint
/// is not enforced — the testsuite explicitly admits
/// `b" \t \t \t \t \t "` as a valid value (#538).
///
/// Comptime LUT (#552): the only invalid bytes are 0x00..0x08, 0x0A..0x1F, 0x7F.
pub const field_value_lut: [256]bool = blk: {
    var t: [256]bool = @splat(false);
    t[0x09] = true;
    t[0x20] = true;
    var c: u8 = 0x21;
    while (c <= 0x7E) : (c += 1) t[c] = true;
    c = 0x80;
    while (true) : (c += 1) {
        t[c] = true;
        if (c == 0xFF) break;
    }
    break :blk t;
};

pub fn isValidFieldValue(value: []const u8) bool {
    for (value) |c| {
        if (!field_value_lut[c]) return false;
    }
    return true;
}

/// RFC 3986 §3.3 `pchar` + `/` + `?` byte set, plus the testsuite
/// carve-out that admits raw UTF-8 (any byte ≥ 0x80) on the wire —
/// see `is_valid_path_char` in `http-request.rs`. Used by
/// `request.set-path-with-query` (#552).
pub const path_char_lut: [256]bool = blk: {
    var t: [256]bool = @splat(false);
    // unreserved: ALPHA / DIGIT / "-" / "." / "_" / "~"
    var c: u8 = '0';
    while (c <= '9') : (c += 1) t[c] = true;
    c = 'A';
    while (c <= 'Z') : (c += 1) t[c] = true;
    c = 'a';
    while (c <= 'z') : (c += 1) t[c] = true;
    for ("-._~") |b| t[b] = true;
    // pct-encoded intro
    t['%'] = true;
    // sub-delims
    for ("!$&'()*+,;=") |b| t[b] = true;
    // pchar extras
    for (":@") |b| t[b] = true;
    // path separator + query intro
    t['/'] = true;
    t['?'] = true;
    // Raw UTF-8 (testsuite carve-out)
    c = 0x80;
    while (true) : (c += 1) {
        t[c] = true;
        if (c == 0xFF) break;
    }
    break :blk t;
};

/// Validate a `path-with-query` byte string against RFC 3986 path-rootless
/// (with raw-UTF-8 carve-out). Empty is accepted by callers and rewritten
/// to `/`; this validator handles non-empty input. Rejects control bytes
/// (0x00..0x1F), DEL (0x7F), and ASCII non-pchar (SP, `"`, `<`, `>`, `[`,
/// `\`, `]`, `^`, `` ` ``, `{`, `|`, `}`, `#`).
pub fn isValidPathWithQuery(path: []const u8) bool {
    for (path) |c| {
        if (!path_char_lut[c]) return false;
    }
    return true;
}

/// `host`-byte set (RFC 3986 §3.2.2 reg-name): unreserved + pct-encoded
/// (`%`) + sub-delims. No `:` (port separator), no `@` (userinfo
/// separator), no `[`/`]` (we don't model IP-literal yet).
pub const host_char_lut: [256]bool = blk: {
    var t: [256]bool = @splat(false);
    var c: u8 = '0';
    while (c <= '9') : (c += 1) t[c] = true;
    c = 'A';
    while (c <= 'Z') : (c += 1) t[c] = true;
    c = 'a';
    while (c <= 'z') : (c += 1) t[c] = true;
    for ("-._~") |b| t[b] = true;
    t['%'] = true;
    for ("!$&'()*+,;=") |b| t[b] = true;
    break :blk t;
};

/// Validate `authority = [userinfo "@"] host [":" port]` per RFC 3986
/// §3.2 (with the simplification that IP-literal `[...]` is not yet
/// supported). Returns `true` for shapes the wasi-p3 `http-request`
/// fixture accepts (#552):
///   - `host`, `host:port`
///   - `userinfo@host`, `userinfo@host:port`
/// The userinfo is allowed to contain `:` (for `user:pass`) and pchar
/// bytes; the host must be a non-empty `reg-name`; `port` must be all
/// ASCII digits (possibly empty per the RFC, but the fixture rejects
/// `example.com:` so we require ≥1 digit). Rejects empty input.
pub fn isValidAuthority(authority: []const u8) bool {
    if (authority.len == 0) return false;
    // Locate the rightmost '@' for userinfo split — userinfo can
    // contain ':' so finding the *first* '@' isn't enough.
    var at_idx: ?usize = null;
    {
        var i: usize = authority.len;
        while (i > 0) {
            i -= 1;
            if (authority[i] == '@') {
                at_idx = i;
                break;
            }
        }
    }
    var hostport_start: usize = 0;
    if (at_idx) |ai| {
        // userinfo = *( unreserved / pct-encoded / sub-delims / ":" )
        const userinfo = authority[0..ai];
        if (userinfo.len == 0) return false; // "@..." invalid
        for (userinfo) |c| {
            if (!host_char_lut[c] and c != ':') return false;
        }
        hostport_start = ai + 1;
    }
    const hostport = authority[hostport_start..];
    if (hostport.len == 0) return false;
    // Split on the *last* ':' (host can't contain ':', but in our
    // simplified non-IP-literal world a colon means port).
    var colon_idx: ?usize = null;
    {
        var i: usize = hostport.len;
        while (i > 0) {
            i -= 1;
            if (hostport[i] == ':') {
                colon_idx = i;
                break;
            }
        }
    }
    const host = if (colon_idx) |ci| hostport[0..ci] else hostport;
    if (host.len == 0) return false;
    for (host) |c| {
        if (!host_char_lut[c]) return false;
    }
    if (colon_idx) |ci| {
        const port = hostport[ci + 1 ..];
        if (port.len == 0) return false; // testsuite rejects `example.com:`
        for (port) |c| {
            if (c < '0' or c > '9') return false; // `localhost:what`
        }
    }
    return true;
}

/// Lower-case ASCII normalisation for HTTP field names. The
/// wasi:http@0.3.0 fixtures expect case-insensitive matching plus
/// stable lower-cased read-back via `copy-all` (#538). Allocator-owned
/// returned slice.
pub fn lowercaseFieldName(allocator: Allocator, name: []const u8) ![]u8 {
    const out = try allocator.alloc(u8, name.len);
    for (name, 0..) |c, i| {
        out[i] = if (c >= 'A' and c <= 'Z') c + 32 else c;
    }
    return out;
}

/// ASCII case-insensitive equality. Used by `set-scheme` to fold
/// `Scheme::Other("HTTP")` back into the canonical `HTTP` variant
/// (#538).
pub fn asciiEqualIgnoreCase(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    for (a, b) |ca, cb| {
        const la = if (ca >= 'A' and ca <= 'Z') ca + 32 else ca;
        const lb = if (cb >= 'A' and cb <= 'Z') cb + 32 else cb;
        if (la != lb) return false;
    }
    return true;
}

/// `wasi:http/types.outgoing-request`. The constructor borrows a
/// `fields` handle for headers; mutation goes through `set-*` methods
/// which the default-deny adapter accepts as ok no-ops (real header
/// validation is deferred). String fields are owned host slices.
pub const OutgoingRequest = struct {
    method_disc: u32 = 0, // .get
    method_other: ?[]u8 = null,
    path_with_query: ?[]u8 = null,
    scheme_disc: ?u32 = null,
    scheme_other: ?[]u8 = null,
    authority: ?[]u8 = null,
    headers_handle: u32,
    body_consumed: bool = false,
    body_handle: ?u32 = null,

    pub fn deinit(self: *OutgoingRequest, allocator: Allocator) void {
        if (self.method_other) |s| allocator.free(s);
        if (self.path_with_query) |s| allocator.free(s);
        if (self.scheme_other) |s| allocator.free(s);
        if (self.authority) |s| allocator.free(s);
    }
};

/// `wasi:http/types.incoming-request`. Server mode constructs these from
/// accepted HTTP/1.1 requests; fields are owned by the adapter and exposed
/// through the usual resource handles.
pub const IncomingRequest = struct {
    method_disc: u32 = 0, // .get
    method_other: ?[]u8 = null,
    path_with_query: ?[]u8 = null,
    scheme_disc: ?u32 = null,
    scheme_other: ?[]u8 = null,
    authority: ?[]u8 = null,
    headers_handle: u32 = 0,
    body_consumed: bool = false,
    /// Request body bytes owned by this request until `consume` transfers
    /// them to an `IncomingBody`.
    body_data: ?[]u8 = null,

    pub fn deinit(self: *IncomingRequest, allocator: Allocator) void {
        if (self.method_other) |s| allocator.free(s);
        if (self.path_with_query) |s| allocator.free(s);
        if (self.scheme_other) |s| allocator.free(s);
        if (self.authority) |s| allocator.free(s);
        if (self.body_data) |d| allocator.free(d);
    }
};

/// `wasi:http/types.incoming-response`. Used by the
/// `future-incoming-response.get` happy path once #149 follow-up wires
/// real outbound HTTP (#176).
pub const IncomingResponse = struct {
    status: u16 = 0,
    headers_handle: u32 = 0,
    body_consumed: bool = false,
    /// Response body bytes owned by the adapter. Transferred to
    /// `IncomingBody` on `consume`, freed on drop if unconsumed.
    body_data: ?[]u8 = null,

    pub fn deinit(self: *IncomingResponse, allocator: Allocator) void {
        if (self.body_data) |d| allocator.free(d);
    }
};

/// `wasi:http/types.outgoing-response`.
pub const OutgoingResponse = struct {
    status: u16 = 200,
    headers_handle: u32,
    body_consumed: bool = false,
    body_handle: ?u32 = null,
};

/// `wasi:http/types.incoming-body`. Holds readable body data
/// transferred from `IncomingResponse` on `consume`.
pub const IncomingBody = struct {
    /// Owned body bytes. Freed on drop.
    data: ?[]u8 = null,
    stream_taken: bool = false,
    /// Heap-allocated input stream created by `stream`. Owned by
    /// `WasiCliAdapter.owned_input_streams`.
    stream: ?*streams.InputStream = null,

    pub fn deinit(self: *IncomingBody, allocator: Allocator) void {
        if (self.data) |d| allocator.free(d);
    }
};

/// `wasi:http/types.outgoing-body`.
pub const OutgoingBody = struct {
    /// Set by `[method]outgoing-body.write` to ensure a second call
    /// returns err per WIT contract.
    stream_taken: bool = false,
    /// Heap-allocated output stream created by `write`. The stream's
    /// buffer holds the body bytes written by the guest. The stream
    /// is owned by `WasiCliAdapter.owned_output_streams` and freed
    /// there; this pointer is only for reading the buffer contents.
    stream: ?*streams.OutputStream = null,
};

/// `wasi:http/types.future-incoming-response` (#149, #583 A2).
///
/// The guest awaits this future via `[method]future-incoming-response.subscribe`
/// (producing a `pollable`) and `[method]future-incoming-response.get`
/// (which consumes the result on the first ready call). The adapter
/// resolves the future asynchronously through `PendingHttpFetch`: the
/// real `std.http.Client.fetch` runs on a worker thread, and the
/// adapter's `drainPendingHttpFetches` driver transitions `state`
/// from `.pending` to `.ready_ok` / `.ready_err` once the worker
/// publishes its outcome. Synchronous denial paths (empty allow-list,
/// malformed request, invalid URL) still settle the future to
/// `.ready_err` immediately — only the actual fetch is deferred.
pub const FutureIncomingResponse = struct {
    pub const State = union(enum) {
        pending,
        ready_ok: u32, // incoming-response handle
        ready_err: u32, // HttpErrorCode discriminant
    };

    state: State,

    /// True on the second `.get()` call — the WIT says a future must
    /// return `err(())` (the outer result-of-result) once it has been
    /// consumed.
    polled: bool = false,
};

/// `wasi:http/types.future-trailers`. Default-deny resolves to
/// `some(ok(ok(none)))` (no trailers).
pub const FutureTrailers = struct {
    polled: bool = false,
};

pub const UdpStreamPollRef = struct {
    handle: u32,
    parent_handle: u32,
    generation: u32,
};

/// Adapter-owned `wasi:io/poll.pollable` resource metadata.
pub const Pollable = union(enum) {
    immediate,
    monotonic_timer: u64,
    input_stream: u32,
    output_stream: u32,
    tcp_socket: u32,
    udp_socket: u32,
    udp_incoming_stream: UdpStreamPollRef,
    udp_outgoing_stream: UdpStreamPollRef,
    resolve_address_stream: u32,
    http_future_response: u32,
    http_future_trailers: u32,
    /// `wasi:clocks/monotonic-clock@0.2.x` polyfill on a P3 backend (#483):
    /// the pollable wraps a P3 timer-future handle. Goes ready when the
    /// associated `TimerFuture` fires (deadline ≤ `monotonicNs()`).
    /// Stored value is the future handle key into `ComponentInstance.futures`,
    /// which is also the lookup key in `WasiCliAdapter.timer_future_ready`.
    future_timer: u32,
};

/// One pending P3 `wait-for` / `wait-until` timer future (#483).
///
/// The future handle lives in `ComponentInstance.futures`; the host
/// completes it when `deadline_ns <= monotonicNs()` by setting the
/// future state to `.ready` and waking any read-waitable.
pub const TimerFuture = struct {
    handle: u32,
    deadline_ns: u64,
};

/// `wasi:http/types.request-options`. Pure record of optional
/// timeouts; the constructor returns a fresh slot, getters return
/// option-none, setters store values.
pub const RequestOptions = struct {
    connect_timeout_ns: ?u64 = null,
    first_byte_timeout_ns: ?u64 = null,
    between_bytes_timeout_ns: ?u64 = null,
};

/// `wasi:http/types.response-outparam`. Server-side handoff slot. The
/// incoming server reads this after calling the guest's exported
/// `incoming-handler.handle` to decide which HTTP response to serialize.
pub const ResponseOutparam = struct {
    pub const State = union(enum) {
        unset,
        response: u32,
        err: u32,
    };

    state: State = .unset,
};

/// `wasi:http/types@0.3.0` unified request resource (#487).
/// Merges 0.2's `incoming-request` + `outgoing-request` into a single
/// resource. Body data lives in `ComponentInstance.streams`; trailers
/// and transmission-result live in `ComponentInstance.futures`. Field
/// strings are owned host slices.
pub const HttpRequestP3 = struct {
    method_disc: u32 = 0, // .get
    method_other: ?[]u8 = null,
    path_with_query: ?[]u8 = null,
    scheme_disc: ?u32 = null,
    scheme_other: ?[]u8 = null,
    authority: ?[]u8 = null,
    headers_handle: u32 = 0,
    options_handle: ?u32 = null,
    /// Handle into `ComponentInstance.streams` (AsyncStream) for the
    /// body stream<u8>. `null` means no body / zero-length.
    body_stream_handle: ?u32 = null,
    /// Handle into `ComponentInstance.futures` for
    /// `future<result<option<trailers>, error-code>>` (trailers channel).
    trailers_future_handle: u32 = 0,
    /// Handle into `ComponentInstance.futures` for
    /// `future<result<_, error-code>>` (transmission result).
    transmission_future_handle: u32 = 0,

    pub fn deinit(self: *HttpRequestP3, allocator: Allocator) void {
        if (self.method_other) |s| allocator.free(s);
        if (self.path_with_query) |s| allocator.free(s);
        if (self.scheme_other) |s| allocator.free(s);
        if (self.authority) |s| allocator.free(s);
    }
};

/// `wasi:http/types@0.3.0` unified response resource (#487).
/// Merges 0.2's `incoming-response` + `outgoing-response`.
pub const HttpResponseP3 = struct {
    status: u16 = 200,
    headers_handle: u32 = 0,
    /// Handle into `ComponentInstance.streams` for body stream<u8>.
    body_stream_handle: ?u32 = null,
    /// Handle into `ComponentInstance.futures` for trailers future.
    trailers_future_handle: u32 = 0,
    /// Handle into `ComponentInstance.futures` for transmission future.
    transmission_future_handle: u32 = 0,

    pub fn deinit(_: *HttpResponseP3, _: Allocator) void {}
};

/// `(string, string)` pair forwarded to `wasi:cli/environment.get-environment`.
/// The slices are borrowed by the adapter — the caller is responsible for
/// keeping them alive across the run.
pub const EnvVar = struct {
    name: []const u8,
    value: []const u8,
};

pub const WasiCliAdapter = struct {
    allocator: Allocator,
    stdout: streams.OutputStream,
    stderr: streams.OutputStream,
    /// Captured stdin buffer. Defaults to empty; callers populate via
    /// `setStdinBytes` before running the component. The slice is
    /// borrowed — keep it alive for as long as the component runs.
    stdin: streams.InputStream = .{ .source = .closed },

    /// `wasi:cli/exit.exit` (or `exit-with-code`). The host fn
    /// also returns `error.Trap`; `runLoadedComponent` checks this
    /// field to translate the trap into a normal `RunOutcome`.
    exit_code: ?u32 = null,

    /// argv passed to the component via `wasi:cli/environment.get-arguments`.
    /// Borrowed — caller keeps slice alive for the run. Default empty.
    argv: []const []const u8 = &.{},
    /// envvars passed to the component via `wasi:cli/environment.get-environment`.
    /// Borrowed — caller keeps slices alive for the run. Default empty.
    env: []const EnvVar = &.{},

    /// `HostInstance` registered for the simple test interface name
    /// (e.g. `"wasi:hello/world"`). Stored inline so the adapter owns its
    /// lifetime; callers pass a stable pointer to `linkImports`.
    write_iface: HostInstance = .{},
    cli_stdout_iface: HostInstance = .{},
    cli_stderr_iface: HostInstance = .{},
    cli_stdin_iface: HostInstance = .{},
    cli_exit_iface: HostInstance = .{},
    cli_environment_iface: HostInstance = .{},
    cli_terminal_stdin_iface: HostInstance = .{},
    cli_terminal_stdout_iface: HostInstance = .{},
    cli_terminal_stderr_iface: HostInstance = .{},
    cli_terminal_input_iface: HostInstance = .{},
    cli_terminal_output_iface: HostInstance = .{},
    io_streams_iface: HostInstance = .{},
    io_poll_iface: HostInstance = .{},
    io_error_iface: HostInstance = .{},
    clocks_wall_iface: HostInstance = .{},
    clocks_monotonic_iface: HostInstance = .{},
    random_iface: HostInstance = .{},
    random_insecure_iface: HostInstance = .{},
    random_insecure_seed_iface: HostInstance = .{},
    fs_types_iface: HostInstance = .{},
    fs_preopens_iface: HostInstance = .{},
    sockets_network_iface: HostInstance = .{},
    sockets_instance_network_iface: HostInstance = .{},
    sockets_tcp_iface: HostInstance = .{},
    sockets_tcp_create_iface: HostInstance = .{},
    sockets_udp_iface: HostInstance = .{},
    sockets_udp_create_iface: HostInstance = .{},
    sockets_ip_name_lookup_iface: HostInstance = .{},
    http_types_iface: HostInstance = .{},
    http_outgoing_handler_iface: HostInstance = .{},
    http_incoming_handler_iface: HostInstance = .{},

    // ── WASIp3 stub host instances (#481 wave A) ─────────────────────
    // These fields exist so wave B/C PRs (#482-#487) only need to add
    // `populateWasi*P3` implementations, not new struct fields. The
    // version-multiplex in `populateWasiProviders` routes versioned
    // `@0.3.x` imports here. Declared in alphabetical order by
    // interface family (cli, clocks, fs, http, io, random, sockets)
    // and mirrors the surface of the corresponding `*_iface` field
    // above. Wave A only wires `io_streams_p3_iface` /
    // `io_error_p3_iface`; the rest are stub-only placeholders.
    cli_stdout_p3_iface: HostInstance = .{},
    cli_stderr_p3_iface: HostInstance = .{},
    cli_stdin_p3_iface: HostInstance = .{},
    cli_exit_p3_iface: HostInstance = .{},
    cli_environment_p3_iface: HostInstance = .{},
    cli_run_p3_iface: HostInstance = .{},
    // #482: cli@0.3.0 adds a `wasi:cli/types` interface (enum
    // `error-code { io, illegal-byte-sequence, pipe }`) — type-only,
    // no function bindings. The instance entry exists only for guest
    // binding satisfaction.
    cli_types_p3_iface: HostInstance = .{},
    // #482: P3 terminal interfaces. Members are identical to 0.2
    // (get-terminal-* → none, [resource-drop]terminal-{input,output}
    // → no-op) but kept as separate HostInstance values so version
    // routing in `populateWasiProviders` is symmetric.
    cli_terminal_stdin_p3_iface: HostInstance = .{},
    cli_terminal_stdout_p3_iface: HostInstance = .{},
    cli_terminal_stderr_p3_iface: HostInstance = .{},
    cli_terminal_input_p3_iface: HostInstance = .{},
    cli_terminal_output_p3_iface: HostInstance = .{},
    clocks_wall_p3_iface: HostInstance = .{},
    clocks_monotonic_p3_iface: HostInstance = .{},
    // #534: wasi:clocks@0.3.0 hoists `duration` (and, in newer revisions,
    // `instant`) into a top-level `wasi:clocks/types` interface that the
    // `monotonic-clock` / `system-clock` ifaces alias from. The instance
    // carries no functions — just type definitions — so the provider is
    // an empty `HostInstance` whose sole purpose is to satisfy guest
    // import resolution. Without it, components emitted by recent rustc
    // toolchains (e.g. the `wall-clock` / `monotonic-clock` /
    // `multi-clock-wait` wasi-p3 fixtures) fail to link even when every
    // other 0.2 / 0.3 clock import has a provider.
    clocks_types_p3_iface: HostInstance = .{},
    fs_types_p3_iface: HostInstance = .{},
    fs_preopens_p3_iface: HostInstance = .{},
    http_types_p3_iface: HostInstance = .{},
    // wasi:http@0.3.0 collapses outgoing-handler/incoming-handler into
    // `wasi:http/handler` (guest-export, host-import stub) and
    // `wasi:http/client` (host-provided send) (#487).
    http_handler_p3_iface: HostInstance = .{},
    http_client_p3_iface: HostInstance = .{},
    io_error_p3_iface: HostInstance = .{},
    io_streams_p3_iface: HostInstance = .{},
    random_p3_iface: HostInstance = .{},
    random_insecure_p3_iface: HostInstance = .{},
    random_insecure_seed_p3_iface: HostInstance = .{},
    sockets_network_p3_iface: HostInstance = .{},
    sockets_instance_network_p3_iface: HostInstance = .{},
    sockets_tcp_p3_iface: HostInstance = .{},
    sockets_tcp_create_p3_iface: HostInstance = .{},
    sockets_udp_p3_iface: HostInstance = .{},
    sockets_udp_create_p3_iface: HostInstance = .{},
    sockets_ip_name_lookup_p3_iface: HostInstance = .{},
    /// `wasi:sockets/types@0.3.0-*` (#486). The 0.3 WIT collapses the six
    /// 0.2 sockets interfaces (network, instance-network, tcp,
    /// tcp-create-socket, udp, udp-create-socket) into a single `types`
    /// interface that holds every tcp-socket and udp-socket method plus
    /// the static constructors. The 0.2 `network` / `instance-network`
    /// sub-interfaces have no 0.3 equivalent — bind/connect take no
    /// network arg in 0.3.
    sockets_types_p3_iface: HostInstance = .{},

    stream_table: std.ArrayListUnmanaged(?*streams.OutputStream) = .empty,
    input_stream_table: std.ArrayListUnmanaged(?*streams.InputStream) = .empty,
    /// Heap-allocated input streams created by `descriptor.read-via-stream`.
    /// Owned by the adapter; freed in `deinit`. The indices in this list
    /// are unrelated to guest handles — guest handles live in
    /// `input_stream_table`. Same arrangement for `owned_output_streams`.
    owned_input_streams: std.ArrayListUnmanaged(*streams.InputStream) = .empty,
    owned_output_streams: std.ArrayListUnmanaged(*streams.OutputStream) = .empty,

    /// `wasi:filesystem` descriptor table. Slot index = guest handle.
    /// Slots are nulled on `[resource-drop]descriptor` (except `.preopen`
    /// slots, which are persistent — see `dropFsDescriptor`).
    fs_descriptor_table: std.ArrayListUnmanaged(?FsDescriptor) = .empty,
    /// Names of the preopen slots, in `get-directories` order. Each entry's
    /// `dir_handle` indexes into `fs_descriptor_table`. The string is owned
    /// by the adapter and freed in `deinit`.
    fs_preopens: std.ArrayListUnmanaged(FsPreopen) = .empty,
    /// `wasi:filesystem/types.directory-entry-stream` resource table (#476).
    /// Slot index = guest handle. Each live slot owns a heap-allocated
    /// `std.Io.Dir.Iterator`. Slots are nulled on
    /// `[resource-drop]directory-entry-stream`; `deinit` mops up any
    /// slots the guest leaked.
    dir_entry_stream_table: std.ArrayListUnmanaged(?DirEntryStream) = .empty,

    /// `wasi:sockets/network` resource table. Slot index = guest handle.
    /// Slots are nulled on `[resource-drop]network`.
    network_table: std.ArrayListUnmanaged(?Network) = .empty,
    /// Adapter-level template for the per-`network` CIDR allow-list (#180).
    /// Each 0.2 `instance-network` snapshots this slice into the new
    /// `Network.allow_list`; the 0.3 sockets path consults this template
    /// directly via `templateAllows` (#583 A1). Owned by the adapter and
    /// replaced atomically by `setSocketsAllowList`.
    ///
    /// Empty-template semantics differ per consumer:
    ///   * 0.2 `Network.allows()` → deny-all (legacy capability gate).
    ///   * 0.3 raw-socket `templateAllows` (tcp-connect, udp-connect,
    ///     udp-send) → allow-all. Embedders that don't seed the
    ///     allow-list get unrestricted raw sockets; the kernel still
    ///     enforces routability / bindability.
    ///   * 0.3 DNS (`resolveAddressesP3`) → `name-unresolvable`.
    ///   * Outbound HTTP (0.2 + 0.3) → `HTTP_request_denied`.
    sockets_allow_list_template: []IpCidr = &.{},
    /// `wasi:sockets/{tcp,udp}` socket resource table. Slot index = guest
    /// handle (shared across both kinds — `Socket.kind` discriminates).
    /// Slots are nulled on `[resource-drop]tcp-socket` /
    /// `[resource-drop]udp-socket`.
    socket_table: std.ArrayListUnmanaged(?Socket) = .empty,
    /// `wasi:sockets/udp.incoming-datagram-stream` sub-resource table.
    /// Each slot owns a heap-allocated rep; nulled on resource-drop.
    udp_incoming_streams: std.ArrayListUnmanaged(?*UdpIncomingStream) = .empty,
    /// `wasi:sockets/udp.outgoing-datagram-stream` sub-resource table.
    udp_outgoing_streams: std.ArrayListUnmanaged(?*UdpOutgoingStream) = .empty,
    /// `wasi:sockets/ip-name-lookup.resolve-address-stream` table. Slots
    /// own the heap-allocated stream struct; nulled on resource-drop.
    resolve_streams: std.ArrayListUnmanaged(?*ResolveAddressStream) = .empty,
    /// Lifetimes for `host_driver` contexts attached to socket-backed
    /// `AsyncStream` slots (#535). The adapter owns these so the
    /// `*AsyncStream`'s `host_driver.context` pointer stays valid until
    /// the adapter tears down — the executor frees the `AsyncStream`
    /// itself but not the host context. Each entry is a small struct
    /// (fd + adapter pointer + family).
    sockets_p3_stream_ctxs: std.ArrayListUnmanaged(*SocketsP3StreamCtx) = .empty,
    /// Lifetimes for `host_driver` contexts attached to `AsyncStream`
    /// slots produced by `descriptor.write-via-stream` /
    /// `descriptor.append-via-stream` (#571). The adapter owns these
    /// so the `*AsyncStream`'s `host_driver.context` pointer stays
    /// valid for the lifetime of the stream — the executor frees the
    /// `AsyncStream` itself but not the host context.
    fs_write_stream_ctxs: std.ArrayListUnmanaged(*FsWriteStreamCtx) = .empty,

    /// Pending `udp-socket.receive` async-futures that found no datagram
    /// waiting on their first non-blocking `recvfrom(2)`. Drained by
    /// `completeReadyPendingUdpReceives` on every `driveAsyncEvents`
    /// tick so the guest's awaited `.receive()` resolves as soon as a
    /// datagram lands in the kernel queue (#576).
    pending_udp_receives: std.ArrayListUnmanaged(PendingUdpReceive) = .empty,

    /// Pending outbound `wasi:http/outgoing-handler.handle` fetches
    /// (#583 A2). Each entry owns a worker thread driving the
    /// blocking `std.http.Client.fetch` plus a shared heap struct
    /// the worker publishes its outcome through. Drained by
    /// `drainPendingHttpFetches` on every `driveAsyncEvents` tick
    /// and at the top of `anyPollableReady` so the guest's
    /// `pollable.poll` / `pollable.block` over a
    /// `future-incoming-response` resolves once the fetch finishes.
    pending_http_fetches: std.ArrayListUnmanaged(PendingHttpFetch) = .empty,

    /// `wasi:http/types` resource tables (#149). Each slot owns a
    /// heap-allocated rep struct; resource-drop nulls the slot and
    /// frees the underlying allocation. `deinit` mops up any slots
    /// the guest leaked.
    http_fields_table: std.ArrayListUnmanaged(?*HttpFields) = .empty,
    http_outgoing_requests: std.ArrayListUnmanaged(?*OutgoingRequest) = .empty,
    http_incoming_requests: std.ArrayListUnmanaged(?*IncomingRequest) = .empty,
    http_outgoing_responses: std.ArrayListUnmanaged(?*OutgoingResponse) = .empty,
    http_incoming_responses: std.ArrayListUnmanaged(?*IncomingResponse) = .empty,
    http_request_options: std.ArrayListUnmanaged(?*RequestOptions) = .empty,
    http_response_outparams: std.ArrayListUnmanaged(?*ResponseOutparam) = .empty,
    http_incoming_bodies: std.ArrayListUnmanaged(?*IncomingBody) = .empty,
    http_outgoing_bodies: std.ArrayListUnmanaged(?*OutgoingBody) = .empty,
    http_future_responses: std.ArrayListUnmanaged(?*FutureIncomingResponse) = .empty,
    http_future_trailers: std.ArrayListUnmanaged(?*FutureTrailers) = .empty,
    /// `wasi:http/types@0.3.0` unified request table (#487).
    http_requests_p3: std.ArrayListUnmanaged(?*HttpRequestP3) = .empty,
    /// `wasi:http/types@0.3.0` unified response table (#487).
    http_responses_p3: std.ArrayListUnmanaged(?*HttpResponseP3) = .empty,
    /// `wasi:http/types@0.3.0` request-options table (#487). Separate
    /// from the 0.2 `http_request_options` to avoid index aliasing
    /// across surfaces; the rep struct is the same.
    http_request_options_p3: std.ArrayListUnmanaged(?*RequestOptions) = .empty,
    /// `wasi:io/poll.pollable` table. Pollables borrow their source
    /// resources and become ready if that source is dropped/closed, so the
    /// guest can observe the underlying closed/error condition without UAF.
    pollable_table: std.ArrayListUnmanaged(?Pollable) = .empty,

    /// Optional deterministic-clock injection. When set, `wasi:clocks/wall-clock.now`
    /// returns this datetime instead of reading the host wall clock — used by
    /// tests that assert on the lifted `record { seconds, nanoseconds }`.
    wall_clock_override: ?Datetime = null,
    /// Optional deterministic-monotonic-clock injection. When set,
    /// `wasi:clocks/monotonic-clock.now` and `subscribe-*` use this value
    /// (`subscribe-instant` clamps the deadline; `subscribe-duration` adds
    /// to it). Defaults to live `std.time.Instant`.
    monotonic_clock_override: ?u64 = null,

    /// Pending P3 async-timer futures (#483). Populated by
    /// `wasi:clocks/monotonic-clock.wait-for` / `wait-until` and the
    /// 0.2 → 0.3 `subscribe-duration` polyfill. Drained by
    /// `completeDueTimerFutures` whenever a polling/blocking site is reached.
    timer_futures: std.ArrayListUnmanaged(TimerFuture) = .empty,

    /// Ready-flag map for `.future_timer` pollables (#483 polyfill). Keyed by
    /// the P3 timer-future handle (== `Pollable.future_timer` payload). Set
    /// to `true` by `completeDueTimerFutures` when the timer fires; checked
    /// by `pollableIsReady`. Survives removal of the entry from
    /// `timer_futures` because the `ComponentInstance.futures` handle is
    /// stable until the guest calls `future.drop`.
    timer_future_ready: std.AutoHashMapUnmanaged(u32, bool) = .empty,

    /// State for the insecure PRNG. When `null`, init-time auto-seed runs
    /// on first use. Tests can overwrite this before invoking the component
    /// to get deterministic output.
    insecure_prng: ?std.Random.DefaultPrng = null,

    /// Memoised `wasi:random/insecure-seed.{get-,}insecure-seed` value.
    /// Per WASI's spec the function is meant to be called once and any
    /// subsequent calls must return the same `tuple<u64, u64>`. The
    /// wasi-p3-testsuite `random` fixture exercises this invariant by
    /// asserting two successive calls yield equal tuples. We compute
    /// the pair on first call and cache it for the lifetime of the
    /// adapter. (#520)
    insecure_seed_cache: ?[2]u64 = null,

    /// Initialize with a buffer-backed stdout sink. Use `getStdoutBytes`
    /// after the component runs to inspect captured output. This is the
    /// test-/embedding-friendly constructor — every existing test in
    /// this file uses it. For the `wamr run` CLI path that streams
    /// live to the host process's stdio, use `initWithHostStdio`.
    pub fn init(allocator: Allocator) WasiCliAdapter {
        return .{
            .allocator = allocator,
            .stdout = streams.OutputStream.toBuffer(),
            .stderr = streams.OutputStream.toBuffer(),
        };
    }

    /// Initialize with stdout/stderr/stdin wired directly to the host
    /// process's standard file descriptors. Used by `wamr run` so the
    /// component's output streams incrementally to the user's terminal
    /// instead of buffering for the entire run. Stdin reads block on
    /// the host's stdin fd (#474).
    ///
    /// `getStdoutBytes` / `getStderrBytes` / `setStdinBytes` are
    /// **not valid** with this constructor — they expect buffer-backed
    /// sinks. Use the regular `init` for embedding / tests that need
    /// to inspect captured output.
    ///
    /// Cross-platform: pulls handles from `std.Io.File.{stdin,stdout,
    /// stderr}` rather than `std.posix.STDIN_FILENO` etc. because on
    /// Windows `posix.fd_t` is `*anyopaque` (HANDLE), so the comptime
    /// integers `0/1/2` don't coerce.
    pub fn initWithHostStdio(allocator: Allocator) WasiCliAdapter {
        return initWithHostStdioFds(
            allocator,
            std.Io.File.stdin().handle,
            std.Io.File.stdout().handle,
            std.Io.File.stderr().handle,
        );
    }

    /// Variant of `initWithHostStdio` that takes explicit fds — used
    /// by tests that redirect stdin/stdout/stderr through pipes to
    /// observe the live-streaming path without touching the test
    /// process's own stdio (#474).
    pub fn initWithHostStdioFds(
        allocator: Allocator,
        stdin_fd: std.posix.fd_t,
        stdout_fd: std.posix.fd_t,
        stderr_fd: std.posix.fd_t,
    ) WasiCliAdapter {
        return .{
            .allocator = allocator,
            .stdout = streams.OutputStream.toFd(stdout_fd),
            .stderr = streams.OutputStream.toFd(stderr_fd),
            .stdin = streams.InputStream.fromFd(stdin_fd),
        };
    }

    pub fn deinit(self: *WasiCliAdapter) void {
        self.stdout.deinit(self.allocator);
        self.stderr.deinit(self.allocator);
        self.write_iface.deinit(self.allocator);
        self.cli_stdout_iface.deinit(self.allocator);
        self.cli_stderr_iface.deinit(self.allocator);
        self.cli_stdin_iface.deinit(self.allocator);
        self.cli_exit_iface.deinit(self.allocator);
        self.cli_environment_iface.deinit(self.allocator);
        self.cli_terminal_stdin_iface.deinit(self.allocator);
        self.cli_terminal_stdout_iface.deinit(self.allocator);
        self.cli_terminal_stderr_iface.deinit(self.allocator);
        self.cli_terminal_input_iface.deinit(self.allocator);
        self.cli_terminal_output_iface.deinit(self.allocator);
        self.io_streams_iface.deinit(self.allocator);
        self.io_poll_iface.deinit(self.allocator);
        self.io_error_iface.deinit(self.allocator);
        self.clocks_wall_iface.deinit(self.allocator);
        self.clocks_monotonic_iface.deinit(self.allocator);
        self.random_iface.deinit(self.allocator);
        self.random_insecure_iface.deinit(self.allocator);
        self.random_insecure_seed_iface.deinit(self.allocator);
        self.fs_types_iface.deinit(self.allocator);
        self.fs_preopens_iface.deinit(self.allocator);
        self.sockets_network_iface.deinit(self.allocator);
        self.sockets_instance_network_iface.deinit(self.allocator);
        self.sockets_tcp_iface.deinit(self.allocator);
        self.sockets_tcp_create_iface.deinit(self.allocator);
        self.sockets_udp_iface.deinit(self.allocator);
        self.sockets_udp_create_iface.deinit(self.allocator);
        self.sockets_ip_name_lookup_iface.deinit(self.allocator);
        self.http_types_iface.deinit(self.allocator);
        self.http_outgoing_handler_iface.deinit(self.allocator);
        self.http_incoming_handler_iface.deinit(self.allocator);

        // P3 stub interfaces (#481).
        self.cli_stdout_p3_iface.deinit(self.allocator);
        self.cli_stderr_p3_iface.deinit(self.allocator);
        self.cli_stdin_p3_iface.deinit(self.allocator);
        self.cli_exit_p3_iface.deinit(self.allocator);
        self.cli_environment_p3_iface.deinit(self.allocator);
        self.cli_run_p3_iface.deinit(self.allocator);
        self.cli_types_p3_iface.deinit(self.allocator);
        self.cli_terminal_stdin_p3_iface.deinit(self.allocator);
        self.cli_terminal_stdout_p3_iface.deinit(self.allocator);
        self.cli_terminal_stderr_p3_iface.deinit(self.allocator);
        self.cli_terminal_input_p3_iface.deinit(self.allocator);
        self.cli_terminal_output_p3_iface.deinit(self.allocator);
        self.clocks_wall_p3_iface.deinit(self.allocator);
        self.clocks_monotonic_p3_iface.deinit(self.allocator);
        self.clocks_types_p3_iface.deinit(self.allocator);
        self.fs_types_p3_iface.deinit(self.allocator);
        self.fs_preopens_p3_iface.deinit(self.allocator);
        self.http_types_p3_iface.deinit(self.allocator);
        self.http_handler_p3_iface.deinit(self.allocator);
        self.http_client_p3_iface.deinit(self.allocator);
        self.io_error_p3_iface.deinit(self.allocator);
        self.io_streams_p3_iface.deinit(self.allocator);
        self.random_p3_iface.deinit(self.allocator);
        self.random_insecure_p3_iface.deinit(self.allocator);
        self.random_insecure_seed_p3_iface.deinit(self.allocator);
        self.sockets_network_p3_iface.deinit(self.allocator);
        self.sockets_instance_network_p3_iface.deinit(self.allocator);
        self.sockets_tcp_p3_iface.deinit(self.allocator);
        self.sockets_tcp_create_p3_iface.deinit(self.allocator);
        self.sockets_udp_p3_iface.deinit(self.allocator);
        self.sockets_udp_create_p3_iface.deinit(self.allocator);
        self.sockets_ip_name_lookup_p3_iface.deinit(self.allocator);
        self.sockets_types_p3_iface.deinit(self.allocator);
        self.timer_futures.deinit(self.allocator);
        self.timer_future_ready.deinit(self.allocator);
        self.pending_udp_receives.deinit(self.allocator);
        // Drain any outbound HTTP worker threads still in flight
        // (#583 A2). Each entry is joined so we can safely free the
        // shared heap struct — a still-running `std.http.Client.fetch`
        // cannot UAF the slot from under us. Entries whose guest had
        // dropped the future-incoming-response (slot kept reserved
        // by `httpFutureDrop` to defeat slot-reuse races) get their
        // slot nulled here as well so the post-deinit
        // `http_future_responses` teardown doesn't double-free.
        for (self.pending_http_fetches.items) |entry| {
            entry.shared.cancelled.store(true, .release);
            entry.thread.join();
            switch (entry.shared.outcome) {
                .success => |s| self.allocator.free(s.body),
                .failure => {},
            }
            self.allocator.destroy(entry.shared);
            if (entry.guest_dropped) {
                const fh = entry.future_handle;
                if (fh < self.http_future_responses.items.len) {
                    if (self.http_future_responses.items[fh]) |f| {
                        self.allocator.destroy(f);
                        self.http_future_responses.items[fh] = null;
                    }
                }
            }
        }
        self.pending_http_fetches.deinit(self.allocator);
        self.stream_table.deinit(self.allocator);
        self.input_stream_table.deinit(self.allocator);

        // Own-streams created by `read-via-stream`/`write-via-stream` —
        // close any underlying borrowed file refs and free the heap stream
        // structs. The streams' `host_file` variant only borrows the
        // descriptor's File handle, so we don't close it here (the
        // descriptor's slot owns it).
        for (self.owned_input_streams.items) |s| {
            s.* = undefined;
            self.allocator.destroy(s);
        }
        self.owned_input_streams.deinit(self.allocator);
        for (self.owned_output_streams.items) |s| {
            s.deinit(self.allocator);
            self.allocator.destroy(s);
        }
        self.owned_output_streams.deinit(self.allocator);

        // Close every owning descriptor in the table (including preopens).
        for (self.fs_descriptor_table.items) |slot| {
            if (slot) |d| closeFsDescriptor(d);
        }
        self.fs_descriptor_table.deinit(self.allocator);
        for (self.fs_preopens.items) |p| self.allocator.free(p.name);
        self.fs_preopens.deinit(self.allocator);

        // #476: any directory-entry-stream slots the guest leaked own a
        // heap-allocated Iterator. The iterator borrows the Dir handle
        // (via its `reader.dir` field) but does not close it, so we
        // only free the heap allocation here.
        for (self.dir_entry_stream_table.items) |maybe| {
            if (maybe) |s| self.allocator.destroy(s.iter);
        }
        self.dir_entry_stream_table.deinit(self.allocator);

        // wasi:sockets resource tables. Sockets are POD; networks own a
        // copy of the per-instance CIDR allow-list (#180) and free it on
        // drop. Resolve streams own their result slice + the heap struct
        // itself.
        for (self.network_table.items) |*maybe| {
            if (maybe.* != null) maybe.*.?.deinit(self.allocator);
        }
        self.network_table.deinit(self.allocator);
        if (self.sockets_allow_list_template.len != 0)
            self.allocator.free(self.sockets_allow_list_template);
        {
            const io = std.Io.Threaded.global_single_threaded.io();
            for (self.socket_table.items) |*maybe| {
                if (maybe.*) |*s| s.closeAll(io, self.allocator);
            }
        }
        self.socket_table.deinit(self.allocator);
        for (self.udp_incoming_streams.items) |maybe| {
            if (maybe) |s| self.allocator.destroy(s);
        }
        self.udp_incoming_streams.deinit(self.allocator);
        for (self.udp_outgoing_streams.items) |maybe| {
            if (maybe) |s| self.allocator.destroy(s);
        }
        self.udp_outgoing_streams.deinit(self.allocator);
        for (self.resolve_streams.items) |maybe| {
            if (maybe) |s| {
                self.allocator.free(s.results);
                self.allocator.destroy(s);
            }
        }
        self.resolve_streams.deinit(self.allocator);
        for (self.sockets_p3_stream_ctxs.items) |ctx| self.allocator.destroy(ctx);
        self.sockets_p3_stream_ctxs.deinit(self.allocator);
        for (self.fs_write_stream_ctxs.items) |ctx| self.allocator.destroy(ctx);
        self.fs_write_stream_ctxs.deinit(self.allocator);

        // wasi:http resource tables (#149). Each slot owns its heap
        // rep; HttpFields and OutgoingRequest also own inner string
        // slices that need recursive cleanup.
        for (self.http_fields_table.items) |maybe| {
            if (maybe) |f| {
                f.deinit(self.allocator);
                self.allocator.destroy(f);
            }
        }
        self.http_fields_table.deinit(self.allocator);
        for (self.http_outgoing_requests.items) |maybe| {
            if (maybe) |r| {
                r.deinit(self.allocator);
                self.allocator.destroy(r);
            }
        }
        self.http_outgoing_requests.deinit(self.allocator);
        for (self.http_incoming_requests.items) |maybe| {
            if (maybe) |r| {
                r.deinit(self.allocator);
                self.allocator.destroy(r);
            }
        }
        self.http_incoming_requests.deinit(self.allocator);
        for (self.http_outgoing_responses.items) |maybe| {
            if (maybe) |r| self.allocator.destroy(r);
        }
        self.http_outgoing_responses.deinit(self.allocator);
        for (self.http_incoming_responses.items) |maybe| {
            if (maybe) |r| {
                r.deinit(self.allocator);
                self.allocator.destroy(r);
            }
        }
        self.http_incoming_responses.deinit(self.allocator);
        for (self.http_request_options.items) |maybe| {
            if (maybe) |r| self.allocator.destroy(r);
        }
        self.http_request_options.deinit(self.allocator);
        for (self.http_response_outparams.items) |maybe| {
            if (maybe) |r| self.allocator.destroy(r);
        }
        self.http_response_outparams.deinit(self.allocator);
        for (self.http_incoming_bodies.items) |maybe| {
            if (maybe) |b| {
                b.deinit(self.allocator);
                self.allocator.destroy(b);
            }
        }
        self.http_incoming_bodies.deinit(self.allocator);
        for (self.http_outgoing_bodies.items) |maybe| {
            if (maybe) |b| self.allocator.destroy(b);
        }
        self.http_outgoing_bodies.deinit(self.allocator);
        for (self.http_future_responses.items) |maybe| {
            if (maybe) |f| self.allocator.destroy(f);
        }
        self.http_future_responses.deinit(self.allocator);
        for (self.http_future_trailers.items) |maybe| {
            if (maybe) |f| self.allocator.destroy(f);
        }
        self.http_future_trailers.deinit(self.allocator);
        // wasi:http@0.3.0 P3 resource tables (#487).
        for (self.http_requests_p3.items) |maybe| {
            if (maybe) |r| {
                r.deinit(self.allocator);
                self.allocator.destroy(r);
            }
        }
        self.http_requests_p3.deinit(self.allocator);
        for (self.http_responses_p3.items) |maybe| {
            if (maybe) |r| {
                r.deinit(self.allocator);
                self.allocator.destroy(r);
            }
        }
        self.http_responses_p3.deinit(self.allocator);
        for (self.http_request_options_p3.items) |maybe| {
            if (maybe) |r| self.allocator.destroy(r);
        }
        self.http_request_options_p3.deinit(self.allocator);
        self.pollable_table.deinit(self.allocator);
    }

    /// Captured stderr bytes (separate buffer from stdout).
    pub fn getStderrBytes(self: *const WasiCliAdapter) []const u8 {
        return self.stderr.getBufferContents();
    }

    /// Set the captured stdin to read from `bytes`. The slice is
    /// borrowed — caller must keep it alive for the run.
    pub fn setStdinBytes(self: *WasiCliAdapter, bytes: []const u8) void {
        self.stdin = streams.InputStream.fromBuffer(bytes);
    }

    /// Forward argv to `wasi:cli/environment.get-arguments`. The slices
    /// are borrowed — caller must keep them alive for the run.
    pub fn setArguments(self: *WasiCliAdapter, argv: []const []const u8) void {
        self.argv = argv;
    }

    /// Forward env to `wasi:cli/environment.get-environment`. The slices
    /// are borrowed — caller must keep them alive for the run.
    pub fn setEnvironment(self: *WasiCliAdapter, env: []const EnvVar) void {
        self.env = env;
    }

    /// Configure the sockets CIDR allow-list (#180, #583 A1). Each entry
    /// is parsed by `IpCidr.parse` (e.g. `"127.0.0.0/8"`, `"::1/128"`,
    /// `"fe80::/10"`). The slice is snapshotted into every 0.2 `Network`
    /// returned by `instance-network` from this point onward; previously
    /// created `Network` resources keep their own snapshot. The 0.3
    /// sockets path consults this template directly (no `network` rep).
    ///
    /// Empty-list semantics (see `sockets_allow_list_template` for the
    /// full table):
    ///   * 0.2 raw sockets — deny-all (legacy).
    ///   * 0.3 raw sockets — allow-all. `tcp-connect`, `udp-connect`
    ///     and `udp-send` skip the allow-list gate when the template
    ///     is empty; the kernel still enforces routability.
    ///   * DNS and outbound HTTP — deny (`name-unresolvable` /
    ///     `HTTP_request_denied`).
    ///
    /// Calling with an empty slice resets the template, freeing any
    /// prior allocation. On parse failure the previous template is
    /// preserved (the partially-filled buffer is freed).
    pub fn setSocketsAllowList(self: *WasiCliAdapter, cidrs: []const []const u8) !void {
        if (cidrs.len == 0) {
            if (self.sockets_allow_list_template.len != 0)
                self.allocator.free(self.sockets_allow_list_template);
            self.sockets_allow_list_template = &.{};
            return;
        }
        const parsed = try self.allocator.alloc(IpCidr, cidrs.len);
        var filled: usize = 0;
        errdefer self.allocator.free(parsed);
        while (filled < cidrs.len) : (filled += 1) {
            parsed[filled] = try IpCidr.parse(cidrs[filled]);
        }
        if (self.sockets_allow_list_template.len != 0)
            self.allocator.free(self.sockets_allow_list_template);
        self.sockets_allow_list_template = parsed;
    }

    /// Captured stdout bytes (valid for buffer-backed sinks).
    pub fn getStdoutBytes(self: *const WasiCliAdapter) []const u8 {
        return self.stdout.getBufferContents();
    }

    /// Register this adapter's `write_iface` as a provider for the named
    /// instance import (e.g. `"wasi:hello/world"`). The interface exposes
    /// a single member `member_name` (e.g. `"write"`) implementing
    /// `(list<u8>) -> ()`: each call appends the bytes to the captured
    /// stdout buffer.
    ///
    /// The caller-owned `providers` map is updated with a `host_instance`
    /// binding whose lifetime is tied to `self` — keep the adapter alive
    /// for as long as any component instance depends on it.
    pub fn populateProviders(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        instance_name: []const u8,
        member_name: []const u8,
    ) !void {
        try self.write_iface.members.put(self.allocator, member_name, .{
            .func = .{
                .context = self,
                .call = &writeBytes,
            },
        });
        try providers.put(self.allocator, instance_name, .{
            .host_instance = &self.write_iface,
        });
    }

    /// Register the WASI cli/run "println" surface used by the Phase 2B-hello
    /// fixture: `wasi:cli/stdout` (with `get-stdout`) and `wasi:io/streams`
    /// (with the output-stream method + resource-drop). The full WIT names
    /// of WASI 0.2 are passed verbatim in `instance_*_name` so callers can
    /// pin a specific interface version (`wasi:cli/stdout@0.2.6` etc.).
    pub fn populateWasiCliRun(
        self: *WasiCliAdapter,
        providers: *std.StringHashMapUnmanaged(ImportBinding),
        cli_stdout_name: []const u8,
        io_streams_name: []const u8,
    ) !void {
        try self.cli_stdout_iface.members.put(self.allocator, "get-stdout", .{
            .func = .{ .context = self, .call = &getStdoutHandle },
        });
        try providers.put(self.allocator, cli_stdout_name, .{
            .host_instance = &self.cli_stdout_iface,
        });

        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]output-stream.blocking-write-and-flush",
            .{ .func = .{ .context = self, .call = &blockingWriteAndFlush } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]output-stream.write",
            .{ .func = .{ .context = self, .call = &outputStreamWrite } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]output-stream.check-write",
            .{ .func = .{ .context = self, .call = &outputStreamCheckWrite } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]output-stream.blocking-flush",
            .{ .func = .{ .context = self, .call = &outputStreamBlockingFlush } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]output-stream.flush",
            .{ .func = .{ .context = self, .call = &outputStreamBlockingFlush } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]output-stream.subscribe",
            .{ .func = .{ .context = self, .call = &outputStreamSubscribe } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]input-stream.subscribe",
            .{ .func = .{ .context = self, .call = &inputStreamSubscribe } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[resource-drop]output-stream",
            .{ .func = .{ .context = self, .call = &dropOutputStream } },
        );
        // Input-stream member surface used by stdio-echo via stdin reads.
        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]input-stream.blocking-read",
            .{ .func = .{ .context = self, .call = &blockingRead } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[method]input-stream.read",
            .{ .func = .{ .context = self, .call = &blockingRead } },
        );
        try self.io_streams_iface.members.put(
            self.allocator,
            "[resource-drop]input-stream",
            .{ .func = .{ .context = self, .call = &dropInputStream } },
        );
        try providers.put(self.allocator, io_streams_name, .{
            .host_instance = &self.io_streams_iface,
        });
    }

    /// Register `wasi:cli/stderr` (mirror of stdout but writing to the
