    /// Reject paths that would escape the preopen sandbox: any `..` path
    /// component, any `\\` separator, any `:` (Windows drive prefix), or
    /// a leading `/` (absolute). Returns the appropriate `error-code`
    /// per the 0.3 fixture expectations on rejection.
    ///
    /// The 0.3 fixtures (`filesystem-{open-errors, stat, mkdir-rmdir,
    /// unlink-errors, rename, hard-links, metadata-hash}`) uniformly
    /// expect `not-permitted` for any sandbox-escaping path:
    /// absolute (`/...`), `..` components, etc. Windows-only escapes
    /// (`\` separator, drive prefix `:`) remain `.access` since no
    /// fixture targets them. (#571.)
    pub fn validateSandboxPath(path: []const u8) ?FsErrorCode {
        if (path.len == 0) return null;
        if (path[0] == '/') return .not_permitted;
        for (path) |c| {
            if (c == '\\' or c == ':') return .access;
        }
        var it = std.mem.splitScalar(u8, path, '/');
        while (it.next()) |comp| {
            if (std.mem.eql(u8, comp, "..")) return .not_permitted;
        }
        return null;
    }

    /// Walk each `/`-separated prefix of `path` and check whether any
    /// component is a symlink in the host filesystem under `base_dir`.
    ///
    /// Per WASI sandbox semantics (#571): a symlink anywhere in a path
    /// component creates a potential escape, so we reject the request
    /// with `not-permitted` rather than letting the kernel follow the
    /// link.
    ///   - **Intermediate** symlinks are always rejected, regardless of
    ///     the operation's `path-flags.symlink-follow` setting. Even an
    ///     op that wouldn't normally follow the last component still
    ///     traverses intermediates (e.g. `unlink-file-at("p/x")` walks
    ///     `p` before unlinking `x`).
    ///   - The **final** component is rejected only if the operation
    ///     follows symlinks (e.g. `stat-at` with `SYMLINK_FOLLOW`,
    ///     `open-at` with that flag, `link-at` with `follow_old=true`).
    ///     If the op targets the link entry itself (e.g. `unlink-file-at`,
    ///     `stat-at` without follow), the final symlink is permitted.
    ///
    /// Returns `null` if the path is clean; `.not_permitted` if a
    /// disallowed symlink component is detected. Non-existent prefixes
    /// pass through (the underlying op will surface the kernel error).
    pub fn checkPathSymlinks(
        base_dir: std.Io.Dir,
        path: []const u8,
        follow_final: bool,
    ) ?FsErrorCode {
        if (path.len == 0) return null;
        const io = std.Io.Threaded.global_single_threaded.io();
        var end: usize = 0;
        while (end < path.len) {
            while (end < path.len and path[end] == '/') end += 1;
            if (end >= path.len) break;
            while (end < path.len and path[end] != '/') end += 1;
            const prefix = path[0..end];
            const is_last = blk: {
                var j = end;
                while (j < path.len and path[j] == '/') j += 1;
                break :blk (j >= path.len);
            };
            const st = base_dir.statFile(io, prefix, .{ .follow_symlinks = false }) catch {
                // Component doesn't exist — can't be a symlink we'd follow.
                return null;
            };
            if (st.kind == .sym_link) {
                if (!is_last) return .not_permitted;
                if (follow_final) return .not_permitted;
            }
        }
        return null;
    }

    /// Whether `path` would make Linux `unlinkat(AT_REMOVEDIR)` (or
    /// the Zig stdlib's `dirDeleteDirPosix`) return `EINVAL` — i.e.
    /// the path's last component is `.` or `..`. Both the kernel and
    /// Zig stdlib treat this as a "programmer bug" and panic in debug
    /// builds; the 0.3 filesystem-mkdir-rmdir fixture explicitly tests
    /// `rmdir(".")` and expects `Err(ErrorCode::Invalid | Access)`.
    /// Detect early so the guest gets a clean `.invalid` rather than a
    /// host trap. Empty path is left to the kernel (NoEntry).
    fn rmdirPathIsInvalid(path: []const u8) bool {
        if (path.len == 0) return false;
        // Drop trailing slashes — `rmdir("foo/")` should behave like
        // `rmdir("foo")` for the trailing-`.` check below.
        var end = path.len;
        while (end > 0 and path[end - 1] == '/') end -= 1;
        if (end == 0) return true; // path was all `/` — kernel EINVAL.
        var start = end;
        while (start > 0 and path[start - 1] != '/') start -= 1;
        const last = path[start..end];
        return std.mem.eql(u8, last, ".") or std.mem.eql(u8, last, "..");
    }

    fn lookupFsDescriptor(self: *WasiCliAdapter, handle: u32) ?*FsDescriptor {
        if (handle >= self.fs_descriptor_table.items.len) return null;
        if (self.fs_descriptor_table.items[handle]) |*d| return d;
        return null;
    }

    /// Append a new descriptor slot, returning the handle. Reuses null
    /// slots if any.
    fn pushFsDescriptor(self: *WasiCliAdapter, d: FsDescriptor) !u32 {
        for (self.fs_descriptor_table.items, 0..) |slot, i| {
            if (slot == null) {
                self.fs_descriptor_table.items[i] = d;
                return @intCast(i);
            }
        }
        const idx: u32 = @intCast(self.fs_descriptor_table.items.len);
        try self.fs_descriptor_table.append(self.allocator, d);
        return idx;
    }

    /// Build a `result<X, error-code>` lift where the err arm carries the
    /// `error-code` variant `code`. Caller-owned via `allocator`.
    fn fsResultErr(allocator: Allocator, code: FsErrorCode) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = .{ .variant_val = .{ .discriminant = @intFromEnum(code), .payload = null } };
        return .{ .result_val = .{ .is_ok = false, .payload = payload } };
    }

    /// Build a `result<X, error-code>` ok lift. `value` is moved into a
    /// fresh `*InterfaceValue` payload.
    fn fsResultOk(allocator: Allocator, value: InterfaceValue) !InterfaceValue {
        const payload = try allocator.create(InterfaceValue);
        payload.* = value;
        return .{ .result_val = .{ .is_ok = true, .payload = payload } };
    }

    /// `wasi:filesystem/preopens.get-directories: () -> list<tuple<own<descriptor>, string>>`.
    fn fsGetDirectories(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        const n = self.fs_preopens.items.len;
        if (n == 0) {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        }

        // Each tuple<own<descriptor>, string>: handle@0:u32, ptr@4:u32, len@8:u32.
        const stride: usize = 12;
        const scratch = try allocator.alloc(u8, n * stride);
        defer allocator.free(scratch);

        for (self.fs_preopens.items, 0..) |p, i| {
            const name_ptr = ci.hostAllocAndWrite(p.name) orelse return error.IoError;
            const off = i * stride;
            // `dir_handle` is the host-side 0-based slot index; the
            // canon-ABI wire handle is `slot + 1` per the resource
            // offset convention (`executor.encodeResourceWire`). Since
            // we're writing the tuple straight into linear memory we
            // apply the encoding here. (#520 wave 2)
            std.mem.writeInt(u32, scratch[off..][0..4], abi.encodeResourceWireAbi(p.dir_handle), .little);
            std.mem.writeInt(u32, scratch[off + 4 ..][0..4], name_ptr, .little);
            std.mem.writeInt(u32, scratch[off + 8 ..][0..4], @intCast(p.name.len), .little);
        }

        const list_ptr = ci.hostAllocAndWrite(scratch) orelse return error.IoError;
        results[0] = .{ .list = .{ .ptr = list_ptr, .len = @intCast(n) } };
    }

    /// `wasi:filesystem/types.descriptor-type` discriminants in WIT order.
    const DescType = enum(u32) {
        unknown = 0,
        block_device = 1,
        character_device = 2,
        directory = 3,
        fifo = 4,
        symbolic_link = 5,
        regular_file = 6,
        socket = 7,
    };

    /// `[method]descriptor.get-type: (borrow<descriptor>) -> result<descriptor-type, error-code>`.
    fn fsDescriptorGetType(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const dt: DescType = switch (d.*) {
            .preopen, .dir => .directory,
            .file => .regular_file,
        };
        const variant = InterfaceValue{ .variant_val = .{
            .discriminant = @intFromEnum(dt),
            .payload = null,
        } };
        results[0] = try fsResultOk(allocator, variant);
    }

    /// `[method]descriptor.get-flags: (borrow<descriptor>) -> result<descriptor-flags, error-code>` (#181).
    /// Returns the `descriptor-flags` the guest passed when this
    /// descriptor was opened (preopens always read|write|mutate).
    fn fsDescriptorGetFlags(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const words = try allocator.alloc(u32, 1);
        words[0] = d.flags().toBits();
        results[0] = try fsResultOk(allocator, .{ .flags_val = words });
    }

    /// `[method]descriptor.stat: (borrow<descriptor>) -> result<descriptor-stat, error-code>`.
    /// The record fields are `(type, link-count, size, atime?, mtime?, ctime?)`.
    /// All three timestamps are lifted from the host `Io.File.Stat` via
    /// `buildDescriptorStatRecord` (#177); `mtime` / `ctime` always
    /// surface as `option::some` on filesystems that record them, while
    /// `atime` may be `option::none` if the host reports it as unset.
    fn fsDescriptorStat(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };

        const io = std.Io.Threaded.global_single_threaded.io();

        const stat_result: ?std.Io.File.Stat = switch (d.*) {
            .preopen => |dir| dir.dir.stat(io) catch null,
            .dir => |dir| dir.dir.stat(io) catch null,
            .file => |f| f.file.stat(io) catch |err| {
                results[0] = try fsResultErr(allocator, mapFsError(err));
                return;
            },
        };

        if (stat_result) |st| {
            results[0] = try fsResultOk(allocator, try buildDescriptorStatRecord(allocator, st));
            return;
        }

        // Dir handle but `dir.stat` failed (or unsupported on this target).
        // Fall back to a minimal record with timestamps as `option::none`.
        const fields = try allocator.alloc(InterfaceValue, 6);
        fields[0] = .{ .variant_val = .{ .discriminant = @intFromEnum(WasiCliAdapter.DescType.directory), .payload = null } };
        fields[1] = .{ .u64 = 1 };
        fields[2] = .{ .u64 = 0 };
        fields[3] = .{ .option_val = .{ .is_some = false, .payload = null } };
        fields[4] = .{ .option_val = .{ .is_some = false, .payload = null } };
        fields[5] = .{ .option_val = .{ .is_some = false, .payload = null } };
        results[0] = try fsResultOk(allocator, .{ .record_val = fields });
    }

    /// `[method]descriptor.stat-at: (borrow<descriptor>, path-flags, string)
    ///   -> result<descriptor-stat, error-code>`.
    fn fsDescriptorStatAt(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        // `path-flags` (#181): bit 0 = symlink-follow.
        const path_flags: u32 = switch (args[1]) {
            .flags_val => |w| if (w.len == 0) 0 else w[0],
            .u32 => |v| v,
            else => 0,
        };
        const follow_symlinks = (path_flags & 0b1) != 0;
        const path_pl = switch (args[2]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };

        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const base_dir: std.Io.Dir = d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };

        const path_bytes = ci.readGuestBytes(path_pl.ptr, path_pl.len) orelse
            return error.OutOfBoundsMemory;

        if (validateSandboxPath(path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (checkPathSymlinks(base_dir, path_bytes, follow_symlinks)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        const io = std.Io.Threaded.global_single_threaded.io();
        const st = base_dir.statFile(io, path_bytes, .{
            .follow_symlinks = follow_symlinks,
        }) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        results[0] = try fsResultOk(allocator, try buildDescriptorStatRecord(allocator, st));
    }

    /// `[method]descriptor.set-times: (borrow<descriptor>, new-timestamp, new-timestamp)
    ///   -> result<_, error-code>`.
    fn fsDescriptorSetTimes(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const ats = try liftNewTimestamp(args[1]);
        const mts = try liftNewTimestamp(args[2]);

        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };

        const io = std.Io.Threaded.global_single_threaded.io();
        switch (d.*) {
            .file => |f| {
                f.file.setTimestamps(io, .{
                    .access_timestamp = ats,
                    .modify_timestamp = mts,
                }) catch |err| {
                    results[0] = try fsResultErr(allocator, mapFsError(err));
                    return;
                };
            },
            .preopen, .dir => {
                // The `Io.Dir` API has no whole-directory setTimestamps;
                // only `setTimestamps(sub_path, ...)`. For a bare directory
                // descriptor (no sub_path), we report `not_permitted`.
                results[0] = try fsResultErr(allocator, .not_permitted);
                return;
            },
        }

        const ok_payload = try allocator.create(InterfaceValue);
        ok_payload.* = .{ .tuple_val = &.{} };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
    }

    /// `[method]descriptor.set-times-at: (borrow<descriptor>, path-flags, string,
    ///   new-timestamp, new-timestamp) -> result<_, error-code>`.
    fn fsDescriptorSetTimesAt(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 5 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const path_flags: u32 = switch (args[1]) {
            .flags_val => |w| if (w.len == 0) 0 else w[0],
            .u32 => |v| v,
            else => 0,
        };
        const path_pl = switch (args[2]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const ats = try liftNewTimestamp(args[3]);
        const mts = try liftNewTimestamp(args[4]);

        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const base_dir: std.Io.Dir = d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };

        const path_bytes = ci.readGuestBytes(path_pl.ptr, path_pl.len) orelse
            return error.OutOfBoundsMemory;

        if (validateSandboxPath(path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        // path-flags bit 0 = symlink-follow (per WIT); 0 means "don't follow".
        const follow_symlinks = (path_flags & 0b1) != 0;
        if (checkPathSymlinks(base_dir, path_bytes, follow_symlinks)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        const io = std.Io.Threaded.global_single_threaded.io();
        // Pre-check path existence: Zig stdlib's `Dir.setTimestamps`
        // error set has no `FileNotFound` variant, so the kernel
        // `ENOENT` on `utimensat` falls into `error.Unexpected` and
        // we'd return `.io` instead of the spec-required `.no_entry`.
        // Probe with `statFile` (which does have `FileNotFound`) and
        // map kernel errors here. (#571.)
        _ = base_dir.statFile(io, path_bytes, .{ .follow_symlinks = follow_symlinks }) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };
        base_dir.setTimestamps(io, path_bytes, .{
            .follow_symlinks = follow_symlinks,
            .access_timestamp = ats,
            .modify_timestamp = mts,
        }) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        const ok_payload = try allocator.create(InterfaceValue);
        ok_payload.* = .{ .tuple_val = &.{} };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
    }

    /// `[method]descriptor.open-at: (borrow<descriptor>, path-flags, string,
    ///   open-flags, descriptor-flags) -> result<own<descriptor>, error-code>`.
    ///
    /// Honors all six descriptor-flags bits (#181):
    /// - `read`/`write` map to Zig open-mode.
    /// - `file-integrity-sync`/`data-integrity-sync` are recorded on the
    ///   new descriptor so blocking-flush calls `file.sync()`.
    /// - `requested-write-sync` is stored (POSIX `O_RSYNC`, read-side)
    ///   but not enforceable today; reported via `get-flags`.
    /// - `mutate-directory` is only valid on directory descriptors and
    ///   is required on the *base* directory for any `open-at` that
    ///   would create, truncate, or open with write access.
    /// `path-flags.symlink-follow` is plumbed into both `openDir` and
    /// `openFile`. `createFile` ignores it because Zig 0.16's
    /// `CreateFileOptions` has no `follow_symlinks` field.
    ///
    /// Flag propagation per `filesystem-flags-and-type` fixture (#571):
    /// - `OpenFlags::CREATE` implies `descriptor-flags::WRITE`.
    /// - If neither `READ` nor `WRITE` is requested in the child flags
    ///   (and `CREATE` isn't adding `WRITE`), default to `READ` so
    ///   `get-flags` round-trips a useful value.
    /// - Opening a sub-directory always implies iteration capability.
    /// Truncation per `filesystem-set-size` (#571): if `TRUNCATE` and
    /// `WRITE`, the file is zero-sized after open via `setLength(0)`.
    fn fsDescriptorOpenAt(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 5 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const path_flags: u32 = switch (args[1]) {
            .flags_val => |w| if (w.len == 0) 0 else w[0],
            .u32 => |v| v,
            else => 0,
        };
        const path_pl = switch (args[2]) {
            .string => |pl| pl,
            else => return error.InvalidArgs,
        };
        const open_flags: u32 = switch (args[3]) {
            .flags_val => |w| if (w.len == 0) 0 else w[0],
            .u32 => |v| v,
            else => 0,
        };
        const desc_flags_bits: u32 = switch (args[4]) {
            .flags_val => |w| if (w.len == 0) 0 else w[0],
            .u32 => |v| v,
            else => 0,
        };
        var child_flags = FsDescriptorFlags.fromBits(desc_flags_bits);

        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const base_flags = d.flags();
        const base_dir: std.Io.Dir = d.asDir() orelse {
            results[0] = try fsResultErr(allocator, .not_directory);
            return;
        };

        // open-flags bits per WIT order: 0=create, 1=directory, 2=exclusive, 3=truncate.
        const want_create = (open_flags & 0b0001) != 0;
        const want_directory = (open_flags & 0b0010) != 0;
        const want_exclusive = (open_flags & 0b0100) != 0;
        const want_truncate = (open_flags & 0b1000) != 0;
        const follow_symlinks = (path_flags & 0b1) != 0;

        // Default-and-imply rules per `filesystem-flags-and-type` fixture:
        //   - If neither READ nor WRITE was explicitly requested by the
        //     guest, default to READ (so `get-flags` round-trips a
        //     useful value on a "I just want a handle" open). Apply
        //     this BEFORE CREATE→WRITE so e.g. `open(CREATE|EXCL, empty)`
        //     yields READ|WRITE, not just WRITE.
        //   - `OpenFlags::CREATE` always implies WRITE on the resulting
        //     descriptor; `WRITE alone (without CREATE) does not imply
        //     READ`.
        if (!child_flags.read and !child_flags.write) child_flags.read = true;
        if (want_create) child_flags.write = true;

        const want_read = child_flags.read;
        const want_write = child_flags.write;

        // Spec (#181): if the base directory was opened without
        // `mutate-directory`, any child open that would mutate (create,
        // truncate, or any write access) must be denied with read-only.
        // Cheap check before we touch guest memory.
        const wants_mutate = want_create or want_truncate or want_write or
            child_flags.mutate_directory;
        if (wants_mutate and !base_flags.mutate_directory) {
            results[0] = try fsResultErr(allocator, .read_only);
            return;
        }

        const path_bytes = ci.readGuestBytes(path_pl.ptr, path_pl.len) orelse
            return error.OutOfBoundsMemory;

        if (validateSandboxPath(path_bytes)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }
        if (checkPathSymlinks(base_dir, path_bytes, follow_symlinks)) |code| {
            results[0] = try fsResultErr(allocator, code);
            return;
        }

        // `mutate-directory` is only meaningful on directory descriptors;
        // strip it from the file-shaped child to keep `get-flags` honest.
        var stored_flags = child_flags;
        if (!want_directory) stored_flags.mutate_directory = false;

        const io = std.Io.Threaded.global_single_threaded.io();

        // Probe the target's kind so an `open-at` without `OpenFlags::DIRECTORY`
        // on a directory path still produces a directory descriptor
        // (per `filesystem-flags-and-type` fixture) — and so a WRITE
        // open against a directory surfaces `IsDirectory` rather than
        // succeeding via `openFile`. The probe is skipped when CREATE
        // is requested (the path may not exist yet). (#571.)
        var open_as_directory = want_directory;
        if (!want_create) {
            const probe = base_dir.statFile(io, path_bytes, .{
                .follow_symlinks = follow_symlinks,
            }) catch null;
            if (probe) |st| {
                if (st.kind == .directory) {
                    if (want_write) {
                        results[0] = try fsResultErr(allocator, .is_directory);
                        return;
                    }
                    open_as_directory = true;
                    // Dir descriptors don't reflect the file-shaped
                    // `mutate_directory` strip we did above.
                    stored_flags.mutate_directory = child_flags.mutate_directory;
                }
            }
        }

        if (open_as_directory) {
            // Directories are always iterable so `read-directory` works
            // on any guest-opened sub-dir (#571 follow-up to #476).
            const new_dir = base_dir.openDir(io, path_bytes, .{
                .follow_symlinks = follow_symlinks,
                .iterate = true,
            }) catch |err| {
                results[0] = try fsResultErr(allocator, mapFsError(err));
                return;
            };
            const new_handle = self.pushFsDescriptor(.{ .dir = .{
                .dir = new_dir,
                .flags = stored_flags,
            } }) catch {
                new_dir.close(io);
                results[0] = try fsResultErr(allocator, .insufficient_memory);
                return;
            };
            results[0] = try fsResultOk(allocator, .{ .handle = new_handle });
            return;
        }

        const new_file = if (want_create) base_dir.createFile(io, path_bytes, .{
            .read = want_read,
            .truncate = want_truncate,
            .exclusive = want_exclusive,
        }) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        } else base_dir.openFile(io, path_bytes, .{
            .mode = if (want_write and want_read)
                .read_write
            else if (want_write)
                .write_only
            else
                .read_only,
            .follow_symlinks = follow_symlinks,
        }) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        // Honor `OpenFlags::TRUNCATE` on the already-existing path —
        // `createFile.truncate` covers the CREATE case; an open without
        // CREATE still needs an explicit `setLength(0)` to truncate.
        // Skip if WRITE wasn't requested (truncate without write is
        // meaningless and `setLength` will EBADF a read-only fd). (#571)
        if (want_truncate and !want_create and want_write) {
            new_file.setLength(io, 0) catch |err| {
                new_file.close(io);
                results[0] = try fsResultErr(allocator, mapFsError(err));
                return;
            };
        }

        const new_handle = self.pushFsDescriptor(.{ .file = .{
            .file = new_file,
            .flags = stored_flags,
        } }) catch {
            new_file.close(io);
            results[0] = try fsResultErr(allocator, .insufficient_memory);
            return;
        };
        results[0] = try fsResultOk(allocator, .{ .handle = new_handle });
    }

    /// `[method]descriptor.read-via-stream: (borrow<descriptor>, u64) -> result<own<input-stream>, error-code>`.
    fn fsDescriptorReadViaStream(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const offset = switch (args[1]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const file: std.Io.File = switch (d.*) {
            .file => |f| f.file,
            .dir, .preopen => {
                results[0] = try fsResultErr(allocator, .is_directory);
                return;
            },
        };
        const stream = self.allocator.create(streams.InputStream) catch {
            results[0] = try fsResultErr(allocator, .insufficient_memory);
            return;
        };
        stream.* = streams.InputStream.fromHostFile(file, offset);
        try self.owned_input_streams.append(self.allocator, stream);
        const stream_handle = try self.allocInputStreamHandle(stream);
        results[0] = try fsResultOk(allocator, .{ .handle = stream_handle });
    }

    /// `[method]descriptor.write-via-stream: (borrow<descriptor>, u64) -> result<own<output-stream>, error-code>`.
    fn fsDescriptorWriteViaStream(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const offset = switch (args[1]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        const stream_handle = try self.fsAllocOutputFileStream(handle, offset, false, allocator, results);
        if (stream_handle) |h| {
            results[0] = try fsResultOk(allocator, .{ .handle = h });
        }
    }

    /// `[method]descriptor.append-via-stream: (borrow<descriptor>) -> result<own<output-stream>, error-code>`.
    fn fsDescriptorAppendViaStream(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const stream_handle = try self.fsAllocOutputFileStream(handle, 0, true, allocator, results);
        if (stream_handle) |h| {
            results[0] = try fsResultOk(allocator, .{ .handle = h });
        }
    }

    /// Common helper for `write-via-stream` / `append-via-stream`.
    /// On error, writes the err-arm `result_val` into `results[0]` and
    /// returns `null`. On success, returns the new stream handle and
    /// leaves `results[0]` untouched (caller wraps).
    fn fsAllocOutputFileStream(
        self: *WasiCliAdapter,
        handle: u32,
        offset: u64,
        append: bool,
        allocator: Allocator,
        results: []InterfaceValue,
    ) !?u32 {
        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return null;
        };
        const fs_file: FsDescriptor.FsFile = switch (d.*) {
            .file => |f| f,
            .dir, .preopen => {
                results[0] = try fsResultErr(allocator, .is_directory);
                return null;
            },
        };
        const stream = self.allocator.create(streams.OutputStream) catch {
            results[0] = try fsResultErr(allocator, .insufficient_memory);
            return null;
        };
        stream.* = streams.OutputStream.toHostFile(
            fs_file.file,
            offset,
            append,
            fs_file.flags.needsWriteSync(),
        );
        try self.owned_output_streams.append(self.allocator, stream);
        return try self.allocStreamHandle(stream);
    }

    /// `[method]descriptor.read: (borrow<descriptor>, filesize, filesize)
    ///   -> result<tuple<list<u8>, bool>, error-code>`. (#475)
    ///
    /// The bool component is `true` when the read reached end-of-file
    /// (less data returned than requested, or the underlying read
    /// returned 0). The 64 MiB cap mirrors the canonical-ABI chunk
    /// chosen elsewhere in the adapter to prevent a hostile `length`
    /// from triggering a multi-exabyte host allocation.
    fn fsDescriptorRead(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const length: u64 = switch (args[1]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };
        const offset: u64 = switch (args[2]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };

        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const fs_file: FsDescriptor.FsFile = switch (d.*) {
            .file => |f| f,
            .dir, .preopen => {
                results[0] = try fsResultErr(allocator, .is_directory);
                return;
            },
        };
        if (!fs_file.flags.read) {
            results[0] = try fsResultErr(allocator, .access);
            return;
        }

        const cap: usize = @intCast(@min(length, 64 * 1024 * 1024));
        const buf = allocator.alloc(u8, cap) catch {
            results[0] = try fsResultErr(allocator, .insufficient_memory);
            return;
        };
        defer allocator.free(buf);

        const io = std.Io.Threaded.global_single_threaded.io();
        const n: usize = if (cap == 0) 0 else fs_file.file.readPositional(io, &.{buf}, offset) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        const guest_ptr: u32 = if (n == 0) 0 else (ci.hostAllocAndWrite(buf[0..n]) orelse return error.IoError);

        const eof = (cap == 0) or (n < cap);
        const tuple_fields = try allocator.alloc(InterfaceValue, 2);
        tuple_fields[0] = .{ .list = .{ .ptr = guest_ptr, .len = @intCast(n) } };
        tuple_fields[1] = .{ .bool = eof };
        results[0] = try fsResultOk(allocator, .{ .tuple_val = tuple_fields });
    }

    /// `[method]descriptor.write: (borrow<descriptor>, list<u8>, filesize)
    ///   -> result<filesize, error-code>`. (#475)
    ///
    /// Returns the number of bytes written. `writePositionalAll` either
    /// writes every byte or fails, so on success the count equals the
    /// input length.
    fn fsDescriptorWrite(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const list = switch (args[1]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };
        const offset: u64 = switch (args[2]) {
            .u64 => |v| v,
            else => return error.InvalidArgs,
        };

        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const fs_file: FsDescriptor.FsFile = switch (d.*) {
            .file => |f| f,
            .dir, .preopen => {
                results[0] = try fsResultErr(allocator, .is_directory);
                return;
            },
        };
        if (!fs_file.flags.write) {
            results[0] = try fsResultErr(allocator, .access);
            return;
        }

        const bytes = ci.readGuestBytes(list.ptr, list.len) orelse
            return error.OutOfBoundsMemory;

        const io = std.Io.Threaded.global_single_threaded.io();
        fs_file.file.writePositionalAll(io, bytes, offset) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        results[0] = try fsResultOk(allocator, .{ .u64 = @intCast(bytes.len) });
    }

    /// `[method]descriptor.sync: (borrow<descriptor>) -> result<_, error-code>`. (#475)
    fn fsDescriptorSync(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        try fsDescriptorSyncImpl(self, args, results, allocator);
    }

    /// `[method]descriptor.sync-data: (borrow<descriptor>) -> result<_, error-code>`.
    /// std.Io.File 0.16 exposes only `sync` (which flushes metadata too);
    /// data-only sync would require a direct `fdatasync` syscall. Falling
    /// back to a full sync is conformant — guests only require that the
    /// data reaches durable storage. (#475)
    fn fsDescriptorSyncData(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        try fsDescriptorSyncImpl(self, args, results, allocator);
    }

    fn fsDescriptorSyncImpl(
        self: *WasiCliAdapter,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        if (args.len < 1 or results.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };

        const d = self.lookupFsDescriptor(handle) orelse {
            results[0] = try fsResultErr(allocator, .bad_descriptor);
            return;
        };
        const fs_file: FsDescriptor.FsFile = switch (d.*) {
            .file => |f| f,
            .dir, .preopen => {
                // Directory sync is not exposed via std.Io.Dir today.
                // Report success; an `fsync` on a directory is advisory.
                const ok_payload = try allocator.create(InterfaceValue);
                ok_payload.* = .{ .tuple_val = &.{} };
                results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
                return;
            },
        };
        // Per `filesystem-io` fixture: `sync` / `sync-data` on a
        // read-only fd is a successful no-op rather than `access`.
        // The kernel-level `fsync(2)` on a read-only fd is valid but
        // typically pointless — for portability, just succeed without
        // calling it so guest semantics are deterministic. (#571.)
        if (!fs_file.flags.write) {
            const ok_payload = try allocator.create(InterfaceValue);
            ok_payload.* = .{ .tuple_val = &.{} };
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
            return;
        }

        const io = std.Io.Threaded.global_single_threaded.io();
        fs_file.file.sync(io) catch |err| {
            results[0] = try fsResultErr(allocator, mapFsError(err));
            return;
        };

        const ok_payload = try allocator.create(InterfaceValue);
        ok_payload.* = .{ .tuple_val = &.{} };
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = ok_payload } };
    }

    /// `[method]descriptor.set-size: (borrow<descriptor>, filesize)
    ///   -> result<_, error-code>`. Truncates or extends the file. (#475)
    fn fsDescriptorSetSize(
        ctx_opaque: ?*anyopaque,
