    fn cleanupHttpResources(self: *WasiCliAdapter) void {
        for (self.http_fields_table.items) |*maybe| {
            if (maybe.*) |f| {
                f.deinit(self.allocator);
                self.allocator.destroy(f);
                maybe.* = null;
            }
        }
        for (self.http_outgoing_requests.items) |*maybe| {
            if (maybe.*) |r| {
                r.deinit(self.allocator);
                self.allocator.destroy(r);
                maybe.* = null;
            }
        }
        for (self.http_incoming_requests.items) |*maybe| {
            if (maybe.*) |r| {
                r.deinit(self.allocator);
                self.allocator.destroy(r);
                maybe.* = null;
            }
        }
        for (self.http_outgoing_responses.items) |*maybe| {
            if (maybe.*) |r| {
                self.allocator.destroy(r);
                maybe.* = null;
            }
        }
        for (self.http_incoming_responses.items) |*maybe| {
            if (maybe.*) |r| {
                r.deinit(self.allocator);
                self.allocator.destroy(r);
                maybe.* = null;
            }
        }
        for (self.http_request_options.items) |*maybe| {
            if (maybe.*) |r| {
                self.allocator.destroy(r);
                maybe.* = null;
            }
        }
        for (self.http_response_outparams.items) |*maybe| {
            if (maybe.*) |r| {
                self.allocator.destroy(r);
                maybe.* = null;
            }
        }
        for (self.http_incoming_bodies.items) |*maybe| {
            if (maybe.*) |b| {
                if (b.stream) |s| self.releaseOwnedInputStream(s);
                b.deinit(self.allocator);
                self.allocator.destroy(b);
                maybe.* = null;
            }
        }
        for (self.http_outgoing_bodies.items) |*maybe| {
            if (maybe.*) |b| {
                if (b.stream) |s| self.releaseOwnedOutputStream(s);
                self.allocator.destroy(b);
                maybe.* = null;
            }
        }
        for (self.http_future_responses.items) |*maybe| {
            if (maybe.*) |f| {
                self.allocator.destroy(f);
                maybe.* = null;
            }
        }
        for (self.http_future_trailers.items) |*maybe| {
            if (maybe.*) |f| {
                self.allocator.destroy(f);
                maybe.* = null;
            }
        }
    }

    // --- helpers for extracting bytes from InterfaceValue args ---

    /// Extract a byte slice from an InterfaceValue that is either a
    /// `.string` PtrLen or a `.list` PtrLen (both pointing into guest
    /// memory). Returns null on invalid encoding or out-of-bounds
    /// guest memory.
    fn extractArgBytes(ci: *ComponentInstance, arg: InterfaceValue) ?[]const u8 {
        switch (arg) {
            .string => |pl| {
                if (pl.len == 0) return "";
                return ci.readGuestBytes(pl.ptr, pl.len);
            },
            .list => |pl| {
                if (pl.len == 0) return "";
                return ci.readGuestBytes(pl.ptr, pl.len);
            },
            else => return null,
        }
    }

    /// Like `extractArgBytes` but allocates a copy.
    fn extractArgBytesAlloc(
        alloc: Allocator,
        ci: *ComponentInstance,
        arg: InterfaceValue,
    ) !?[]u8 {
        switch (arg) {
            .string => |pl| {
                if (pl.len == 0) return try alloc.dupe(u8, "");
                const src = ci.readGuestBytes(pl.ptr, pl.len) orelse return null;
                return try alloc.dupe(u8, src);
            },
            .list => |pl| {
                if (pl.len == 0) return try alloc.dupe(u8, "");
                const src = ci.readGuestBytes(pl.ptr, pl.len) orelse return null;
                return try alloc.dupe(u8, src);
            },
            else => return null,
        }
    }

    // --- fields ---

    /// `[constructor]fields() -> own<fields>`.
    fn httpFieldsConstructor(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        _: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;
        const f = try self.allocator.create(HttpFields);
        f.* = .{};
        const h = try self.pushHttpFields(f);
        results[0] = .{ .handle = h };
    }

    /// `[static]fields.from-list(list<tuple<field-name, field-value>>)
    ///   -> result<own<fields>, header-error>`.
    ///
    /// The argument is a guest-memory list of `tuple<string, string>`
    /// records. Each element is laid out as four u32s — name.ptr,
    /// name.len, value.ptr, value.len — for a 16-byte stride. We lift
    /// each tuple, copy both strings into adapter-owned heap, and
    /// populate the new `HttpFields.entries`. No header validation is
    /// performed today (a follow-up may reject `.invalid_syntax` per
    /// RFC 7230); guests that round-trip through `entries` get back
    /// what they passed in.
    fn httpFieldsFromList(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const list = switch (args[0]) {
            .list => |pl| pl,
            else => return error.InvalidArgs,
        };

        // Lift+validate the input list FIRST so that on
        // `header-error.invalid-syntax` we don't leak the
        // `HttpFields` slot.
        var lifted_entries: []HttpFieldEntry = &.{};
        if (list.len > 0) {
            const mem = ci.canonicalMemory() orelse return error.OutOfBoundsMemory;
            lifted_entries = liftFieldEntries(self.allocator, mem.data, list.ptr, list.len) catch |e| switch (e) {
                error.InvalidFieldSyntax => {
                    results[0] = try httpHeaderErr(allocator, .invalid_syntax);
                    return;
                },
                else => return e,
            };
        }
        errdefer {
            for (lifted_entries) |entry| {
                self.allocator.free(entry.name);
                self.allocator.free(entry.value);
            }
            if (lifted_entries.len > 0) self.allocator.free(lifted_entries);
        }

        const f = try self.allocator.create(HttpFields);
        f.* = .{};
        if (lifted_entries.len > 0) {
            f.entries = .{ .items = lifted_entries, .capacity = lifted_entries.len };
            lifted_entries = &.{}; // ownership transferred — disarm errdefer
        }
        errdefer {
            f.deinit(self.allocator);
            self.allocator.destroy(f);
        }

        const h = try self.pushHttpFields(f);
        results[0] = try httpResultOk(allocator, .{ .handle = h });
    }

    /// `[method]fields.entries(borrow<fields>)
    ///   -> list<tuple<field-name, field-value>>`. Returns the stored
    /// entries as InterfaceValue list of tuples, each tuple containing
    /// a list_val of u8 for name and a list_val of u8 for value.
    fn httpFieldsEntries(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => {
                results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
                return;
            },
        };

        const f = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        };

        // Lower into canonical `list<tuple<list<u8>, list<u8>>>` PtrLen
        // form (issue #402): each entry is 16 bytes of (ptr,len) pairs
        // backed by guest memory.
        results[0] = .{ .list = try lowerFieldEntriesList(ci, f.entries.items) };
    }

    /// `[method]fields.get(borrow<fields>, field-name)
    ///   -> list<field-value>`.
    fn httpFieldsGet(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const f = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        };

        // Read name from arg
        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        });

        // `get` on an invalid name returns an empty list — no error
        // (per `test_invalid_field_name` in `http-fields.rs`, #538).
        if (!isValidFieldName(name)) {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        }

        // Fast path: empty entries — return empty list without
        // allocating a lowercase buffer (#552 hot-path budget).
        if (f.entries.items.len == 0) {
            results[0] = .{ .list = .{ .ptr = 0, .len = 0 } };
            return;
        }

        // ASCII case-insensitive compare against each (already-
        // lowercase) entry, avoiding a per-call lowercase allocation
        // for the input name. Collect matching values into a temporary
        // slice so we can hand it to the byte-list-of-byte-lists
        // lowerer in one shot.
        var matches: std.ArrayListUnmanaged([]const u8) = .empty;
        defer matches.deinit(self.allocator);
        for (f.entries.items) |e| {
            if (asciiEqualIgnoreCase(e.name, name)) {
                try matches.append(self.allocator, e.value);
            }
        }
        results[0] = .{ .list = try lowerByteListList(ci, matches.items) };
    }

    /// `[method]fields.has(borrow<fields>, field-name) -> bool`.
    fn httpFieldsHas(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const f = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .bool = false };
            return;
        };

        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = .{ .bool = false };
            return;
        });

        // `has` on an invalid name returns false (no error).
        if (!isValidFieldName(name)) {
            results[0] = .{ .bool = false };
            return;
        }

        // Fast paths: empty entry list (the http-fields fixture
        // sweeps 1024 codepoints through a fresh `Fields::new()` so
        // most calls land here) — and ASCII case-insensitive compare
        // against each (already-lowercase) stored entry, both
        // avoiding the per-call lowercase-buffer allocation (#552).
        if (f.entries.items.len == 0) {
            results[0] = .{ .bool = false };
            return;
        }
        for (f.entries.items) |e| {
            if (asciiEqualIgnoreCase(e.name, name)) {
                results[0] = .{ .bool = true };
                return;
            }
        }
        results[0] = .{ .bool = false };
    }

    /// `[method]fields.append(borrow<fields>, field-name, field-value)
    ///   -> result<_, header-error>`.
    fn httpFieldsAppend(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const f = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        if (f.immutable) {
            results[0] = try httpHeaderErr(allocator, .immutable);
            return;
        }

        // Lift name+value views first so we can validate before
        // committing any allocations (#538).
        const name_view: ?[]const u8 = extractArgBytes(ci, args[1]);
        const value_view: ?[]const u8 = extractArgBytes(ci, args[2]);
        const name_alloc = if (name_view == null)
            try extractArgBytesAlloc(self.allocator, ci, args[1])
        else
            null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const value_alloc = if (value_view == null)
            try extractArgBytesAlloc(self.allocator, ci, args[2])
        else
            null;
        defer if (value_alloc) |v| self.allocator.free(v);
        const name = name_view orelse (name_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });
        const value = value_view orelse (value_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });

        if (!isValidFieldName(name) or !isValidFieldValue(value)) {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        }

        const lower_name = try lowercaseFieldName(self.allocator, name);
        errdefer self.allocator.free(lower_name);
        const val_copy = try self.allocator.dupe(u8, value);
        errdefer self.allocator.free(val_copy);

        try f.entries.append(self.allocator, .{ .name = lower_name, .value = val_copy });
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `[method]fields.set(borrow<fields>, field-name, list<field-value>)
    ///   -> result<_, header-error>`.
    fn httpFieldsSet(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 3 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const f = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        if (f.immutable) {
            results[0] = try httpHeaderErr(allocator, .immutable);
            return;
        }

        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });

        if (!isValidFieldName(name)) {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        }

        // Add new entries from the list of values: canonical
        // `list<list<u8>>` is laid out in guest memory as
        // `n × (u32 ptr, u32 len)` pairs (issue #402).
        const vals_pl = switch (args[2]) {
            .list => |pl| pl,
            else => {
                results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
                return;
            },
        };

        // Validate ALL values before committing any mutation — `set`
        // is atomic per the WIT semantics. We pre-scan values to catch
        // an invalid one without partially clobbering `f.entries`.
        if (vals_pl.len > 0) {
            const mem_for_scan = ci.canonicalMemory() orelse {
                results[0] = try httpHeaderErr(allocator, .invalid_syntax);
                return;
            };
            const stride0: u32 = 8;
            const total0 = std.math.mul(u32, vals_pl.len, stride0) catch return error.InvalidArgs;
            const list_end0 = std.math.add(u32, vals_pl.ptr, total0) catch return error.InvalidArgs;
            if (list_end0 > mem_for_scan.data.len) return error.OutOfBoundsMemory;
            var sc: u32 = 0;
            while (sc < vals_pl.len) : (sc += 1) {
                const off = vals_pl.ptr + sc * stride0;
                const inner_ptr = std.mem.readInt(u32, mem_for_scan.data[off..][0..4], .little);
                const inner_len = std.mem.readInt(u32, mem_for_scan.data[off + 4 ..][0..4], .little);
                const inner_bytes: []const u8 = if (inner_len == 0) "" else blk: {
                    const end = std.math.add(u32, inner_ptr, inner_len) catch return error.OutOfBoundsMemory;
                    if (end > mem_for_scan.data.len) return error.OutOfBoundsMemory;
                    break :blk mem_for_scan.data[inner_ptr..end];
                };
                if (!isValidFieldValue(inner_bytes)) {
                    results[0] = try httpHeaderErr(allocator, .invalid_syntax);
                    return;
                }
            }
        }

        // Validation succeeded — remove existing entries with this
        // name. Skip the remove walk if the entry list is empty
        // (#552 hot-path budget).
        if (f.entries.items.len > 0) {
            httpFieldsRemoveByNameInsensitive(f, self.allocator, name);
        }

        if (vals_pl.len == 0) {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        }
        const mem = ci.canonicalMemory() orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        const stride: u32 = 8;
        var i: u32 = 0;
        while (i < vals_pl.len) : (i += 1) {
            const off = vals_pl.ptr + i * stride;
            const inner_ptr = std.mem.readInt(u32, mem.data[off..][0..4], .little);
            const inner_len = std.mem.readInt(u32, mem.data[off + 4 ..][0..4], .little);
            const inner_bytes: []const u8 = if (inner_len == 0)
                ""
            else blk: {
                const end = std.math.add(u32, inner_ptr, inner_len) catch return error.OutOfBoundsMemory;
                if (end > mem.data.len) return error.OutOfBoundsMemory;
                break :blk mem.data[inner_ptr..end];
            };

            const lower_name = try lowercaseFieldName(self.allocator, name);
            errdefer self.allocator.free(lower_name);
            const val_copy = try self.allocator.dupe(u8, inner_bytes);
            try f.entries.append(self.allocator, .{ .name = lower_name, .value = val_copy });
        }
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// `[method]fields.delete(borrow<fields>, field-name)
    ///   -> result<_, header-error>`.
    fn httpFieldsDelete(
        ctx_opaque: ?*anyopaque,
        ci: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        allocator: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len < 2 or results.len == 0) return error.InvalidArgs;

        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        const f = self.lookupHttpFields(handle) orelse {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        };
        if (f.immutable) {
            results[0] = try httpHeaderErr(allocator, .immutable);
            return;
        }

        const name_bytes: ?[]const u8 = extractArgBytes(ci, args[1]);
        const name_alloc = if (name_bytes == null) try extractArgBytesAlloc(self.allocator, ci, args[1]) else null;
        defer if (name_alloc) |n| self.allocator.free(n);
        const name = name_bytes orelse (name_alloc orelse {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        });

        if (!isValidFieldName(name)) {
            results[0] = try httpHeaderErr(allocator, .invalid_syntax);
            return;
        }

        // Fast path: empty entries — nothing to remove, no need to
        // build a lowercase buffer (#552 hot-path budget).
        if (f.entries.items.len == 0) {
            results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
            return;
        }

        httpFieldsRemoveByNameInsensitive(f, self.allocator, name);
        results[0] = .{ .result_val = .{ .is_ok = true, .payload = null } };
    }

    /// Remove all entries whose (lowercase) name ASCII-case-matches
    /// `query`. Avoids the per-call lowercase allocation that
    /// `httpFieldsRemoveByName` would require (#552).
    fn httpFieldsRemoveByNameInsensitive(f: *HttpFields, alloc: Allocator, query: []const u8) void {
        var i: usize = 0;
        while (i < f.entries.items.len) {
            if (asciiEqualIgnoreCase(f.entries.items[i].name, query)) {
                alloc.free(f.entries.items[i].name);
                alloc.free(f.entries.items[i].value);
                _ = f.entries.swapRemove(i);
            } else {
                i += 1;
            }
        }
    }

    /// Remove all entries with the given name from an HttpFields.
    /// `name` is expected to be lowercased by the caller — entries
    /// in the table are always lowercase (#538).
    fn httpFieldsRemoveByName(f: *HttpFields, alloc: Allocator, name: []const u8) void {
        var i: usize = 0;
        while (i < f.entries.items.len) {
            if (std.mem.eql(u8, f.entries.items[i].name, name)) {
                alloc.free(f.entries.items[i].name);
                alloc.free(f.entries.items[i].value);
                _ = f.entries.swapRemove(i);
            } else {
                i += 1;
            }
        }
    }

    /// `[method]fields.clone(borrow<fields>) -> own<fields>`.
    fn httpFieldsClone(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        results: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0 or results.len == 0) return error.InvalidArgs;
        const src_handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };

        const f = try self.allocator.create(HttpFields);
        f.* = .{};
        errdefer {
            f.deinit(self.allocator);
            self.allocator.destroy(f);
        }

        // Deep-copy the source's entries — clone returns a mutable
        // owned `fields` that subsequent mutations on the original
        // must not affect (and vice versa). #538: prior implementation
        // returned an empty `fields`, dropping the entries that the
        // http-fields wasi-p3-testsuite fixture round-trips through
        // `Fields::from_list(...).clone()`.
        if (self.lookupHttpFields(src_handle)) |src| {
            if (src.entries.items.len > 0) {
                const copied = try self.allocator.alloc(HttpFieldEntry, src.entries.items.len);
                var filled: usize = 0;
                errdefer {
                    for (copied[0..filled]) |e| {
                        self.allocator.free(e.name);
                        self.allocator.free(e.value);
                    }
                    self.allocator.free(copied);
                }
                while (filled < src.entries.items.len) : (filled += 1) {
                    const e = src.entries.items[filled];
                    const name_copy = try self.allocator.dupe(u8, e.name);
                    errdefer self.allocator.free(name_copy);
                    const value_copy = try self.allocator.dupe(u8, e.value);
                    copied[filled] = .{ .name = name_copy, .value = value_copy };
                }
                f.entries = .{ .items = copied, .capacity = copied.len };
            }
        }

        const h = try self.pushHttpFields(f);
        results[0] = .{ .handle = h };
    }

    /// `[resource-drop]fields`.
    fn httpFieldsDrop(
        ctx_opaque: ?*anyopaque,
        _: *ComponentInstance,
        args: []const InterfaceValue,
        _: []InterfaceValue,
        _: Allocator,
    ) anyerror!void {
        const self: *WasiCliAdapter = @ptrCast(@alignCast(ctx_opaque.?));
        if (args.len == 0) return error.InvalidArgs;
        const handle = switch (args[0]) {
            .handle => |h| h,
            else => return error.InvalidArgs,
        };
        if (handle >= self.http_fields_table.items.len) return;
        if (self.http_fields_table.items[handle]) |f| {
            f.deinit(self.allocator);
            self.allocator.destroy(f);
            self.http_fields_table.items[handle] = null;
        }
    }

