    ) !void {
        try self.http_handler_p3_iface.members.put(self.allocator, "handle", .{
            .func = .{ .context = self, .call = &httpHandlerHandleP3 },
        });
        try providers.put(self.allocator, iface_name, .{
            .host_instance = &self.http_handler_p3_iface,
        });
