test "filesystem: open-at sandbox rejects .. and absolute paths (#145)" {
    const testing = std.testing;

    // Absolute paths map to `not-permitted` per the 0.3 conformance
    // fixtures (filesystem-open-errors, filesystem-stat,
    // filesystem-mkdir-rmdir): leading `/` is a sandbox escape, not a
    // POSIX-EACCES situation. (#571 follow-up to #564.)
    try testing.expectEqual(@as(?FsErrorCode, .not_permitted), WasiCliAdapter.validateSandboxPath("/etc/passwd"));
    try testing.expectEqual(@as(?FsErrorCode, .not_permitted), WasiCliAdapter.validateSandboxPath("/"));
    // `..` components map to `not-permitted` per the 0.3 conformance
    // fixture's expectation (filesystem-dotdot). Windows-style escapes
    // still map to `access`. (#564.)
    try testing.expectEqual(@as(?FsErrorCode, .not_permitted), WasiCliAdapter.validateSandboxPath("../escape"));
    try testing.expectEqual(@as(?FsErrorCode, .not_permitted), WasiCliAdapter.validateSandboxPath("a/../b"));
    try testing.expectEqual(@as(?FsErrorCode, .access), WasiCliAdapter.validateSandboxPath("a\\b"));
    try testing.expectEqual(@as(?FsErrorCode, .access), WasiCliAdapter.validateSandboxPath("C:foo"));
    try testing.expectEqual(@as(?FsErrorCode, null), WasiCliAdapter.validateSandboxPath("a/b/c.txt"));
    try testing.expectEqual(@as(?FsErrorCode, null), WasiCliAdapter.validateSandboxPath(""));
    try testing.expectEqual(@as(?FsErrorCode, null), WasiCliAdapter.validateSandboxPath("..foo"));
}

test "filesystem: ioTimestampToDatetime clamps + splits ns (#177)" {
    const testing = std.testing;

    const zero = ioTimestampToDatetime(.{ .nanoseconds = 0 });
    try testing.expectEqual(@as(u64, 0), zero.seconds);
    try testing.expectEqual(@as(u32, 0), zero.nanoseconds);

    // Negative epoch clamps to (0, 0).
    const neg = ioTimestampToDatetime(.{ .nanoseconds = -42 });
    try testing.expectEqual(@as(u64, 0), neg.seconds);
    try testing.expectEqual(@as(u32, 0), neg.nanoseconds);

    // 1.5 seconds.
    const one_half = ioTimestampToDatetime(.{ .nanoseconds = 1_500_000_000 });
    try testing.expectEqual(@as(u64, 1), one_half.seconds);
    try testing.expectEqual(@as(u32, 500_000_000), one_half.nanoseconds);
}

test "filesystem: liftNewTimestamp covers all three variants (#177)" {
    const testing = std.testing;

    const unchanged = try liftNewTimestamp(.{ .variant_val = .{ .discriminant = 0, .payload = null } });
    try testing.expect(unchanged == .unchanged);

    const now_v = try liftNewTimestamp(.{ .variant_val = .{ .discriminant = 1, .payload = null } });
    try testing.expect(now_v == .now);

    var dt_fields = [_]InterfaceValue{
        .{ .u64 = 1_700_000_000 },
        .{ .u32 = 500_000_000 },
    };
    const dt_iv = InterfaceValue{ .record_val = &dt_fields };
    const new_v = try liftNewTimestamp(.{ .variant_val = .{ .discriminant = 2, .payload = &dt_iv } });
    try testing.expect(new_v == .new);
    try testing.expectEqual(@as(i96, 1_700_000_000 * 1_000_000_000 + 500_000_000), new_v.new.nanoseconds);

    // Bad discriminant rejects.
    try testing.expectError(error.InvalidArgs, liftNewTimestamp(.{ .variant_val = .{ .discriminant = 7, .payload = null } }));
}

test "filesystem #571: liftNewTimestamp accepts s64-encoded seconds (system-clock.instant)" {
    // The wit-bindgen-emitted component encodes
    // `wasi:clocks/system-clock.instant.seconds` as `s64` (signed —
    // pre-epoch instants are representable). The 0.2 `wall-clock.datetime`
    // shape used `u64`. liftNewTimestamp must accept either tag so the
    // wasi-testsuite `filesystem-stat` fixture's `set-times-at` call
    // lifts correctly regardless of which wit-bindgen vintage the
    // component was built with.
    const testing = std.testing;

    var dt_fields_s64 = [_]InterfaceValue{
        .{ .s64 = 42 },
        .{ .u32 = 0 },
    };
    const dt_iv_s64 = InterfaceValue{ .record_val = &dt_fields_s64 };
    const ts_s64 = try liftNewTimestamp(.{ .variant_val = .{ .discriminant = 2, .payload = &dt_iv_s64 } });
    try testing.expect(ts_s64 == .new);
    try testing.expectEqual(@as(i96, 42 * 1_000_000_000), ts_s64.new.nanoseconds);

    // Negative pre-epoch seconds round-trip correctly through i96.
    var dt_fields_neg = [_]InterfaceValue{
        .{ .s64 = -3 },
        .{ .u32 = 250_000_000 },
    };
    const dt_iv_neg = InterfaceValue{ .record_val = &dt_fields_neg };
    const ts_neg = try liftNewTimestamp(.{ .variant_val = .{ .discriminant = 2, .payload = &dt_iv_neg } });
    try testing.expect(ts_neg == .new);
    try testing.expectEqual(@as(i96, -3 * 1_000_000_000 + 250_000_000), ts_neg.new.nanoseconds);

    // u64 seconds still work (back-compat with 0.2 wall-clock.datetime).
    var dt_fields_u64 = [_]InterfaceValue{
        .{ .u64 = 99 },
        .{ .u32 = 0 },
    };
    const dt_iv_u64 = InterfaceValue{ .record_val = &dt_fields_u64 };
    const ts_u64 = try liftNewTimestamp(.{ .variant_val = .{ .discriminant = 2, .payload = &dt_iv_u64 } });
    try testing.expect(ts_u64 == .new);
    try testing.expectEqual(@as(i96, 99 * 1_000_000_000), ts_u64.new.nanoseconds);
}

test "filesystem: stat returns mtime/ctime as option::some (#177)" {
