    try testing.expect(std.mem.indexOf(u8, bytes, "Injected") == null);
}

test "http: discovers versioned incoming-handler export (#201)" {
    const testing = std.testing;

    const core_wasm = [_]u8{
        0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
