            }, &stream_results, a);
            defer stream_results[0].deinit(a);
            const out_handle = stream_results[0].result_val.payload.?.tuple_val[1].handle;
            // check-send
            {
                const cs_args = [_]InterfaceValue{.{ .handle = out_handle }};
