    // Empty port rejected.
    try testing.expect(!try Caller.callSetSome(&adapter, &ci, req_handle, "example.com:"));
    // Empty authority rejected.
    try testing.expect(!try Caller.callSetSome(&adapter, &ci, req_handle, ""));
}

test "sockets (#520 wave 2): socketCodeToP3Disc maps internal enum to WIT 0.3 variant discs" {
    const testing = std.testing;
    // WIT 0.3 `wasi:sockets/types.error-code` variant ordering:
    // 0=access-denied, 1=not-supported, 2=invalid-argument, 3=out-of-memory,
    // 4=timeout, 5=invalid-state, 6=address-not-bindable, 7=address-in-use,
    // 8=remote-unreachable, 9=connection-refused, 10=connection-broken,
    // 11=connection-reset, 12=connection-aborted, 13=datagram-too-large,
    // 14=other(option<string>). Our internal `SocketErrorCode` enum
    // matches the 0.2 ENUM ordering (`unknown=0`, access_denied=1, …)
    // which is off-by-one from 0.3 — that mismatch is what
    // `socketCodeToP3Disc` translates at the host boundary.
    try testing.expectEqual(@as(u32, 0), WasiCliAdapter.socketCodeToP3Disc(.access_denied));
    try testing.expectEqual(@as(u32, 1), WasiCliAdapter.socketCodeToP3Disc(.not_supported));
    try testing.expectEqual(@as(u32, 2), WasiCliAdapter.socketCodeToP3Disc(.invalid_argument));
    try testing.expectEqual(@as(u32, 3), WasiCliAdapter.socketCodeToP3Disc(.out_of_memory));
    try testing.expectEqual(@as(u32, 5), WasiCliAdapter.socketCodeToP3Disc(.invalid_state));
    try testing.expectEqual(@as(u32, 6), WasiCliAdapter.socketCodeToP3Disc(.address_not_bindable));
    try testing.expectEqual(@as(u32, 7), WasiCliAdapter.socketCodeToP3Disc(.address_in_use));
    // 0.2-only cases (no 0.3 equivalent) fall back to `other(none)` = 14.
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.unknown));
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.concurrency_conflict));
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.not_in_progress));
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.would_block));
    try testing.expectEqual(@as(u32, 14), WasiCliAdapter.socketCodeToP3Disc(.new_socket_limit));
}

test "sockets #575/#583 A6: bindAndGetsockname SO_REUSEADDR lets immediate rebind to TIME_WAIT port succeed" {
    const testing = std.testing;
    const io = std.Io.Threaded.global_single_threaded.io();

    // First bind: wildcard:0 — kernel assigns an ephemeral port.
    const wildcard: std.Io.net.IpAddress = .{ .ip4 = .{
        .bytes = [4]u8{ 127, 0, 0, 1 },
        .port = 0,
    } };
    const first = try bindAndGetsockname(wildcard, .stream, .tcp);
    const assigned_port = switch (first.address) {
        .ip4 => |v4| v4.port,
        .ip6 => |v6| v6.port,
    };
    try testing.expect(assigned_port != 0);

    // Close the first socket — the kernel may leave the 4-tuple in
    // TIME_WAIT. Without SO_REUSEADDR on the new socket below the
    // rebind would fail with `error.AddressInUse` for that window.
    // With the setsockopt added in #575 (POSIX) / #583 A6 (Windows)
    // it succeeds on every supported platform.
    first.close(io);

    // Second bind: same port, fresh socket. With SO_REUSEADDR set by
    // `bindAndGetsockname` this must succeed even if the first tuple
    // is still in TIME_WAIT — the symptom that broke
    // `sockets-tcp-bind::test_reuseaddr` before #575 on POSIX (and
    // would break it on MinGW CI once Windows runs the p3 suite,
    // absent #583 A6).
    const rebind_addr: std.Io.net.IpAddress = .{ .ip4 = .{
        .bytes = [4]u8{ 127, 0, 0, 1 },
        .port = assigned_port,
    } };
    const second = try bindAndGetsockname(rebind_addr, .stream, .tcp);
    defer second.close(io);

    const got_port = switch (second.address) {
        .ip4 => |v4| v4.port,
        .ip6 => |v6| v6.port,
    };
    try testing.expectEqual(assigned_port, got_port);
}

test "sockets #583 A6: bindAndGetsockname wildcard:0 round-trip is portable across POSIX/Windows" {
    // Smoke-test the same `bindAndGetsockname` entry point on every
    // platform — on POSIX it exercises the raw-syscall path, on
    // Windows it exercises the ws2_32 path added by #583 A6. Both
    // arms must:
    //   1. Open a socket and bind to 127.0.0.1:0 successfully.
    //   2. Receive a non-zero kernel-assigned ephemeral port via
    //      getsockname.
    //   3. Allow an immediate rebind on the resolved port using a
    //      fresh socket (SO_REUSEADDR coverage — same expectation as
    //      `sockets-tcp-bind::test_reuseaddr`).
    //   4. Repeat the round trip for UDP/.dgram so the non-stream
    //      branch of the `mode` switch is hit too.
    const testing = std.testing;
    const io = std.Io.Threaded.global_single_threaded.io();

    inline for (.{
        .{ std.Io.net.Socket.Mode.stream, std.Io.net.Protocol.tcp },
        .{ std.Io.net.Socket.Mode.dgram, std.Io.net.Protocol.udp },
    }) |pair| {
        const mode = pair[0];
        const proto = pair[1];

        const wildcard: std.Io.net.IpAddress = .{ .ip4 = .{
            .bytes = [4]u8{ 127, 0, 0, 1 },
            .port = 0,
        } };
        const first = try bindAndGetsockname(wildcard, mode, proto);
        const assigned_port = switch (first.address) {
            .ip4 => |v4| v4.port,
            .ip6 => |v6| v6.port,
        };
        try testing.expect(assigned_port != 0);
        first.close(io);

        const rebind_addr: std.Io.net.IpAddress = .{ .ip4 = .{
            .bytes = [4]u8{ 127, 0, 0, 1 },
            .port = assigned_port,
        } };
        const second = try bindAndGetsockname(rebind_addr, mode, proto);
        defer second.close(io);
        const got_port = switch (second.address) {
            .ip4 => |v4| v4.port,
            .ip6 => |v6| v6.port,
        };
        try testing.expectEqual(assigned_port, got_port);
    }
}

test "main (#520 wave 2): runComponent applies --map-dir flags via addPreopen" {
    const testing = std.testing;

    // Spin up an adapter the same way `runComponent` does and verify
    // that `addPreopen` ends up in `fs_preopens`. The CLI plumbing
    // path itself (parse `--map-dir`, call `cwd_dir.openDir`, hand
    // off to `addPreopen`) is exercised end-to-end by the
    // wasi-p3-testsuite filesystem fixtures once the async-future
    // lower fix lands; this unit test pins the contract.
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    var tmp = testing.tmpDir(.{});
    defer tmp.cleanup();

    const handle = try adapter.addPreopen("fs-tests.dir", tmp.dir);
    // Replace the slot with null so adapter.deinit doesn't double-close
    // (tmp.cleanup() owns the dir handle).
    adapter.fs_descriptor_table.items[handle] = null;

    try testing.expectEqual(@as(usize, 1), adapter.fs_preopens.items.len);
    try testing.expectEqualStrings("fs-tests.dir", adapter.fs_preopens.items[0].name);
    // `dir_handle` is the 0-based slot index; the wire encoding
    // (`slot + 1`) is applied by `fsGetDirectories` via
    // `abi.encodeResourceWireAbi` when lowering to guest memory.
    try testing.expectEqual(handle, adapter.fs_preopens.items[0].dir_handle);
}

// ── #562: wasi:http@0.3 host-handle wire offset for `outgoing-response`
// and friends. Verifies that every http host-instance table reserves
// slot 0 as a null sentinel, so the canon-ABI `decodeResourceWire(wire)`
// mapping of wire `0` → host slot `0` lands on a null entry (rather
// than silently returning the first allocated resource). PR #560
// applied the same pattern to sockets + filesystem; this PR extends
// the convention to http (`http_outgoing_responses`,
// `http_outgoing_requests`, `http_outgoing_bodies`,
// `http_incoming_responses`, `http_incoming_requests`,
// `http_incoming_bodies`, `http_fields`, `http_future_trailers`).

test "http (#562): outgoing-response push reserves slot 0 + wire round-trips through encodeResourceWire" {
    const testing = std.testing;
    const executor = @import("executor.zig");

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // Push a fresh `OutgoingResponse`. The headers_handle field is
    // populated from a real `pushHttpFields` slot to keep the
    // adapter's deinit clean.
    const fields = try adapter.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);
    try testing.expect(fh >= 1); // slot 0 reserved

    const resp = try adapter.allocator.create(OutgoingResponse);
    resp.* = .{ .status = 200, .headers_handle = fh };
    const slot = try adapter.pushOutgoingResponse(resp);

    // Slot must be 1+ (slot 0 is the null sentinel).
    try testing.expect(slot >= 1);
    try testing.expectEqual(@as(?*OutgoingResponse, null), adapter.http_outgoing_responses.items[0]);
    try testing.expectEqual(resp, adapter.http_outgoing_responses.items[slot].?);

    // wire = slot + 1 (`encodeResourceWire`). Non-zero, so wit-bindgen
    // Rust's `Resource<OutgoingResponse>::from_handle(wire)` will not
    // trip the `handle != 0` debug assertion.
    const wire = executor.encodeResourceWire(slot);
    try testing.expect(wire >= 2);
    try testing.expectEqual(slot + 1, wire);

    // Round-trip back to slot via `decodeResourceWire`.
    const decoded = executor.decodeResourceWire(wire);
    try testing.expectEqual(slot, decoded);
    try testing.expectEqual(resp, adapter.lookupOutgoingResponse(decoded).?);
}

test "http (#562): http_fields_table push reserves slot 0 + wire round-trips through encodeResourceWire" {
    const testing = std.testing;
    const executor = @import("executor.zig");

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    const fields = try adapter.allocator.create(HttpFields);
    fields.* = .{};
    const slot = try adapter.pushHttpFields(fields);

    // Slot 0 stays null; first allocation lands at slot 1.
    try testing.expect(slot >= 1);
    try testing.expectEqual(@as(?*HttpFields, null), adapter.http_fields_table.items[0]);
    try testing.expectEqual(fields, adapter.http_fields_table.items[slot].?);

    // Encode → decode → lookup must round-trip to the same resource.
    const wire = executor.encodeResourceWire(slot);
    try testing.expect(wire >= 2);
    const decoded = executor.decodeResourceWire(wire);
    try testing.expectEqual(slot, decoded);
    try testing.expectEqual(fields, adapter.lookupHttpFields(decoded).?);
}

test "http (#562): every http host table reserves slot 0 — wire=0 lookup returns null, not the first allocation" {
    const testing = std.testing;
    const executor = @import("executor.zig");

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // Allocate one resource into every http host table so that slot 1
    // is real. `decodeResourceWire(0) == 0` (the canon-ABI lifts a
    // wire-zero handle to host slot 0); slot 0 of every http table
    // must be null so the corresponding `lookup*` returns null
    // instead of silently surfacing the first allocation.
    const fields = try adapter.allocator.create(HttpFields);
    fields.* = .{};
    const fh = try adapter.pushHttpFields(fields);
    try testing.expect(fh >= 1);

    const out_req = try adapter.allocator.create(OutgoingRequest);
    out_req.* = .{ .headers_handle = fh };
    const out_req_slot = try adapter.pushOutgoingRequest(out_req);
    try testing.expect(out_req_slot >= 1);

    const in_req = try adapter.allocator.create(IncomingRequest);
    in_req.* = .{};
    const in_req_slot = try adapter.pushIncomingRequest(in_req);
    try testing.expect(in_req_slot >= 1);

    const out_resp = try adapter.allocator.create(OutgoingResponse);
    out_resp.* = .{ .status = 200, .headers_handle = fh };
    const out_resp_slot = try adapter.pushOutgoingResponse(out_resp);
    try testing.expect(out_resp_slot >= 1);

    const in_resp = try adapter.allocator.create(IncomingResponse);
    in_resp.* = .{};
    const in_resp_slot = try adapter.pushIncomingResponse(in_resp);
    try testing.expect(in_resp_slot >= 1);

    const out_body = try adapter.allocator.create(OutgoingBody);
    out_body.* = .{};
    const out_body_slot = try adapter.pushOutgoingBody(out_body);
    try testing.expect(out_body_slot >= 1);

    const in_body = try adapter.allocator.create(IncomingBody);
    in_body.* = .{};
    const in_body_slot = try adapter.pushIncomingBody(in_body);
    try testing.expect(in_body_slot >= 1);

    const ft = try adapter.allocator.create(FutureTrailers);
    ft.* = .{};
    const ft_slot = try adapter.pushFutureTrailers(ft);
    try testing.expect(ft_slot >= 1);

    // For each of the 8 tables listed in #562, `decodeResourceWire(0)`
    // returns host slot `0`, and `lookup*(0)` must return null so the
    // host doesn't silently target the first real allocation.
    const wire_zero_slot = executor.decodeResourceWire(0);
    try testing.expectEqual(@as(u32, 0), wire_zero_slot);
    try testing.expectEqual(@as(?*HttpFields, null), adapter.lookupHttpFields(wire_zero_slot));
    try testing.expectEqual(@as(?*OutgoingRequest, null), adapter.lookupOutgoingRequest(wire_zero_slot));
    try testing.expectEqual(@as(?*IncomingRequest, null), adapter.lookupIncomingRequest(wire_zero_slot));
    try testing.expectEqual(@as(?*OutgoingResponse, null), adapter.lookupOutgoingResponse(wire_zero_slot));
    try testing.expectEqual(@as(?*IncomingResponse, null), adapter.lookupIncomingResponse(wire_zero_slot));
    try testing.expectEqual(@as(?*OutgoingBody, null), adapter.lookupOutgoingBody(wire_zero_slot));
    try testing.expectEqual(@as(?*IncomingBody, null), adapter.lookupIncomingBody(wire_zero_slot));
    // `lookupFutureTrailers` doesn't exist as a helper (`http_future_trailers`
    // is accessed inline via `items[handle]`), but the table itself must
    // still reserve slot 0:
    try testing.expectEqual(@as(?*FutureTrailers, null), adapter.http_future_trailers.items[0]);
}

test "http (#562): slot-reuse stays within the 1-based range after a drop" {
    const testing = std.testing;

    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // Three pushes land at slots 1, 2, 3 (slot 0 reserved).
    const o1 = try adapter.allocator.create(OutgoingResponse);
    o1.* = .{ .status = 200, .headers_handle = 0 };
    const s1 = try adapter.pushOutgoingResponse(o1);
    const o2 = try adapter.allocator.create(OutgoingResponse);
    o2.* = .{ .status = 200, .headers_handle = 0 };
    const s2 = try adapter.pushOutgoingResponse(o2);
    const o3 = try adapter.allocator.create(OutgoingResponse);
    o3.* = .{ .status = 200, .headers_handle = 0 };
    const s3 = try adapter.pushOutgoingResponse(o3);
    try testing.expectEqual(@as(u32, 1), s1);
    try testing.expectEqual(@as(u32, 2), s2);
    try testing.expectEqual(@as(u32, 3), s3);

    // Free slot 2; a subsequent push must reuse slot 2 (not slot 0).
    adapter.allocator.destroy(o2);
    adapter.http_outgoing_responses.items[s2] = null;

    const o4 = try adapter.allocator.create(OutgoingResponse);
    o4.* = .{ .status = 201, .headers_handle = 0 };
    const s4 = try adapter.pushOutgoingResponse(o4);
    try testing.expectEqual(@as(u32, 2), s4);
    try testing.expectEqual(@as(?*OutgoingResponse, null), adapter.http_outgoing_responses.items[0]);
}

// ───────────────────────────────────────────────────────────────────
// wasi:http@0.3.0 http-service end-to-end (#570) unit tests
// ───────────────────────────────────────────────────────────────────

test "wasi:http@0.3 (#570): createIncomingRequestP3FromHttpBytes parses GET line + headers + empty body" {
    // Synthetic HTTP/1.1 request → `HttpRequestP3` round-trip. Mirrors
    // the wasi-testsuite `http-service` driver path: an accepted TCP
    // socket's bytes get parsed into a P3 request resource without
    // needing the dispatcher to actually invoke a guest export.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const request_bytes =
        "GET /hello?x=1 HTTP/1.1\r\n" ++
        "Host: example.com\r\n" ++
        "User-Agent: wamr-test\r\n" ++
        "Content-Length: 0\r\n" ++
        "\r\n";
    const req_handle = try adapter.createIncomingRequestP3FromHttpBytes(&ci, request_bytes);
    try testing.expect(req_handle > 0); // slot 0 is reserved (#562)

    const r = adapter.lookupHttpRequestP3(req_handle) orelse return error.TestFailed;
    // GET → method discriminant 0.
    try testing.expectEqual(@as(u32, 0), r.method_disc);
    try testing.expectEqualStrings("/hello?x=1", r.path_with_query.?);
    try testing.expectEqualStrings("example.com", r.authority.?);
    // Default scheme is http (#570 — `splitHttpTarget` returns 0
    // when no `http(s)://` prefix is present in the origin-form target).
    try testing.expectEqual(@as(?u32, 0), r.scheme_disc);

    // Headers are interned as an immutable HttpFields. The two
    // user-supplied headers + the `host` echo land here.
    const fields = adapter.lookupHttpFields(r.headers_handle) orelse return error.TestFailed;
    try testing.expect(fields.immutable);
    try testing.expect(fields.entries.items.len >= 3);

    // Body stream<u8> is pre-EOF for a zero-length request — the guest
    // can read once and immediately observe write-closed semantics.
    const body_handle = r.body_stream_handle orelse return error.TestFailed;
    const body_stream = ci.streams.getPtr(body_handle) orelse return error.TestFailed;
    try testing.expectEqual(@as(usize, 0), body_stream.buffer.items.len);
    try testing.expect(body_stream.write_closed);

    // Trailers + transmission futures must be ready-settled so the
    // guest's `.await` resolves synchronously on the first poll.
    const trailers_fut = ci.futures.getPtr(r.trailers_future_handle) orelse return error.TestFailed;
    try testing.expectEqual(async_mod.Future.State.ready, trailers_fut.state);
    const tx_fut = ci.futures.getPtr(r.transmission_future_handle) orelse return error.TestFailed;
    try testing.expectEqual(async_mod.Future.State.ready, tx_fut.state);
}

test "wasi:http@0.3 (#570): createIncomingRequestP3FromHttpBytes preserves POST body in stream" {
    // POST with `Content-Length: <n>` and an `<n>`-byte body. The body
    // bytes must land in the per-instance `stream<u8>` so the guest's
    // `request.consume-body` rendezvous can hand them back unmodified.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const body_payload = "hello body";
    const request_bytes =
        "POST /submit HTTP/1.1\r\n" ++
        "Host: api.example\r\n" ++
        "Content-Length: 10\r\n" ++
        "\r\n" ++
        body_payload;
    const req_handle = try adapter.createIncomingRequestP3FromHttpBytes(&ci, request_bytes);

    const r = adapter.lookupHttpRequestP3(req_handle) orelse return error.TestFailed;
    // POST → method discriminant 2 (per `httpMethodDiscriminant`).
    try testing.expectEqual(@as(u32, 2), r.method_disc);
    try testing.expectEqualStrings("/submit", r.path_with_query.?);
    const body_stream = ci.streams.getPtr(r.body_stream_handle.?) orelse return error.TestFailed;
    try testing.expectEqualStrings(body_payload, body_stream.buffer.items);
    try testing.expect(body_stream.write_closed);
}

test "wasi:http@0.3 (#570): writeHttpResponseP3FromHandle emits status line + headers + body" {
    // Synthetic `HttpResponseP3` lifted via the same constructor the
    // dispatch path uses. The streaming writer renders it as
    // HTTP/1.1 over a backing in-memory sink so the wasi-testsuite
    // `requests.request(...)` driver receives the expected status +
    // body. Matches the JSON expectations of `http-service.json`:
    // `200 + content-type: text/plain + "hey\n"`.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    // Set up a response with `content-type: text/plain` header and a
    // pre-filled body stream containing "hey\n".
    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const name = try testing.allocator.dupe(u8, "content-type");
    const value = try testing.allocator.dupe(u8, "text/plain");
    try fields.entries.append(testing.allocator, .{ .name = name, .value = value });
    const fields_handle = try adapter.pushHttpFields(fields);

    const body_handle = ci.allocAsyncHandle();
    var body: async_mod.AsyncStream = .{ .elem_type_idx = 0 };
    try body.buffer.appendSlice(testing.allocator, "hey\n");
    body.write_closed = true;
    try ci.streams.put(testing.allocator, body_handle, body);

    // Allocate ready-settled trailers + transmission futures so the
    // writer can reason about their state without driving any
    // additional canon ops.
    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });
    const tx_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, tx_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });

    const resp = try testing.allocator.create(HttpResponseP3);
    resp.* = .{
        .status = 200,
        .headers_handle = fields_handle,
        .body_stream_handle = body_handle,
        .trailers_future_handle = trailers_h,
        .transmission_future_handle = tx_h,
    };
    const resp_handle = try adapter.pushHttpResponseP3(resp);

    // Drive `writeHttpResponseP3FromHandle` into a buffer-backed sink
    // so the test can assert the exact wire format.
    var out = streams.OutputStream.toBuffer();
    defer out.deinit(testing.allocator);

    try adapter.writeHttpResponseP3FromHandle(&out, &ci, resp_handle, false);

    const written = out.getBufferContents();
    // Status-line + standard headers + chunked-framed body. The
    // guest did not set Content-Length, so the writer falls back
    // to Transfer-Encoding: chunked (#583 A5).
    try testing.expect(std.mem.startsWith(u8, written, "HTTP/1.1 200 OK\r\n"));
    try testing.expect(std.mem.indexOf(u8, written, "content-type: text/plain\r\n") != null);
    try testing.expect(std.mem.indexOf(u8, written, "Transfer-Encoding: chunked\r\n") != null);
    try testing.expect(std.mem.indexOf(u8, written, "Connection: close\r\n") != null);
    // One non-zero chunk + the terminating 0-chunk with no trailers.
    try testing.expect(std.mem.indexOf(u8, written, "\r\n4\r\nhey\n\r\n") != null);
    try testing.expect(std.mem.endsWith(u8, written, "0\r\n\r\n"));
}

test "wasi:http@0.3 (#570): writeHttpResponseP3FromHandle handles 404 + empty body" {
    // The `/whatever` arm of `http-service` returns status 404 with an
    // empty body. The writer must emit a `Content-Length: 0` and no
    // body bytes after the header block — the wasi-testsuite driver
    // reads exactly that and validates.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const fields_handle = try adapter.pushHttpFields(fields);

    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });
    const tx_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, tx_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });

    const resp = try testing.allocator.create(HttpResponseP3);
    resp.* = .{
        .status = 404,
        .headers_handle = fields_handle,
        .body_stream_handle = null,
        .trailers_future_handle = trailers_h,
        .transmission_future_handle = tx_h,
    };
    const resp_handle = try adapter.pushHttpResponseP3(resp);

    var out = streams.OutputStream.toBuffer();
    defer out.deinit(testing.allocator);

    try adapter.writeHttpResponseP3FromHandle(&out, &ci, resp_handle, false);

    const written = out.getBufferContents();
    try testing.expect(std.mem.startsWith(u8, written, "HTTP/1.1 404 Not Found\r\n"));
    try testing.expect(std.mem.indexOf(u8, written, "Content-Length: 0\r\n") != null);
    // No body bytes after `\r\n\r\n`.
    try testing.expect(std.mem.endsWith(u8, written, "\r\n\r\n"));
}

test "wasi:http@0.3 (#570): findHttpIncomingHandlerExportNameP3 selects 0.3 over 0.2" {
    // The P3 driver must dispatch through `wasi:http/handler@0.3.x`
    // (unified handler — `wasi:http@0.3.0` collapsed
    // incoming/outgoing). A component exporting only the legacy
    // `wasi:http/incoming-handler@0.2.x` falls through to the sync
    // P2 dispatch path; the P3 finder must therefore return null for
    // 0.2-only exports and the P3 export name (with `/handle`) when
    // a 0.3 export is present.
    const testing = std.testing;

    const core_wasm = [_]u8{
        0x00, 0x61, 0x73, 0x6d, 0x01, 0x00, 0x00, 0x00,
        // type section: () -> ()
        0x01, 0x04, 0x01, 0x60, 0x00, 0x00,
        // function section: 1 fn of type 0
        0x03, 0x02, 0x01, 0x00,
        // export section: "handle" -> func 0
        0x07, 0x0a, 0x01, 0x06, 'h', 'a', 'n', 'd', 'l', 'e', 0x00, 0x00,
        // code section: empty body
        0x0a, 0x04, 0x01, 0x02, 0x00, 0x0b,
    };
    const core_modules = [_]ctypes.CoreModule{.{ .data = &core_wasm }};
    const type_defs = [_]ctypes.TypeDef{
        .{ .func = .{ .params = &.{}, .results = .none } },
    };
    const core_insts = [_]ctypes.CoreInstanceExpr{
        .{ .instantiate = .{ .module_idx = 0, .args = &.{} } },
    };
    const aliases_decl = [_]ctypes.Alias{
        .{ .instance_export = .{
            .sort = .{ .core = .func },
            .instance_idx = 0,
            .name = "handle",
        } },
    };
    const canons = [_]ctypes.Canon{
        .{ .lift = .{ .core_func_idx = 0, .type_idx = 0, .opts = &.{} } },
    };
    const inline_exp = [_]ctypes.InlineExport{
        .{ .name = "handle", .sort_idx = .{ .sort = .func, .idx = 0 } },
    };
    const instances = [_]ctypes.InstanceExpr{
        .{ .exports = &inline_exp },
    };

    // Case 1: component exports `wasi:http/handler@0.3.0` (P3 unified).
    const exports_p3 = [_]ctypes.ExportDecl{
        .{
            .name = "wasi:http/handler@0.3.0-rc-2026-03-15",
            .desc = .{ .instance = 0 },
            .sort_idx = .{ .sort = .instance, .idx = 0 },
        },
    };
    const component_p3 = ctypes.Component{
        .core_modules = &core_modules,
        .core_instances = &core_insts,
        .core_types = &.{},
        .components = &.{},
        .instances = &instances,
        .aliases = &aliases_decl,
        .types = &type_defs,
        .canons = &canons,
        .imports = &.{},
        .exports = &exports_p3,
    };
    const inst_p3 = try instance_mod.instantiate(&component_p3, testing.allocator);
    defer inst_p3.deinit();
    const name_p3 = (try findHttpIncomingHandlerExportNameP3(&component_p3, inst_p3, testing.allocator)) orelse
        return error.TestFailed;
    defer testing.allocator.free(name_p3);
    try testing.expectEqualStrings(
        "wasi:http/handler@0.3.0-rc-2026-03-15/handle",
        name_p3,
    );

    // Case 2: component exports only `wasi:http/incoming-handler@0.2.6` —
    // P3 finder should return null so the dispatcher falls through to
    // the P2 sync path (`serveOneHttpConnection`).
    const exports_p2 = [_]ctypes.ExportDecl{
        .{
            .name = "wasi:http/incoming-handler@0.2.6",
            .desc = .{ .instance = 0 },
            .sort_idx = .{ .sort = .instance, .idx = 0 },
        },
    };
    const component_p2 = ctypes.Component{
        .core_modules = &core_modules,
        .core_instances = &core_insts,
        .core_types = &.{},
        .components = &.{},
        .instances = &instances,
        .aliases = &aliases_decl,
        .types = &type_defs,
        .canons = &canons,
        .imports = &.{},
        .exports = &exports_p2,
    };
    const inst_p2 = try instance_mod.instantiate(&component_p2, testing.allocator);
    defer inst_p2.deinit();
    const name_p2 = try findHttpIncomingHandlerExportNameP3(&component_p2, inst_p2, testing.allocator);
    try testing.expect(name_p2 == null);
}

test "wasi:http@0.3 (#570): cleanupHttpResourcesAllVersions clears P3 + P2 handle tables" {
    // The per-connection cleanup hook must reset every http resource
    // table the dispatch may have touched so the next accepted socket
    // sees a fresh 1-based handle namespace (#562). This guards
    // against handle-reuse confusion between requests served on the
    // same listening socket.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();

    // Populate one entry in each P3 table (1-based — slot 0 reserved).
    const r = try testing.allocator.create(HttpRequestP3);
    r.* = .{};
    const rh = try adapter.pushHttpRequestP3(r);
    try testing.expectEqual(@as(u32, 1), rh);

    const resp = try testing.allocator.create(HttpResponseP3);
    resp.* = .{};
    const resp_h = try adapter.pushHttpResponseP3(resp);
    try testing.expectEqual(@as(u32, 1), resp_h);

    adapter.cleanupHttpResourcesAllVersions();

    // After cleanup, slot 1 is null (entry freed) and slot 0 is still
    // the reserved null sentinel.
    try testing.expectEqual(@as(?*HttpRequestP3, null), adapter.http_requests_p3.items[0]);
    try testing.expectEqual(@as(?*HttpRequestP3, null), adapter.http_requests_p3.items[1]);
    try testing.expectEqual(@as(?*HttpResponseP3, null), adapter.http_responses_p3.items[0]);
    try testing.expectEqual(@as(?*HttpResponseP3, null), adapter.http_responses_p3.items[1]);
}

test "wasi:http@0.3 (#570): HandleP3Outcome.fromTaskReturnValues decodes Ok branch (disc=0 → wire-decoded handle)" {
    // Round-trip the dispatch-glue's `task.return_values` shape. The
    // guest pushes `[disc, wire_handle, ... padding ...]` for the Ok
    // arm of `result<own<response>, error-code>`. The wire handle is
    // canon-ABI `slot + 1` (#562 / `encodeResourceWireAbi`); the
    // outcome decoder must `decodeResourceWire` it back to the
    // 0-based slot before the host writes the response.
    const testing = std.testing;
    const HandleP3Outcome = WasiCliAdapter.HandleP3Outcome;

    // Ok branch with wire-encoded slot 1 → decoded payload 1.
    const flat_ok = [_]u32{ 0, 2 };
    const out_ok = HandleP3Outcome.fromTaskReturnValues(&flat_ok);
    try testing.expect(out_ok.is_ok);
    try testing.expectEqual(@as(u32, 1), out_ok.payload);

    // Wire 0 (sentinel "no resource") stays 0 after decode — the
    // host's `lookupHttpResponseP3(0)` then surfaces "invalid response
    // handle" cleanly rather than crashing.
    const flat_ok_zero = [_]u32{ 0, 0 };
    const out_ok_zero = HandleP3Outcome.fromTaskReturnValues(&flat_ok_zero);
    try testing.expect(out_ok_zero.is_ok);
    try testing.expectEqual(@as(u32, 0), out_ok_zero.payload);

    // Trailing variant-join padding (wit-bindgen 0.45 produces 7 i32s
    // + 1 i64 = 8 slots for the joined `error-code` arm) is ignored —
    // only `flat[0..2]` is consulted.
    const flat_ok_padded = [_]u32{ 0, 4, 0, 0, 0, 0, 0, 0 };
    const out_ok_padded = HandleP3Outcome.fromTaskReturnValues(&flat_ok_padded);
    try testing.expect(out_ok_padded.is_ok);
    try testing.expectEqual(@as(u32, 3), out_ok_padded.payload); // wire 4 → slot 3
}

test "wasi:http@0.3 (#570): HandleP3Outcome.fromTaskReturnValues decodes Err branch (disc=1 → raw error-code disc)" {
    // The Err arm payload is an `error-code` variant discriminant —
    // a plain i32 with no resource-wire offset. The decoder must NOT
    // wire-decode it; otherwise a guest-returned `HTTP_request_denied`
    // (disc 15) would silently surface as `14` to the host.
    const testing = std.testing;
    const HandleP3Outcome = WasiCliAdapter.HandleP3Outcome;

    const flat_err = [_]u32{ 1, @intFromEnum(HttpErrorCode.HTTP_request_denied) };
    const out = HandleP3Outcome.fromTaskReturnValues(&flat_err);
    try testing.expect(!out.is_ok);
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.HTTP_request_denied)),
        out.payload,
    );

    // Defensive fallbacks: missing payload → internal_error.
    const flat_err_short = [_]u32{1};
    const out_short = HandleP3Outcome.fromTaskReturnValues(&flat_err_short);
    try testing.expect(!out_short.is_ok);
    try testing.expectEqual(
        @as(u32, @intFromEnum(HttpErrorCode.internal_error)),
        out_short.payload,
    );

    // Empty return_values → empty task (task.return never invoked,
    // e.g. the guest trapped before completing) → reported as Err.
    const out_empty = HandleP3Outcome.fromTaskReturnValues(&.{});
    try testing.expect(!out_empty.is_ok);
}

test "wasi:http@0.3 (#570): readIncomingRequestP3FromStream parses an HTTP/1.1 request off a buffered stream" {
    // End-to-end variant of the `createIncomingRequestP3FromHttpBytes`
    // tests above: drives the same wire bytes through
    // `InputStream.fromBuffer` to confirm the stream-read framing
    // (header-end detection, body-length read) keeps the parser
    // happy. Mirrors the live TCP-accept path used by
    // `serveOneHttpConnectionP3` without standing up a real socket.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const wire = "GET /probe HTTP/1.1\r\nHost: example.com\r\nUser-Agent: probe/1\r\n\r\n";
    var input = streams.InputStream.fromBuffer(wire);
    const parsed = try adapter.readIncomingRequestP3FromStream(&ci, &input);
    const rh = parsed.request_handle;
    try testing.expectEqual(@as(u32, 1), rh);
    // HTTP/1.1 default is keep-alive (#583 A5) — the request line
    // bears no `Connection: close` so the keep-alive loop should
    // expect another round-trip.
    try testing.expect(parsed.keep_alive);

    const req = adapter.lookupHttpRequestP3(rh).?;
    try testing.expectEqual(@as(u8, 0), req.method_disc); // GET
    try testing.expectEqualStrings("/probe", req.path_with_query.?);
    try testing.expectEqualStrings("example.com", req.authority.?);

    // Body stream is allocated even for an empty body — write_closed
    // ensures the guest's first read observes EOF without blocking.
    const body_h = req.body_stream_handle.?;
    const body = ci.streams.getPtr(body_h).?;
    try testing.expect(body.write_closed);
    try testing.expectEqual(@as(usize, 0), body.buffer.items.len);
}

// ───────────────────────────────────────────────────────────────────
// wasi:http@0.3.0 incoming-handler robustness (#583 A5) unit tests
// ───────────────────────────────────────────────────────────────────

test "wasi:http@0.3 (#583 A5): keep-alive serves two sequential GETs off one stream" {
    // Two HTTP/1.1 GETs concatenated on the same buffered InputStream
    // — the keep-alive path must parse them as two independent
    // requests without losing any bytes between them. The "live"
    // counterpart of this is `serveOneHttpConnectionP3Stream` running
    // on top of an accepted TCP socket; here we drive
    // `readIncomingRequestP3FromStream` directly across the same
    // underlying stream so the test stays hermetic.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const wire =
        "GET /one HTTP/1.1\r\nHost: example.com\r\n\r\n" ++
        "GET /two HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n";
    var input = streams.InputStream.fromBuffer(wire);
    var reader: WasiCliAdapter.BufferedLineReader = .{ .allocator = adapter.allocator, .stream = &input };
    defer reader.deinit();

    const first = try adapter.readIncomingRequestP3FromBufferedReader(&ci, &reader);
    try testing.expect(first.keep_alive); // default for HTTP/1.1
    const r1 = adapter.lookupHttpRequestP3(first.request_handle).?;
    try testing.expectEqualStrings("/one", r1.path_with_query.?);

    // The keep-alive loop calls `compact` between rounds — exercise
    // the same surface so over-read bytes survive into the next
    // request parse.
    reader.compact();

    const second = try adapter.readIncomingRequestP3FromBufferedReader(&ci, &reader);
    try testing.expect(!second.keep_alive); // honored `Connection: close`
    const r2 = adapter.lookupHttpRequestP3(second.request_handle).?;
    try testing.expectEqualStrings("/two", r2.path_with_query.?);

    // After the second request, the buffer is exhausted — the next
    // attempt must surface as a clean idle-close so the keep-alive
    // loop exits without writing a response.
    const err = adapter.readIncomingRequestP3FromBufferedReader(&ci, &reader);
    try testing.expectError(error.HttpConnectionIdleClose, err);
}

test "wasi:http@0.3 (#583 A5): chunked request body lifts into a single contiguous guest stream" {
    // RFC 7230 §4.1: each chunk is `<hex>\r\n<bytes>\r\n` with a
    // terminating `0\r\n\r\n`. The chunked decoder reassembles the
    // chunks into a contiguous body buffer, then hands the bytes to
    // the guest via the same `stream<u8>` rendezvous a
    // Content-Length-framed body would use. (#583 A5)
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const wire =
        "POST /upload HTTP/1.1\r\n" ++
        "Host: api.example\r\n" ++
        "Transfer-Encoding: chunked\r\n" ++
        "\r\n" ++
        "5\r\nhello\r\n" ++
        "1\r\n \r\n" ++
        "7\r\nworld!\n\r\n" ++
        "0\r\n\r\n";
    var input = streams.InputStream.fromBuffer(wire);
    const parsed = try adapter.readIncomingRequestP3FromStream(&ci, &input);
    const r = adapter.lookupHttpRequestP3(parsed.request_handle).?;
    try testing.expectEqual(@as(u32, 2), r.method_disc); // POST
    try testing.expectEqualStrings("/upload", r.path_with_query.?);
    const body = ci.streams.getPtr(r.body_stream_handle.?).?;
    try testing.expectEqualStrings("hello world!\n", body.buffer.items);
    try testing.expect(body.write_closed);

    // `Transfer-Encoding` header is transport-managed and must be
    // stripped from the guest-visible field set so the guest can't
    // tell whether the request was chunked-framed or
    // Content-Length-framed.
    const fields = adapter.lookupHttpFields(r.headers_handle).?;
    for (fields.entries.items) |entry| {
        try testing.expect(!std.ascii.eqlIgnoreCase(entry.name, "transfer-encoding"));
    }
}

test "wasi:http@0.3 (#583 A5): response with no Content-Length emits Transfer-Encoding: chunked" {
    // Guest writes a `stream<u8>` body without setting a
    // `Content-Length` header — the writer must fall back to chunked
    // encoding (RFC 7230 §3.3.1) so the receiver can parse the body
    // without an explicit length up-front. (#583 A5)
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const ct_name = try testing.allocator.dupe(u8, "content-type");
    const ct_value = try testing.allocator.dupe(u8, "application/octet-stream");
    try fields.entries.append(testing.allocator, .{ .name = ct_name, .value = ct_value });
    const fields_handle = try adapter.pushHttpFields(fields);

    const body_handle = ci.allocAsyncHandle();
    var body: async_mod.AsyncStream = .{ .elem_type_idx = 0 };
    try body.buffer.appendSlice(testing.allocator, "streamed payload");
    body.write_closed = true;
    try ci.streams.put(testing.allocator, body_handle, body);

    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });
    const tx_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, tx_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });

    const resp = try testing.allocator.create(HttpResponseP3);
    resp.* = .{
        .status = 200,
        .headers_handle = fields_handle,
        .body_stream_handle = body_handle,
        .trailers_future_handle = trailers_h,
        .transmission_future_handle = tx_h,
    };
    const resp_handle = try adapter.pushHttpResponseP3(resp);

    var out = streams.OutputStream.toBuffer();
    defer out.deinit(testing.allocator);

    try adapter.writeHttpResponseP3FromHandle(&out, &ci, resp_handle, true);

    const written = out.getBufferContents();
    try testing.expect(std.mem.startsWith(u8, written, "HTTP/1.1 200 OK\r\n"));
    try testing.expect(std.mem.indexOf(u8, written, "Transfer-Encoding: chunked\r\n") != null);
    try testing.expect(std.mem.indexOf(u8, written, "Connection: keep-alive\r\n") != null);
    // No `Content-Length` is emitted when the body is chunked.
    try testing.expect(std.mem.indexOf(u8, written, "Content-Length:") == null);
    // Single chunk for "streamed payload" (16 bytes = 0x10).
    try testing.expect(std.mem.indexOf(u8, written, "\r\n10\r\nstreamed payload\r\n") != null);
    try testing.expect(std.mem.endsWith(u8, written, "0\r\n\r\n"));
}

test "wasi:http@0.3 (#583 A5): guest trailers ride through the chunked trailer block" {
    // The trailers future's payload encodes `some(<fields_handle>)`
    // as canon-ABI `option<own<trailers>>` — 1-byte discriminant +
    // 3 bytes padding + 4 byte handle. When non-empty, the writer
    // emits each trailer entry after the terminating `0\r\n` chunk.
    // (#583 A5)
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    // Response headers (no Content-Length → chunked path will fire
    // automatically). The trailer field set sits in a separate
    // `HttpFields` slot referenced by the trailers future payload.
    const headers_fields = try testing.allocator.create(HttpFields);
    headers_fields.* = .{};
    const headers_handle = try adapter.pushHttpFields(headers_fields);

    const trailer_fields = try testing.allocator.create(HttpFields);
    trailer_fields.* = .{};
    const t_name = try testing.allocator.dupe(u8, "x-custom");
    const t_value = try testing.allocator.dupe(u8, "foo");
    try trailer_fields.entries.append(testing.allocator, .{ .name = t_name, .value = t_value });
    const trailer_fields_handle = try adapter.pushHttpFields(trailer_fields);

    const body_handle = ci.allocAsyncHandle();
    var body: async_mod.AsyncStream = .{ .elem_type_idx = 0 };
    try body.buffer.appendSlice(testing.allocator, "abc");
    body.write_closed = true;
    try ci.streams.put(testing.allocator, body_handle, body);

    // Simulate what a `future.write` of `some(<handle>)` would have
    // deposited in the trailers future's `payload` (8 bytes:
    // 1-byte discriminant `1` for `some`, 3 padding bytes, then
    // the u32 handle in little-endian).
    const trailers_payload = try testing.allocator.alloc(u8, 8);
    trailers_payload[0] = 1;
    trailers_payload[1] = 0;
    trailers_payload[2] = 0;
    trailers_payload[3] = 0;
    std.mem.writeInt(u32, trailers_payload[4..8], trailer_fields_handle, .little);

    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0,
        .state = .ready,
        .write_closed = true,
        .payload = trailers_payload,
    });
    const tx_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, tx_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });

    const resp = try testing.allocator.create(HttpResponseP3);
    resp.* = .{
        .status = 200,
        .headers_handle = headers_handle,
        .body_stream_handle = body_handle,
        .trailers_future_handle = trailers_h,
        .transmission_future_handle = tx_h,
    };
    const resp_handle = try adapter.pushHttpResponseP3(resp);

    var out = streams.OutputStream.toBuffer();
    defer out.deinit(testing.allocator);

    try adapter.writeHttpResponseP3FromHandle(&out, &ci, resp_handle, false);

    const written = out.getBufferContents();
    // `Trailer:` declaration header announces the names that will
    // appear in the trailer block (RFC 7230 §4.4).
    try testing.expect(std.mem.indexOf(u8, written, "Trailer: x-custom\r\n") != null);
    try testing.expect(std.mem.indexOf(u8, written, "Transfer-Encoding: chunked\r\n") != null);
    // Single chunk for "abc" (3 = 0x3), then the trailer block.
    try testing.expect(std.mem.indexOf(u8, written, "\r\n3\r\nabc\r\n") != null);
    try testing.expect(std.mem.endsWith(u8, written, "0\r\nx-custom: foo\r\n\r\n"));
}

test "wasi:http@0.3 (#583 A5): oversize header section short-circuits with 431 without dispatch" {
    // RFC 7230 §3.2.5 doesn't mandate a limit, but in practice 16
    // KiB matches Wasmtime's default. The wamr server returns 431
    // before consulting the guest dispatcher so a hostile client
    // can't trigger expensive lifting of an attacker-supplied
    // header section. (#583 A5)
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    // Build a request whose header block alone is ~24 KiB — well
    // past `max_http_p3_header_section_bytes` (16 KiB) but still
    // small enough that the test stays under the std.testing
    // allocator's bookkeeping bound.
    var wire: std.ArrayListUnmanaged(u8) = .empty;
    defer wire.deinit(testing.allocator);
    try wire.appendSlice(testing.allocator, "GET / HTTP/1.1\r\nHost: example.com\r\n");
    var i: usize = 0;
    while (i < 200) : (i += 1) {
        var name_buf: [40]u8 = undefined;
        const line = try std.fmt.bufPrint(&name_buf, "X-Pad-{d:0>4}: ", .{i});
        try wire.appendSlice(testing.allocator, line);
        try wire.appendSlice(testing.allocator, "A" ** 100);
        try wire.appendSlice(testing.allocator, "\r\n");
    }
    try wire.appendSlice(testing.allocator, "\r\n");
    try testing.expect(wire.items.len > max_http_p3_header_section_bytes);

    var input = streams.InputStream.fromBuffer(wire.items);
    const err = adapter.readIncomingRequestP3FromStream(&ci, &input);
    try testing.expectError(error.HttpRequestHeaderTooLarge, err);

    // No P3 request resource may have been registered — the slot-0
    // reservation only happens on a successful push, so the table
    // is still empty after a parse short-circuit.
    var nonzero_request_slots: usize = 0;
    for (adapter.http_requests_p3.items) |slot| {
        if (slot != null) nonzero_request_slots += 1;
    }
    try testing.expectEqual(@as(usize, 0), nonzero_request_slots);

    // statusForRequestReadError maps the parse error onto 431 so the
    // accept loop emits `HTTP/1.1 431 Request Header Fields Too
    // Large` without dispatching the guest.
    try testing.expectEqual(@as(u16, 431), statusForRequestReadError(error.HttpRequestHeaderTooLarge));
}

test "wasi:http@0.3 (#583 A5): chunked response with Content-Length header still uses identity framing" {
    // When the guest sets `Content-Length`, the writer must keep
    // identity framing — chunked is only the fallback for
    // unknown-length bodies. Mirrors the wasi-testsuite
    // `http-service` `GET /` arm which sets content-length
    // explicitly for the `hey\n` body.
    const testing = std.testing;
    var adapter = WasiCliAdapter.init(testing.allocator);
    defer adapter.deinit();
    var ci = p3HttpTestCi(testing.allocator);
    defer p3HttpTestCiDeinit(&ci);

    const fields = try testing.allocator.create(HttpFields);
    fields.* = .{};
    const cl_name = try testing.allocator.dupe(u8, "content-length");
    const cl_value = try testing.allocator.dupe(u8, "5");
    try fields.entries.append(testing.allocator, .{ .name = cl_name, .value = cl_value });
    const fields_handle = try adapter.pushHttpFields(fields);

    const body_handle = ci.allocAsyncHandle();
    var body: async_mod.AsyncStream = .{ .elem_type_idx = 0 };
    try body.buffer.appendSlice(testing.allocator, "hello");
    body.write_closed = true;
    try ci.streams.put(testing.allocator, body_handle, body);

    const trailers_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, trailers_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });
    const tx_h = ci.allocAsyncHandle();
    try ci.futures.put(testing.allocator, tx_h, .{
        .elem_type_idx = 0, .state = .ready, .write_closed = true,
    });

    const resp = try testing.allocator.create(HttpResponseP3);
    resp.* = .{
        .status = 200,
        .headers_handle = fields_handle,
        .body_stream_handle = body_handle,
        .trailers_future_handle = trailers_h,
        .transmission_future_handle = tx_h,
    };
    const resp_handle = try adapter.pushHttpResponseP3(resp);

    var out = streams.OutputStream.toBuffer();
    defer out.deinit(testing.allocator);

    try adapter.writeHttpResponseP3FromHandle(&out, &ci, resp_handle, true);

    const written = out.getBufferContents();
    try testing.expect(std.mem.startsWith(u8, written, "HTTP/1.1 200 OK\r\n"));
    try testing.expect(std.mem.indexOf(u8, written, "Content-Length: 5\r\n") != null);
    try testing.expect(std.mem.indexOf(u8, written, "Transfer-Encoding:") == null);
    try testing.expect(std.mem.indexOf(u8, written, "Connection: keep-alive\r\n") != null);
    try testing.expect(std.mem.endsWith(u8, written, "\r\n\r\nhello"));
}

test "wasi:http@0.3 (#583 A5): httpRequestHeaderInfoFromBlock detects keep-alive default and Connection: close" {
    // Unit-tests the small header-info helper so the upstream
    // parsing surface stays orthogonal to the streaming reader.
    const testing = std.testing;

    const default_keepalive = "GET / HTTP/1.1\r\nHost: x\r\n\r\n";
    const info1 = try WasiCliAdapter.httpRequestHeaderInfoFromBlock(default_keepalive);
    try testing.expect(info1.keep_alive);

    const explicit_close = "GET / HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n";
    const info2 = try WasiCliAdapter.httpRequestHeaderInfoFromBlock(explicit_close);
    try testing.expect(!info2.keep_alive);

    const explicit_keepalive = "GET / HTTP/1.1\r\nConnection: keep-alive\r\nHost: x\r\n\r\n";
    const info3 = try WasiCliAdapter.httpRequestHeaderInfoFromBlock(explicit_keepalive);
    try testing.expect(info3.keep_alive);

    const http10_default = "GET / HTTP/1.0\r\nHost: x\r\n\r\n";
    const info4 = try WasiCliAdapter.httpRequestHeaderInfoFromBlock(http10_default);
    try testing.expect(!info4.keep_alive);

    const http10_opt_in = "GET / HTTP/1.0\r\nHost: x\r\nConnection: keep-alive\r\n\r\n";
    const info5 = try WasiCliAdapter.httpRequestHeaderInfoFromBlock(http10_opt_in);
    try testing.expect(info5.keep_alive);

    const chunked = "POST / HTTP/1.1\r\nTransfer-Encoding: chunked\r\n\r\n";
    const info6 = try WasiCliAdapter.httpRequestHeaderInfoFromBlock(chunked);
    try testing.expect(info6.body_kind == .chunked);

    const cl = "POST / HTTP/1.1\r\nContent-Length: 7\r\n\r\n";
    const info7 = try WasiCliAdapter.httpRequestHeaderInfoFromBlock(cl);
    try testing.expectEqual(@as(usize, 7), info7.body_kind.content_length);
}

